(window.GIM_TS=window.GIM_TS||{})["Bava Metzia.7"]={"from":168,"a":[["\u0003חכים יתקרי\u0004 \u0005[חכם\u0006 ורופא \u0005ייקרא],\u0006 אבל \u0003\"רבי\" לא יתקרי\u0004 \u0005[ייקרא],\u0006 \u0003ואסו\u0004 \u0005[ורפואתו]\u0006 של \u0003רבי על ידו תהא.\u0004 ועוד ראיתי שם: \u0003רבי ור' נתן\u0004 — \u0003סוף משנה,\u0004 שהם אחרוני התנאים, עורכי המשנה. \u0003רב אשי ורבינא\u0004 — \u0003סוף הוראה,\u0004 כלומר, סוף תקופת האמוראים שמתקופת התלמוד.","\u0003וסימנך\u0004 \u0005[וסימן לכך],\u0006 מה שנאמר: \u0003\"עד אבוא אל מקדשי אל אבינה לאחריתם\"\u0004 (תהלים עג, יז) \"מקדשי\" רומז לאשי, אבינא הוא רמז לרבינא (ששמו המלא הוא: רב אבינא) שהם באחריתם של ימי התלמוד.","ועוד בשבח החכמים. \u0003אמר רב כהנא: אישתעי\u0004 \u0005[אמר,\u0006 סיפר\u0005],\u0006 \u0003לי רב חמא בר ברתיה\u0004 \u0005[בן בתו]\u0006 של \u0003חסא:\u0004 \u0003רבה בר נחמני אגב\u0004 גזירת \u0003שמדא\u0004 \u0005[שמד]\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005].\u0006 כיצד — \u0003אכלו ביה קורצא בי מלכא\u0004 \u0005[הלשינו\u0006 עליו \u0005בבית המלך],\u0006 \u0003אמרו: איכא חד גברא ביהודאי דקא\u0004 \u0005[יש אדם אחד בין היהודים שהוא]\u0006 \u0003מבטל תריסר אלפי גברי\u0004 \u0005[שנים עשר אלף אנשים]\u0006 \u0003מישראל ירחא בקייטא וירחא בסתוא מכרגא דמלכא\u0004 \u0005[חודש בקיץ וחודש בחורף ממיסי המלך],\u0006 שכן קהל גדול זה היה בא ללמוד בישיבתו של רבה בירחי כלה (באדר ובאלול), והאשימו אותו שהוא גורם שיבטלו אותם האנשים מעבודתם.","\u0003שדרו פריסתקא דמלכא בתריה\u0004 \u0005[שלחו שליח המלך אחריו]\u0006 \u0003ולא אשכחיה\u0004 \u0005[מצאהו].\u0006 \u0003ערק ואזל\u0004 \u0005[ברח\u0006 רבה \u0005והלך]\u0006 \u0003מפומבדיתא לאקרא,\u0004 ו\u0003מאקרא לאגמא, ומאגמא לשחין, ומשחין לצריפא, ומצריפא לעינא דמים\u0004 \u0005[לעין מים],\u0006 \u0003ומעינא דמים\u0004 \u0005[ומעין מים]\u0006 ברח \u0003לפומבדיתא.\u0004 \u0003בפומבדיתא אשכחיה\u0004 \u0005[מצאהו].\u0006 וכיצד אירע הדבר — \u0003איקלע פריסתקא דמלכא לההוא אושפיזא\u0004 \u0005[הזדמן שליח המלך למארחו]\u0006 של \u0003רבה.\u0004 מה עשו — \u0003קריבו תכא קמיה ואשקוהו תרי כסי, ודליוה לתכא מקמיה הדר פרצופיה לאחוריה\u0004 \u0005[הביאו שולחן לפניו והשקו אותו שתי כוסות, והוציאו את השולחן מלפניו,\u0006 ו\u0005חזר פרצופו לאחוריו],\u0006 שנעשה בו נס זה בשל רבה.","\u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי נעביד ליה\u0004 \u0005[מה נעשה לו]?\u0006 הלא \u0003גברא דמלכא\u0004 \u0005[איש של המלך]\u0006 \u0003הוא\u0004 ואי אפשר להשאירו כך! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קריבו תכא לקמיה, ואשקוהו חד כסא, ודליוהו לתכא מקמיה ולתסי\u0004 \u0005[קרבו את השולחן לפניו, והשקוהו כוס אחד, והוציאו את השולחן מלפניו ויתרפא].\u0006 \u0003עבדו ליה הכי ואתסי\u0004 \u0005[עשו לו כך והתרפא].\u0006 \u0003אמר\u0004 אותו שליח: \u0003מידע ידענא דגברא דקא בעינא הכא\u0004 \u0005[יודע אני שהאיש שאני מחפש כאן]\u0006 \u0003הוא,\u0004 שבוודאי בשלו אירעו בי דברים מופלאים אלה. \u0003בחיש אבתריה ואשכחיה\u0004 \u0005[חיפש אחריו ומצאו].\u0006 \u0003אמר\u0004 השליח: \u0003אזלינא מהא\u0004 \u0005[הולך אני מכאן]\u0006 ואיני מסגיר את רבה, ואפילו \u0003אי מקטל קטלו לההוא גברא\u0004 \u0005[אם יהרגו את האיש הזה],\u0006 כלומר, אותי, — \u0003לא מגלינא\u0004 \u0005[אגלה],\u0006 \u0003ואי נגידי מנגדין ליה\u0004 \u0005[ו\u0006אולם \u0005אם יכו אותי]\u0006 — \u0003מגלינא\u0004 \u0005[אגלה],\u0006 שלא אוכל לעמוד בעינויים.","\u0003אתיוהו לקמיה, עייליה לאדרונא וטרקיה לבבא באנפיה\u0004 \u0005[הביאוהו\u0006 את רבה \u0005לפניו. הכניסו למסדרון\u0006 קטן \u0005וסגר את הדלת\u0006 לפניו\u0005].\u0006 \u0003בעא רחמי, פרק אשיתא ערק ואזיל לאגמא\u0004 \u0005[ביקש רחמים, התפרק הקיר, ברח והלך לאגם].\u0006 \u0003הוה יתיב אגירדא דדקולא וקא גריס\u0004 \u0005[היה יושב על גדם של דקל ולומד]\u0006 לעצמו. ובאותה שעה \u0003קא מיפלגי במתיבתא דרקיעא\u0004 \u0005[היו נחלקים\u0006 החכמים \u0005בישיבה\u0006 של מעלה \u0005ברקיע]\u0006 בהלכה זו; בדיני נגע הצרעת נאמר שאם \u0003בהרת\u0004 שבעור הבשר \u0003קודמת לשער לבן\u0004 הצומח במקום הבהרת — הרי זה נגע \u0003טמא,\u0004 ואם \u0003שער לבן קודם לבהרת\u0004 — \u0003טהור.\u0004","ואולם מה הדין אם היה \u0003ספק\u0004 איזה מהם קדם — \u0003הקדוש ברוך הוא אומר: טהור, וכולהו מתיבתא דרקיעא אמרי\u0004 \u0005[וכל\u0006 בני \u0005הישיבה של מעלה אומרים]:\u0006 \u0003טמא. ואמרי\u0004 \u0005[ואמרו]:\u0006 \u0003מאן נוכח\u0004 \u0005[מי יוכיח],\u0006 כלומר, מי יכריע בדבר? והסכימו כי \u0003נוכח\u0004 \u0005[יוכיח]\u0006 \u0003רבה בר נחמני.\u0004 ש\u0003אמר רבה בר נחמני: אני יחיד בנגעים, אני יחיד באהלות,\u0004 שהיה גדול מאד בידיעתו בהלכות אלה.","\u0003שדרו שליחא בתריה\u0004 \u0005[שלחו\u0006 משמים \u0005שליח אחריו\u0006 לקחת את נשמתו\u0005].\u0006 \u0003לא הוה מצי\u0004 \u0005[היה יכול]\u0006 \u0003מלאך המות למקרב ליה\u0004 \u0005[להתקרב,\u0006 לגשת \u0005אליו],\u0006 \u0003מ\u0004כיון ש\u0003לא הוה קא פסיק פומיה מגרסיה\u0004 \u0005[פסק פיו מללמוד].\u0006 \u0003אדהכי נשב זיקא ואויש ביני קני\u0004 \u0005[בינתיים נשבה הרוח ונשמע רעש בין הקנים],\u0006 \u0003סבר\u0004 \u0005[חשב]\u0006 רבה שוודאי \u0003גונדא דפרשי הוא\u0004 \u0005[קבוצת פרשים היא].\u0006 \u0003אמר: תינח נפשיה דההוא גברא,\u0004 \u0005[תנוח נפשו,\u0006 ימות, \u0005אותו האיש,\u0006 רבה\u0005],\u0006 \u0003ולא ימסר בידא דמלכותא\u0004 \u0005[\u0006\u0005בידי המלכות].\u0006 ואז יכול היה המלאך ליטול את נשמתו.","\u0003כי הוה קא ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003אמר\u0004 רבה בתשובה לשאלה בדבר הנגע: \u0003טהור, טהור. יצאת\u0004 (יצאה) \u0003בת קול\u0004 ממרום \u0003ואמרה: אשריך רבה בר נחמני שגופך טהור, ויצאתה\u0004 (יצאה) \u0003נשמתך בטהור. נפל פתקא מרקיעא\u0004 \u0005[פתק מן השמים]\u0006 בישיבה \u0003בפומבדיתא,\u0004 עליו היה כתוב: \u0003רבה בר נחמני נתבקש בישיבה של מעלה. נפקו\u0004 \u0005[יצאו]\u0006 \u0003אביי ורבא וכולהו רבנן לאיעסוקי ביה\u0004 \u0005[וכל החכמים להתעסק בו,\u0006 בקבורתו\u0005].\u0006 \u0003לא הוו ידעי דוכתיה\u0004 \u0005[היו יודעים את מקומו].\u0006 \u0003אזלו לאגמא חזו צפרי דמטללי וקיימי\u0004 \u0005[הלכו לאגם ראו צפורים העומדות ומטילות צל],\u0006 \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003שמע מינה התם\u0004 \u0005[נלמד מכאן\u0006 כי \u0005שם]\u0006 \u0003הוא\u0004 מצוי. ואכן מצאוהו שם.","\u0003ספדוהו תלתא יומי ותלתא לילותא\u0004 \u0005[שלושה ימים ושלושה לילות].\u0006 \u0003נפל פתקא\u0004 \u0005[פתק]\u0006 מן השמים שנכתב בו: \u0003כל הפורש\u0004 מן ההספד \u0003יהא בנידוי,\u0004 שעדיין אין זה מספיק כפי כבודו. \u0003ספדוהו\u0004 עוד עד תום \u0003שבעה יומי\u0004 \u0005[ימים]\u0006 לפטירתו. \u0003נפל פתקא\u0004 \u0005[פתק]\u0006 שנכתב בו \u0005:\u0006 \u0003לכו לביתכם לשלום.\u0004","מספרים: \u0003ההוא יומא דנח נפשיה דלייה זעפא ודרי לההוא טייעא כי רכיב גמלא מהאי גיסא\u0004 \u0005[אותו יום שנחה נפשו\u0006 של רבה היתה רוח סערה \u0005ונשאה הרוח ערבי אחד כאשר היה רכוב על גמל מצד אחד]\u0006 של \u0003נהר פפא ושדייה בהך גיסא\u0004 \u0005[והשליכתו בצד האחר].\u0006 \u0003אמר: מאי האי\u0004 \u0005[מה זה]\u0006 שקורה כאן? \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003רבה בר נחמני. אמר לפניו: רבונו של עולם! כולי עלמא דידך\u0004 \u0005[כל העולם שלך]\u0006 \u0003הוא, ורבה בר נחמני דידך\u0004 \u0005[שלך],\u0006 \u0003את\u0004 \u0005[אתה]\u0006 של \u0003רבה ורבה דידך\u0004 \u0005[שלך]\u0006 — \u0003אמאי קא מחרבת ליה לעלמא\u0004 \u0005[מדוע אתה מחריב אותו, את לעולם]?\u0006 \u0003נח זעפא\u0004 \u0005[נחה הרוח].\u0006","וכדי לסיים את המעשים שהתחלנו בהם, שדובר באותם חכמים שהיו בריאי בשר, מספרים: \u0003ר' שמעון בן חלפתא בעל בשר הוה\u0004 \u0005[היה].\u0006 \u0003יומא חד הוה חמימא ליה, הוה סליק ויתיב אשינא דטורא\u0004 \u0005[יום אחד היה חם לו\u0006 ביותר ו\u0005היה עולה ויושב על שן ההר]\u0006 כדי לצנן עצמו מעט. \u0003אמר לה לברתיה\u0004 \u0005[לבתו]:\u0006 \u0003בתי, הניפי עלי במניפא, ואני אתן ליך\u0004 \u0005[לך]\u0006 במתנה \u0003ככרין\u0004 של \u0003נרד\u0004 (בושם). \u0003אדהכי נשבא זיקא\u0004 \u0005[בינתיים נשבה רוח],\u0006 \u0003אמר: כמה ככרין\u0004 של \u0003נרד\u0004 יש \u0003למרי דיכי\u0004 \u0005[לבעליה של\u0006 רוח \u0005זו].\u0006","ומעתה חוזרים אנו לפירושה של המשנה. שנינו שם בענין הזנת הפועלים העובדים לבעל הבית: \u0003הכל כמנהג המדינה.\u0004 ושואלים: לשון \u0003\"הכל\"\u0004 ששנינו \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה],\u0006 מה עוד בכלל הזה יתר על מה שאמרנו? ומשיבים: \u0003לאתויי באתרא דנהיגי מכרך ריפתא ומשתה אנפקא\u0004 \u0005[להביא,\u0006 להוסיף, \u0005במקום שנוהגים\u0006 הפועלים \u0005לאכול לחם ולשתות יין].\u0006 \u0003דאי אמר להו קדימו ואייתי לכו\u0004 \u0005[שאם\u0006 רוצה \u0005אומר הקדימו\u0006 בבוקר יותר \u0005ואביא לכם]\u0006 מאכל ומשתה זה, ולא תבטלו מזמן העבודה. \u0003אמרו לו: לא כל כמינך\u0004 \u0005[לא הכל ממך]\u0006 אין אתה רשאי, ואינך יכול לשנות מן המנהג.","שנינו במשנה: \u0003מעשה ברבן יוחנן בן מתיא שאמר לבנו צא ושכור\u0004 לנו פועלים ושכר הבן פועלים, ואמר לו אביו להתנות במפורש מה הוא מאכיל להם. ומקשים: הלא כיון שנאמר במשנה שהכל כמנהג המדינה, הרי זה \u0003מעשה לסתור!\u0004 שהרי מן המעשה אפשר ללמוד שלא די במנהג המדינה! ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה המשנה וכך היא שנויה],\u0006 כך יש לשנותה: \u0003ואם פסק להן מזונות\u0004"],["\u0003ריבה להן,\u0004 שכיון שלא הסתפק בשכירתם היתה כוונתו להוסיף להם מזונות יותר על המנהג.","\u0003ומעשה נמי\u0004 \u0005[גם כן]\u0006 \u0003בר' יוחנן בן מתיא,\u0004 כפי שנאמר במשנה, \u0003שאמר לבנו: צא שכור לנו פועלים, הלך ופסק להן מזונות, וכשבא אצל אביו אמר לו בני אפילו אתה עושה להן,\u0004 לפועלים ששכרת, \u0003כסעודת שלמה בשעתו לא יצאת ידי חובתך עמהן,\u0004 לפי \u0003שהן בני אברהם יצחק ויעקב.\u0004 ושואלים: \u0003למימרא דסעודתא\u0004 \u0005[האם לומר\u0006 ללמוד מכאן \u0005שסעודתו]\u0006 של \u0003אברהם אבינו\u0004 היתה \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 \u0003מ\u0004זו של \u0003שלמה?\u0004 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויהי לחם שלמה ליום אחד שלשים כר סלת וששים כר קמח. עשרה בקר בראים ועשרה בקר רעי ומאה צאן לבד מאיל וצבי ויחמור וברברים אבוסים\"\u0004 (מלכים א' ה, ב–ג)! \u0003ואמר גוריון בן אסטיון משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הללו,\u0004 כל קמח שנאמר הוא \u0003לעמילן של טבחים\u0004 ששמים בקדרה כדי שידבק בו הקצף שעל גבי התבשיל. \u0003ור' יצחק אמר: הללו לציקי קדירה,\u0004 לבצק שמטגנים עמו את שיירי האוכל.","\u0003ואמר ר' יצחק: אלף נשים היו לשלמה, כל אחת ואחת עשתה לו בביתה כך. מאי טעמא\u0004 \u0005[מה טעם]\u0006 — \u0003זו סבורה שמא אצלי סועד היום, וזו סבורה שמא אצלי סועד היום. ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003אברהם כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואל הבקר רץ אברהם ויקח בן בקר רך וטוב\"\u0004 (בראשית יח, ז). \u0003ואמר רב יהודה אמר רב: \"בן בקר\"\u0004 — הרי \u0003אחד, \"רך\"\u0004 — \u0003שנים, \"וטוב\"\u0004 — \u0003שלשה,\u0004 והרי זה פחות מסעודתו של שלמה!","ומתרצים: \u0003התם תלתא תורי לתלתא גברי\u0004 \u0005[שם\u0006 הכין \u0005שלושה שוורים לשלשה אנשים],\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 בשלמה היו נשיו מכינות סעודה \u0003לכל ישראל ויהודה, שנאמר: \"יהודה וישראל רבים כחול אשר על שפת הים\u0004 לרוב אוכלים ושותים ושמחים","\u0003\"\u0004(מלכים א' ד, כ). כיון שהוזכרו ברבורים אבוסים שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ברבורים אבוסים\"? אמר רב:\u0004 מדובר באלה \u0003שאובסים\u0004 (מאכילים) \u0003אותם בעל כרחם. ושמואל אמר: שאבוסים ועומדים מאליהם. ור' יוחנן אמר: מביאין תור ממרעיתו\u0004 \u0005[שור מהמרעה שלו]\u0006 שמעולם \u0003לא אניס\u0004 \u0005[נאנס\u0006 לעבוד\u0005],\u0006 \u0003ותרנגולת מאשפתה\u0004 ש\u0003לא אניסא\u0004 \u0005[נאנסה\u0006 לגדל אפרוחים\u0005],\u0006 ומהם היו מכינים את סעודת שלמה.","אגב כך מביאים את מה ש\u0003אמר ר' יוחנן: מובחר שבבהמות\u0004 לענין אכילה — \u0003שור, מובחר שבעופות\u0004 — \u0003תרנגולת. אמר אמימר:\u0004 באיזו תרנגולת מדובר — \u0003זגתא אוכמתא בי בטניתא דמשתכחא ביני עצרי\u0004 \u0005[תרנגולת שחורה בעלת כרס הנמצאת בין הגיתות],\u0006 שיש לה אוכל מרובה, \u0003דלא מציא פסיא קניא\u0004 \u0005[שאיננה יכולה לפסוע\u0006 כדי מרחק של \u0005קנה\u0006 מרוב שומנה\u0005].\u0006","כיון שדובר בענין סעודתו של אברהם אבינו, מרחיבים את הדיבור בענין זה. נאמר: \u0003\"ואל הבקר רץ אברהם\u0004 ויקח בן בקר רך וטוב\u0003\"\u0004 (בראשית יח, ז). \u0003אמר רב יהודה אמר רב: \"בן בקר\"\u0004 — \u0003אחד, \"רך\"\u0004 — \u0003שנים, \"וטוב\"\u0004 — \u0003שלשה,\u0004 ושואלים: \u0003ואימא חד, כדאמרי אינשי\u0004 \u0005[ואמור שהיה\u0006 זה \u0005רק אחד, כמו שאומרים בני אדם]:\u0006 \u0003רכיך וטב\u0004 \u0005[רך וטוב]\u0006 ולא שהיו אלה עגלים אחדים!","ועונים: \u0003אם כן\u0004, \u0003לכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003\"רך טוב\", מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 הפסיק וכתב \u0003\"וטוב\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר \u0003לדרשה\u0004, שאין מדובר באותו בן בקר. ושואלים: אם כן, \u0003אימא תרי\u0004 \u0005[אמור\u0006 שהיו רק \u0005שנים]\u0006 ולא שלושה! ומשיבים: \u0003מ\u0004כיון ש\u0003\"טוב\"\u0004 בא \u0003לדרשה\u0004 להוסיף עוד אחד, \u0003\"רך\" נמי\u0004 \u0005גם כן\u0006 בא \u0003לדרשה,\u0004 להוסיף אף הוא \u0005אחד.\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה בר עולא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב הושעיא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב נתן בר' הושעיא:\u0004 הלא נאמר \u0003\"ויתן אל הנער וימהר לעשות אתו\",\u0004 משמע שרק אחד היה! ומשיבים: \u0003כל חד וחד יהביה\u0004 \u0005[אחד ואחד\u0006 מן השוורים \u0005נתנו]\u0006 \u0003לנער חד\u0004 \u0005[אחד].\u0006 ומקשים עוד: והרי נאמר \u0003\"ויקח חמאה וחלב ובן הבקר אשר עשה ויתן לפניהם\"\u0004 (שם), משמע שהיה רק בן בקר אחד! ומשיבים: \u0003דקמא קמא דמטיא, אייתי לקמייהו\u0004 \u0005[שראשון ראשון שהגיע\u0006 מוכן, \u0005הביא לפניהם].\u0006","ושואלים: \u0003ולמה לי תלתא\u0004 \u0005[לו שלושה\u0006 שוורים\u0005]?\u0006 \u0003תסגי בחד\u0004 \u0005[שיסתפק באחד],\u0006 שהרי שלושה אנשים די להם והותר בשור אחד! \u0003אמר רב חנן בר רבא:\u0004 שחט שלשה \u0003כדי להאכילן שלש לשונות\u0004 (שהם החלק המובחר שבבשר) \u0003בחרדל.\u0004 אגב ענין זה \u0003אמר ר' תנחום בר חנילאי: לעולם אל ישנה אדם מן המנהג\u0004 הנהוג במקום, \u0003שהרי משה עלה למרום\u0004 — \u0003ולא אכל לחם, מלאכי השרת ירדו למטה\u0004 — \u0003ואכלו לחם.\u0004 ושואלים: \u0003ואכלו סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר?! כיצד יכול מלאך לאכול? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003נראו כמי שאכלו ושתו.\u0004 ועוד מה שלמדים מסעודת אברהם.","\u0003אמר רב יהודה אמר רב: כל מה שעשה אברהם\u0004 אבינו \u0003למלאכי השרת בעצמו, עשה הקדוש ברוך הוא לבניו\u0004 של אברהם, לבני ישראל, אף הוא \u0003בעצמו, וכל מה שעשה אברהם על ידי שליח\u0004 — \u0003עשה הקדוש ברוך הוא לבניו\u0004 של אברהם \u0003על ידי שליח.\u0004 כיצד?","נאמר \u0003\"ואל הבקר רץ אברהם\"\u0004 (בראשית יח, ז), וכנגד זה נאמר \u0003\"ורוח נסע מאת ה'\u0004 ויגז שלוים מן הים\u0003\"\u0004 (במדבר יא, לא). נאמר באברהם \u0003\"ויקח חמאה וחלב\"\u0004 (בראשית יח, ח), וכנגד זה נאמר \u0003\"הנני ממטיר לכם לחם מן השמים\"\u0004 (שמות טז, ד).","נאמר באברהם \u0003\"והוא עמד עליהם תחת העץ\u0004 ויאכלו\u0003\"\u0004 (בראשית שם), ונאמר כנגדו \u0003\"הנני עמד לפניך שם על הצור\u0004 בחורב והכית בצור ויצאו ממנו מים\u0003\"\u0004 (שמות יז, ו). נאמר \u0003\"ואברהם הלך עמם לשלחם\"\u0004 (בראשית שם, טז), וכנגדו נאמר \u0003\"וה' הלך לפניהם יומם\"\u0004 (שמות יג, כא).","והיו דברים שעשה אברהם על ידי שליח: נאמר כאן \u0003\"יקח נא מעט מים\"\u0004 (בראשית שם ד), ונאמר כנגדו למשה, כשליח ה', \u0003\"והכית בצור ויצאו ממנו מים ושתה העם\"\u0004 (שמות יז, ו).","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דברי \u0003ר' חמא בר' חנינא.\u0004 ש\u0003אמר ר' חמא בר' חנינא, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 \u0003בשכר שלשה\u0004 בני בקר ששחט עבור המלאכים \u0003זכו\u0004 בניו \u0003לשלשה\u0004 מתנות שניתנו להם מאוחר יותר בהיותם במדבר. כיצד? \u0003בשכר\u0004 שנתן \u0003חמאה וחלב\u0004 — \u0003זכו\u0004 ישראל \u0003למן, בשכר \"והוא עמד עליהם\"\u0004 — \u0003זכו לעמוד הענן, בשכר \"יקח נא מעט מים\"\u0004 — \u0003זכו לבארה של מרים,\u0004 ואינו מחלק בין מה שעשה אברהם בעצמו ועל ידי שליח.","ועוד בפירוש כתובים אלה; נאמר \u0003\"יקח נא מעט מים ורחצו רגליכם\"\u0004 — \u0003אמר ר' ינאי בר' ישמעאל, אמרו לו: וכי בערביים חשדתנו, שהם משתחוים לאבק רגליהם,\u0004 שלכן רצונך שנרחץ רגלינו ולא נשתחוה לאבק, הלא \u0003כבר יצא ממנו ישמעאל\u0004 שהרי בני ישמעאל הם שעתידים לעשות כך.","ועוד באותו ענין: נאמר \u0003\"וירא אליו ה' באלני ממרא והוא ישב פתח האהל כחם היום\"\u0004 (בראשית יח, א), ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 של \u0003\"כחם היום\"? אמר ר' חמא בר' חנינא: אותו היום יום שלישי של מילה של אברהם היה, ובא הקדוש ברוך הוא לשאול באברהם\u0004 כדרך שמבקרים את החולה, \u0003הוציא הקדוש ברוך הוא חמה מנרתיקה,\u0004 שעשה שתלהט החמה ביותר באותו יום \u0003כדי שלא יטריח אותו צדיק\u0004 עצמו \u0003באורחים\u0004 ויוכל לנוח מעט. ואולם אברהם רצה מאד לקיים מצות הכנסת אורחים.","\u0003שדריה\u0004 \u0005[שלחו]\u0006 את \u0003אליעזר\u0004 עבדו \u0003למיפק לברא\u0004 \u0005[לצאת לחוץ]\u0006 לראות אם יש אורחים. \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003ולא אשכח\u0004 \u0005[מצא],\u0006 \u0003אמר\u0004 אלו אברהם: אני \u0003לא מהימנא\u0004 \u0005[מאמין]\u0006 \u0003לך.\u0004 \u0003היינו דאמרי תמן\u0004 \u0005[\u0006ו\u0005זהו שאמרו שם,\u0006 בארץ ישראל\u0005]:\u0006 \u0003לית הימנותא בעבדי\u0004 \u0005[אין נאמנות בעבדים].\u0006 \u0003נפק איהו חזייה\u0004 \u0005[יצא הוא וראהו]\u0006 \u0003להקדוש ברוך הוא דקאי אבבא\u0004 \u0005[ש\u0006הוא \u0005עומד על הפתח].\u0006 \u0003היינו דכתיב\u0004 \u0005[הוא שנאמר]\u0006 \u0003\"\u0004אדני אם נא מצאתי חן בעיניך \u0003אל נא תעבור מעל עבדך\"\u0004 (שם יח, ג), שפנה לשכינה בבקשה זו.","\u0003כיון\u0004 ש\u0003חזא דקא אסר ושרי\u0004 \u0005[כיון שראה\u0006 הקדוש ברוך הוא \u0005שהוא קושר ומתיר]\u0006 התחבושת על פצעו, \u0003אמר: לאו אורח ארעא למיקם הכא\u0004 \u0005[אין זה דרך ארץ לעמוד כאן].\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"וישא עיניו וירא והנה שלשה אנשים נצבים עליו וירא וירץ לקראתם\u0004 (שם ב). \u0003מעיקרא אתו קמו עליה\u0004 \u0005[מתחילה באו ועמדו עליו],\u0006 \u0003כי חזיוהו דהוה ליה צערא\u0004 \u0005[כאשר ראוהו שיש לו צער,\u0006 כאב\u0005],\u0006 \u0003אמרו: לאו אורח ארעא למיקם הכא\u0004 \u0005[אין זה דרך ארץ לעמוד כאן].\u0006","ואומרים: \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 \u0003שלשה אנשים\u0004 אלו — המלאכים \u0003מיכאל וגבריאל ורפאל.\u0004 ולשם מה באו? \u0003מיכאל\u0004 — \u0003שבא לבשר את שרה\u0004 שיהיה לה בן, \u0003רפאל\u0004 — \u0003שבא לרפא את אברהם\u0004 מכאב המילה, \u0003גבריאל אזל למהפכיה\u0004 \u0005[הלך להפוך]\u0006 את \u0003סדום.\u0004 ושואלים: אם כך, רק מלאך אחד צריך ללכת לסדום, \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויבאו שני המלאכים סדמה בערב\"\u0004 (בראשית יט, א)! ומשיבים: \u0003דאזל\u0004 \u0005[שהלך]\u0006 \u0003מיכאל בהדיה לשזביה\u0004 \u0005[אתו,\u0006 עם גבריאל, \u0005להציל]\u0006 את \u0003לוט.\u0004 ומעירים: \u0003דיקא נמי, דכתיב\u0004 \u0005[מדוייק גם כן\u0006 לומר כך, \u0005ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויהפך את הערים האל\"\u0004 (שם כה) \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 בלשון רבים \u0003\"ויהפכו\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שרק מלאך אחד היה שליח הפורענות, ואחד היה שליח להצלה.","אגב כך שואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 במנהג המלאכים \u0003לגבי אברהם דכתיב\u0004 \u0005[שנאמר]\u0006 מיד כשפנה אליהם אמרו לו: \u0003\"כן תעשה כאשר דברת\"\u0004 (שם יח, ה), \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 במנהגם \u0003לגבי לוט דכתיב\u0004 \u0005[שנאמר]\u0006"],["\u0003\"ויפצר בם מאד\"\u0004 (בראשית יט, ג) עד שנענו לו? \u0003אמר ר' אלעזר: מכאן\u0004 שמחמת הנימוס \u0003מסרבין לקטן\u0004 הבא להציע מתנה או אירוח, אבל \u0003אין מסרבין לגדול,\u0004 שאם אדם גדול מציע דבר אין זה מנומס להתווכח אתו, אלא עושים מיד כפי שביקש.","\u0003כתיב\u0004 \u0005[נאמר]\u0006 שאמר אברהם לאורחיו: \u0003\"ואקחה פת לחם\u0004 וסעדו לבכם\u0003\"\u0004 (שם יח, ה) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ואל הבקר רץ אברהם\u0004 ויקח בן בקר רך וטוב...\u0003\"\u0004 (שם, ז), \u0003אמר ר' אלעזר: מכאן שצדיקים אומרים מעט,\u0004 שהרי אמר להם רק פת לחם, \u0003ועושים\u0004 בפועל \u0003הרבה.\u0004 ואילו \u0003רשעים אומרים הרבה ואפילו מעט אינם עושים,\u0004","\u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה — \u0003מעפרון. מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 בו שאמר לאברהם \u0003\"ארץ ארבע מאת שקל כסף\u0004 ביני ובינך מה היא...\u0003\"\u0004 (שם כג, טו), \u0003ולבסוף כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וישמע אברהם אל עפרון וישקל אברהם לעפרן את הכסף אשר דבר באזני בני חת ארבע מאות שקל כסף עבר לסחר\"\u0004 (שם טז), שלא רק שלקח מיד את הכסף, אלא אף \u0003לא שקל מיניה\u0004 \u0005[לקח\u0006 \u0003ממנו]\u0004 \u0003אלא קנטרי\u0004 \u0005[מטבעות מובחרים]\u0006 \u0003דאיכא דוכתא דקרי ליה לתיקלא\u0004 \u0005[שיש מקום שקוראים לו לשקל]\u0006 \u0003\"קנטירא\".\u0004","\u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"קמח\" וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"סלת\"\u0004 (\"מהרי שלש סאים קמח סלת\" (שם יח, ו), ולכאורה אפשר לתת או קמח או סולת! \u0003אמר ר' יצחק: מכאן שהאשה צרה עיניה באורחים יותר מן האיש,\u0004 שהיא רצתה לתת קמח והיא זו שאמרה \"קמח\", והוא רצה לתת מובחר יותר, ולכן אמר הוא \"סולת\".","\u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"לושי ועשי עגות\"\u0004 (שם), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בהמשך \u0003\"ויקח חמאה וחלב ובן הבקר\u0004 אשר עשה...\u0003\"\u0004 (שם ח), \u0003ואילו לחם לא אייתי לקמייהו\u0004 \u0005[הביא לפניהם],\u0006 ומדוע? הרי אמר לה לעשות עוגות!","\u0003אמר אפרים מקשאה תלמידו של ר' מאיר משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מאיר: אברהם אבינו אוכל חולין בטהרה היה,\u0004 שהיה מקפיד לאכול כל מאכלים — אפילו חולין — כשהם טהורים, \u0003ושרה אמנו אותו היום פירסה נדה\u0004 ומשום כך נטמא האוכל, ולא רצה אברהם לאכול מאכל טמא.","ובהמשך נאמר \u0003\"ויאמרו אליו איה שרה אשתך ויאמר הנה באהל\"\u0004 (שם ט) — בא כתוב זה \u0003להודיע ששרה אמנו צנועה היתה,\u0004 שגם כשבאו האורחים לא יצאה מתוך האוהל. \u0003אמר רב יהודה אמר רב ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק: יודעים היו מלאכי השרת ששרה אמנו באהל היתה, אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"באהל\",\u0004 למה שאלו אף שידעו שישיב להם שהנה היא באהל — \u0003כדי לחבבה על בעלה,\u0004 שיזכיר אותה ואת מעלותיה הטובות.","\u0003ר' יוסי בר' חנינא אמר:\u0004 שאלו עליה \u0003כדי לשגר לה כוס של ברכה\u0004 כדרך שנוהגים, שמברכים על הכוס ונותנים ממנו לבני הבית. \u0003תני משום\u0004 \u0005[שנו בשם]\u0006 \u0003ר' יוסי: למה נקוד\u0004 בתורה \u0003על\u0004 האותיות \u0003איו שב\u0004מלה \u0003\"אליו\"\u0004 — \u0003לימדה\u0004 כאן \u0003תורה דרך ארץ; שישאל אדם באכסניא שלו,\u0004 שכאשר בא למקום ישאל מה שלום בעל הבית (\"איו\") ומה שלום בעלת הבית. ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: אין שואלין בשלום אשה כלל,\u0004 שאין זה מנהג דרך ארץ! ומשיבים: \u0003על ידי בעלה שאני\u0004 \u0005[שונה],\u0006 שדבר זה בוודאי מותר ואין בו משום חוסר צניעות.","על מה שנאמר שאמרה שרה \u0003\"אחרי בלתי היתה לי עדנה\"\u0004 (שם, יב), \u0003אמר רב חסדא: אחר שנתבלה הבשר\u0004 מזקנה \u0003ורבו הקמטין\u0004 — שוב \u0003נתעדן הבשר ונתפשטו הקמטין, וחזר היופי למקומו.\u0004","\u0003כתיב\u0004 \u0005[נאמר]\u0006 שאמרה שרה \u0003\"ואדני זקן\"\u0004 (שם), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"\u0004ויאמר ה' אל אברהם למה זה צחקה שרה לאמר האף אמנם אלד \u0003ואני זקנתי\"\u0004 (שם יג) — שינו הלשון מלמד \u0003דלא מותיב\u0004 \u0005[שאין משיב,\u0006 חוזר\u0005]\u0006 \u0003הקדוש ברוך הוא כדקאמרה איהי\u0004 \u0005[כפי שאמרה היא]\u0006 (\"אדוני זקן\") אלא בשינוי, שהיא הזקינה.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003דבי ר' ישמעאל: גדול שלום, שאפילו הקדוש ברוך הוא שינה בו,\u0004 בגללו, \u0003שנאמר: \"ותצחק שרה בקרבה\u0004 לאמור אחרי בלותי היתה לי עדנה \u0003ואדני זקן\"\u0004 (שם יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמר ה' אל אברהם\u0004 למה זה צחקה שרה לאמר האף אמנם אלד \u0003ואני זקנתי\"\u0004 (שם יג), ששינה הקדוש ברוך הוא ממה שאמרה שרה, כדי שלא ייעלב אברהם, ויפגע השלום ביניהם.","נאמר ביחס לשרה שלאחר לידת יצחק \u0003\"ותאמר מי מלל לאברהם הניקה בנים שרה\"\u0004 (שם כא, ז), ושואלים: \u0003כמה בנים הניקה שרה?\u0004 הרי לא הניקה אלא את יצחק! \u0003אמר ר' לוי: אותו היום שגמל אברהם את יצחק בנו עשה סעודה גדולה. היו כל אומות העולם מרננים ואומרים: ראיתם זקן וזקנה\u0004 אלה \u0003שהביאו אסופי מן השוק ואומרים: בנינו הוא, ולא עוד אלא שעושין משתה גדול להעמיד\u0004 (לתת חיזוק) ל\u0003דבריהם!\u0004","\u0003מה עשה אברהם אבינו\u0004 — \u0003הלך וזימן כל גדולי הדור, ושרה אמנו זימנה את נשותיהם. וכל אחת ואחת\u0004 מן הנשים \u0003הביאה בנה עמה ומניקתה לא הביאה, ונעשה נס בשרה אמנו ונפתחו דדיה\u0004 (שדיה) \u0003כשני מעיינות, והניקה את כולן,\u0004 את כל הילדים הללו, והוא שנאמר \"הניקה בנים שרה\". \u0003ועדיין היו\u0004 אנשים \u0003מרננים ואומרים: \"אם שרה הבת תשעים שנה תלד\",\u0004 בכל זאת \u0003\"אברהם בן מאה שנה יוליד\"? מיד נהפך קלסתר פנים של יצחק ונדמה\u0004 לגמרי \u0003לאברהם, פתחו כולם ואמרו \"אברהם הוליד את יצחק\"\u0004 (בראשית כה, יט).","אגב ענין זה אומרים: \u0003עד אברהם לא היה\u0004 \u0005[היתה]\u0006 \u0003זקנה\u0004 בעולם, שלא היה הזקן ניכר במראהו מן הצעיר. וכיון שכך \u0003מאן דהוה בעי למשתעי בהדי\u0004 \u0005[מי שהיה רוצה לשוחח עם]\u0006 \u0003אברהם\u0004 היה \u0003משתעי בהדי\u0004 \u0005[משוחח עם]\u0006 \u0003יצחק,\u0004 וכן להיפך, מי שהיה רוצה לשוחח \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003יצחק\u0004 — היה \u0003משתעי בהדי\u0004 \u0005[משוחח עם]\u0006 \u0003אברהם,\u0004 שהרי כאמור היו שניהם דומים לגמרי זה לזה ולכן \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אברהם בעא רחמי והוה\u0004 \u0005[ביקש רחמים ונהיתה]\u0006 \u0003זקנה,\u0004 שיהיה ניכר זקן וצעיר, \u0003שנאמר \"ואברהם זקן בא בימים\"\u0004 (בראשית כד, א), ועד כתוב זה לא נזכרה כלל זקנה באדם אחר.","\u0003עד יעקב לא הוה חולשא\u0004 \u0005[היתה חולשה,\u0006 מחלה\u0005]\u0006 והיה אדם מת פתאום. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003יעקב בעא רחמי והוה חולשא\u0004 \u0005[ביקש רחמים ובאה חולשה\u0006 מחלה\u0005]\u0006 לעולם, שיידע אדם שהנה הוא עומד למות, ויכין עצמו. \u0003שנאמר: \"ויאמר ליוסף הנה אביך חלה\"\u0004 (שם מח, א), וזו פעם ראשונה במקרא שנזכרה בו מחלה. \u0003עד דאתא\u0004 \u0005[שבא]\u0006 \u0003אלישע לא הוה דחליש ואתפח\u0004 \u0005[היה מי שחולה ומתרפא],\u0006 שהיה אדם חולה רק פעם אחת — ומת. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אלישע בעא רחמי ואתפח\u0004 \u0005[ביקש רחמים והתרפא],\u0006 \u0003שנאמר: \"ואלישע חלה את חליו אשר ימות בו\"\u0004 (מלכים ב' יג, יד) — \u0003מכלל\u0004 הדברים אתה לומד \u0003דחלה חלי אחריתי\u0004 \u0005[שחלה\u0006 גם \u0005חולי אחר]\u0006 שלא מת בו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה חלאין חלה אלישע,\u0004 ושנים מהם באו לו כעונש; \u0003אחד\u0004 — \u0003על שדחפו לגיחזי בשתי ידיו,\u0004 כלומר, שגירש את גיחזי מעל פניו לגמרי ולא נתן לו אפשרות לחזור בו. \u0003ואחד\u0004 — \u0003על שגירה דובין בתינוקות\u0004 כמעשה שקלל את הילדים ויצאו הדובים מן היער והרגום, \u0003ו\u0004חולי \u0003אחד\u0004 נוסף \u0003שמת בו, שנאמר: \"ואלישע חלה את חליו אשר ימות בו\"\u0004 (שם).","שנינו במשנה שאמר ר' יוחנן בן מתיא לבנו: \u0003אלא עד שלא יתחילו במלאכה צא ואמור להם על מנת שאין לכם עלי אלא פת וקטנית.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף לרב חסדא:\u0004 האם \u0003פת קטנית תנן\u0004 \u0005[שנינו],\u0006 שהיא פת פחותה עשויה ממיני קטנית, \u0003או פת וקטנית תנן\u0004 \u0005[שנינו]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בלשון שבועה: \u0003האלהים! צריכה וי\"ו\u0004 (ב\"וקטנית\") \u0003כי מורדיא דלברות\u0004 \u0005[כמו משוט של ברוש],\u0006 כלומר, ברור בלי ספק שיש שם ו\"ו.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר: אינו צריך,\u0004 אלא \u0003הכל כמנהג המדינה.\u0004 ושואלים: לשון \u0003\"הכל\"\u0004 ששנינו \u0003לאתויי מאי\u0004 \u0005[להביא מה],\u0006 מה מוסיף בזה? ומשיבים: \u0003לאתויי הא דתנן\u0004 \u0005[להוסיף זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השוכר את הפועל ואמר לו\u0004 הריני משלם לך \u0003כאחד וכשנים מבני העיר\u0004 — \u0003נותן לו כפחות שבשכירות\u0004 באותו מקום, שמשום כך אמר לו בלשון זו אלו \u0003דברי ר' יהושע. וחכמים אומרים: משמנין\u0004 \u0005[מחלקים]\u0006 \u0003ביניהם\u0004 לא כמחיר הגבוה ולא כפחות, אלא כמנהג המדינה. והוא שרמז לו רבן שמעון בן גמליאל.","יודעים אנו מן הכתובים ומדברי חכמים שפועל העושה מלאכה אצל בעל הבית מותר לו לאכול מן הפירות שעובד בהם. ואמרו, \u0003ואלו\u0004 מן הפועלים \u0003אוכלין מן התורה,\u0004 שלפי דין תורה מחוייב בעל הבית להניח להם לאכול: פועל \u0003העושה במחובר לקרקע, בשעת גמר מלאכה\u0004 של אותו גידול (כגון בציר), או עושה מלאכה \u0003בתלוש מן הקרקע עד שלא נגמרה מלאכתו,\u0004 כגון באיסוף תבואה מן השדה, \u0003ובדבר שגידולו מן הארץ\u0004 דווקא. \u0003ואלו שאין אוכלים:\u0004 פועל \u0003העושה במחובר לקרקע\u0004"],["\u0003בשעה שאין גמר מלאכה\u0004 עדיין, או \u0003בתלוש מן הקרקע מאחר שנגמרה מלאכתו,\u0004 וכן עושה \u0003בדבר שאין גידולו מן הארץ.\u0004","על המשנה שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלו]\u0006 שמותר לפועל לאכול במחובר לקרקע, מה מקור דין זה בכתוב? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תבא בכרם רעך ואכלת\u0004 ענבים כנפשך שבעך ואל כליך לא תתן\u0003\"\u0004 (דברים כג, כה). ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו,\u0006 למדנו מכאן\u0005]\u0006 \u0003כרם, כל מילי מנא לן\u0004 \u0005[דברים,\u0006 שאר גידולים, \u0005מנין לנו]\u0006 שגם בהם הדין כך?","ומשיבים: \u0003גמרינן\u0004 \u0005[לומדים אנו]\u0006 בדרך הלימוד של בנין אב \u0003מכרם: מה כרם מיוחד\u0004 בכך שהוא \u0003דבר שגידולי קרקע, ובשעת גמר מלאכה פועל אוכל בו, אף כל דבר שגידולי קרקע\u0004 — \u0003בשעת גמר מלאכה פועל אוכל בו.\u0004","ומקשים: \u0003מה לכרם\u0004 שיש בו צד מיוחד — \u0003שכן חייב ב\u0004מצות הפרשת \u0003עוללות,\u0004 ואם כן שמא מיוחד הוא אף בדינים אלה! ומשיבים: \u0003גמרינן\u0004 \u0005[לומדים אנו]\u0006 \u0003מקמה.\u0004 ושואלים: ב\u0003קמה גופה\u0004 \u0003מנא לן\u0004 \u0005[עצמה מנין לנו]\u0006 שהדין כן? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תבא בקמת רעך וקטפת מלילת בידך\u0004 וחרמש לא תניף על קמת רעך","\u0003\"\u0004(שם כו). ויש לדחות: \u0003מה לקמה\u0004 — שיש בה דין מיוחד \u0003שכן\u0004 העיסה שעושים ממנה \u0003חייבת ב\u0004הפרשת \u0003חלה!\u0004 על דחיה זו שואלים: \u0003וממאי דהאי\u0004 \u0005[ומנין שזו]\u0006 ה\u0003קמה\u0004 שנאמרה בכתוב זה \u0003קמה\u0004 ש\u0003מתחייבת בחלה היא? דלמא\u0004 \u0005[שמא]\u0006 \u0003כל קמה קאמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 כל יבול, כל דבר שגדל!","ומשיבים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"קמה\" \"קמה\": כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"כי תבא בקמת רעך\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"\u0004שבעה שבועות תספר לך \u0003מהחל חרמש בקמה...\"\u0004(דברים טז, ט). \u0003מה התם\u0004 \u0005[שם]\u0006 \"מהחל חרמש בקמה\" הוא בקצירת עומר ושעורים (כמבואר בספר ויקרא) והיא \u0003קמה דמיחייבא\u0004 \u0005[שמתחייבת]\u0006 \u0003ב\u0004הפרשת \u0003חלה, אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003קמה דמיחייבא\u0004 \u0005[שמתחייבת]\u0006 \u0003בחלה.\u0004","דחינו איפוא את השאלה הצדדית הזו, ולכן עדיין עומדת השאלה הראשונה, שהרי \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]\u0006 על מה שלמדנו מכאן, ואפשר לומר: \u0003מה לקמה שכן חייבת בחלה!\u0004 ומשיבים: אם כך — \u0003כרם יוכיח,\u0004 שאינו חייב בחלה ופועל אוכל בו! ודוחים: \u0003מה לכרם\u0004 — \u0003שכן חייב בעוללות.\u0004 ואומרים: אם כן — \u0003קמה תוכיח,\u0004 שאינה חייבת בעוללות ופועל אוכל בה.","ובסופו של דבר \u0003חזר הדין\u0004 (חוזר הדיון — השיקול) בענין זה על עצמו, ועלינו להגיע למסקנה: \u0003לא ראי זה כראי זה,\u0004 כלומר, אין זה דומה לזה, שלא דין הקמה כדין הכרם, ולא דין הכרם כדין הקמה. \u0003הצד השוה שבהן\u0004 — \u0003שכן\u0004 שניהם \u0003דבר שגידולי קרקע, ובשעת גמר מלאכה פועל אוכל בו,\u0004 ומכאן נסיק: \u0003אף כל דבר שגידולי קרקע בשעת גמר מלאכה פועל אוכל בו.\u0004","ומקשים: \u0003מה להצד השוה שבהן\u0004 שאי אפשר ללמוד ממנו על כל הדברים כולם, \u0003שכן יש בהן צד מזבח\u0004 — ששניהם כאחד יוצאי דופן, שכן גם מן הכרם וגם מן הקמה מביאים למזבח (לנסכים יין מן הכרם, וחלה למנחות מן הקמה) ויש בהם איפוא יחוד. \u0003ו\u0004אמנם \u0003אתא נמי\u0004 \u0005[בא,\u0006 נלמד, \u0005גם כן]\u0006 מכאן \u0003זית, דאית ביה\u0004 \u0005[שיש בו]\u0006 גם כן \u0003צד מזבח\u0004 שאף משמן הזית מעלים למזבח. אבל לא נלמד לשאר גידולים!","אגב כך שואלים: \u0003וזית\u0004 האם \u0003ב\u0004דרך הלימוד של \u0003\"מה הצד\u0004 השווה ביניהם \u0003\"\u0004\u0003אתי\u0004 \u0005[בא,\u0006 נלמד\u0005]?\u0006 הלא \u0003הוא גופיה\u0004 \u0005[עצמו]\u0006 \u0003\"כרם\" איקרי\u0004 \u0005[נקרא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבער מגדיש ועד קמה ועד כרם זית\"\u0004 (שופטים טו, ה)! \u0003אמר רב פפא:\u0004 אף על פי כן צריך ללמוד ב\"מה הצד\", כי אמנם \u0003\"כרם זית\"\u0004 — \u0003אקרי\u0004 \u0005[נקרא],\u0006 \u0003\"כרם\" סתמא\u0004 \u0005[סתם]\u0006 — הוא \u0003לא אקרי\u0004 \u0005[נקרא].\u0006","ו\u0003מכל מקום קשיא\u0004 \u0005[קשה],\u0006 שהרי אין ללמוד מכאן על דברים שאינם באים למזבח! \u0003אלא אמר שמואל:\u0004 יש לדחות את דרך הלימוד שאמרנו, ויש לומר כך: מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וחרמש\u0004 לא תניף\u0003\"\u0004 (דברים כג, כו) — הרי זה בא \u0003לרבות כל בעלי חרמש,\u0004 כלומר, לרבות כל הדברים הנקצרים בחרמש.","ושואלים: \u0003והאי\u0004 \u0005[ו\u0006הלא \u0005זו]\u0006 המלה \u0003\"חרמש\" מיבעי ליה\u0004 \u0005[צריכה לו]\u0006 ללימוד אחר: ש\u0003בשעת חרמש\u0004 שהיא שעת גמר מלאכה — \u0003אכול, שלא בשעת חרמש\u0004 — \u0003לא תיכול\u0004 \u0005[אל תאכל]!\u0006","ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 ענין\u0005]\u0006 \u0003מ\"ואל כליך לא תתן\"\u0004 (שם) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005],\u0006 כפי שנבאר להלן. ומקשים על שיטת שמואל: \u0003תינח\u0004 \u0005[נניח]\u0006 בכל דבר שהוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003חרמש,\u0004 דברים שניתנים לקצירה בחרמש, שהם יכולים להילמד מביטוי זה, ואולם דבר \u0003דלאו בר\u0004 \u0005[שאיננו בן]\u0006 \u0003חרמש\u0004 שאיננו נקצר בחרמש \u0003מנא לן\u0004 \u0005[\u0006\u0005מנין לנו]\u0006 שגם בו יש דין זה?","\u0003אלא\u0004 נדחו דברי שמואל ו\u0003אמר ר' יצחק:\u0004 מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"קמה\"\u0004 — הרי זה בא \u0003לרבות כל בעלי קמה,\u0004 כלומר, כל הגידולים. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמרת\u0004 קודם \u0003\"קמה\"\u0004 \"קמה\" ולמדנו מגזירה שווה זו שמדובר ב\u0003קמה דמיחייבא\u0004 שמחוייבת \u0003ב\u0004הפרשת \u0003חלה\u0004 ולא יותר!","ומשיבים: \u0003הני מילי\u0004 \u0003מקמי דניתי\u0004 \u0005[דברים אלה\u0006 אמרנו \u0005לפני שבא]\u0006 הלימוד של \u0003\"\u0004\u0003חרמש\", השתא דאתי\u0004 \u0005[עכשיו שבא]\u0006 הלימוד של \u0003\"חרמש\"\u0004 — \u0003איתרבי ליה\u0004 \u0005[נתרבה לו,\u0006 ממנו\u0005]\u0006 \u0003כל דבר\u0004 הניתן לקצירה בחרמש, \u0003ואף על גב דלא מיחייב\u0004 \u0005[ואף\u0006 \u0003על פי שאיננו מתחייב]\u0004 \u0003ב\u0004הפרשת \u0003חלה,\u0004 אם כן נמצא איפוא שהמלה \"קמה\" אינה באה לצמצם את המשמעות ולא ללמד בגזירה שווה, אם כן המלה \u0003\"קמה\" למה לי\u0004 — הרי היא באה \u0003לרבות כל בעלי קמה.\u0004","ושואלים: \u0003והשתא דנפקא לן\u0004 \u0005[ועכשיו שיוצא לנו]\u0006 שלומדים את ההלכה כולה \u0003מ\"חרמש\" ומ\"קמה\",\u0004 הפסוק האחר \u0003\"כי תבא בכרם רעך\"...\u0004 (דברים כג, כה) \u0003למה לי?\u0004","\u0003אמר רבא:\u0004 פסוק זה נאמר \u0003להלכותיו\u0004 המיוחדות בו. \u0003כדתניא\u0004 \u0005[כפו ששנינו\u0006 בברייתא\u0005]\u0006 הדורשת פסוק זה כולו: \u0003\"כי תבא\", נאמר כאן\u0004 לשון \u0003\"ביאה\", ונאמר להלן\u0004 לשון \"ביאה\", \u0003\"\u0004ביומו תתן שכרו ו\u0003לא תבוא עליו השמש\"\u0004 (דברים כד, טו), \u0003מה להלן\u0004 ב\"לא תבא\" \u0003בפועל הכתוב מדבר, אף כאן\u0004 — \u0003בפועל הכתוב מדבר\u0004 ולא בכל אדם הבא לכרם.","ועוד: \u0003\"בכרם רעך\"\u0004 — \u0003ולא בכרם גוי.\u0004 ואומרים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003גזל גוי אסור\u0004 — \u0003היינו דאיצטריך קרא\u0004 \u0005[זה\u0006 הטעם \u0005שהוצרך הפסוק]\u0006 \u0003למישרי\u0004 \u0005[להתיר]\u0006 ב\u0003פועל, אלא למאן דאמר\u0004 \u0005[ל\u0006עת \u0005מי שאומר]\u0006 ש\u0003גזל גוי מותר\u0004 — \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003גזילה\u0004 עצמה \u0003מותר, פועל מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006","ומשיבים לשיטה זו: \u0003מוקים לה\u0004 \u0005[מעמיד,\u0006 מסביר \u0005אותה]\u0006 כך: \u0003\"בכרם רעך\"\u0004 — \u0003ולא של הקדש\u0004 ששם אסור לפועל לאכול. \u0003\"ואכלת\"\u0004 — \u0003ולא מוצץ\u0004 ומשליך את השאר, אלא צריך לאכול ממש. \u0003\"ענבים\" ולא ענבים ודבר אחר,\u0004 שאסור לו להוסיף תבלין לפירות כדי שיוכל לאכול הרבה מהן.","\u0003\"כנפשך\"\u0004 פירושו: \u0003כנפש של בעל הבית כך נפשו של פועל.\u0004 לומר: \u0003מה נפשך\u0004 — בעל הכרם — \u0003אוכל ופטור\u0004 מן המעשרות, שהרי עדיין לא הגיעו הפירות לגמר מלאכתן, \u0003אף נפשו של פועל\u0004 — \u0003אוכל ופטור.\u0004","\u0003\"שבעך\"\u0004 בא ללמד: \u0003ולא אכילה גסה\u0004 שאדם אוכל אחרי ששבע כבר, ודוחק עצמו לאכול בעל כרחו. \u0003\"ואל כליך לא תתן\"\u0004 ללמדנו: \u0003בשעה שאתה נותן לכליו של בעל הבית\u0004 בגמר מלאכה — אז \u0003אתה אוכל, ובשעה שאי\u0004 \u0005[שאין]\u0006 \u0003אתה נותן לכליו של בעל הבית\u0004 שהפועל עובד עבודה אחרת בכרם ולפני הבציר — \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה אוכל.\u0004","\u0003אמר ר' ינאי: אין הטבל\u0004 (תבואה שלא הפרישו ממנה עדיין את המעשרות) \u0003מתחייב ב\u0004הפרשת \u0003מעשר\u0004 ממנו"],["\u0003עד שיראה פני הבית,\u0004 כלומר, שיוכנס לתוך הבית, \u0003שנאמר\u0004 בוידוי המעשר: \u0003\"בערתי הקדש מן הבית\"\u0004 (דברים כו, יג), משמע שהתבואה נתחייבה — כשהיתה בתוך הבית.","\u0003ור' יוחנן אמר: אפילו חצר קובעת\u0004 לחובת מעשר, שדי במה שנכנס הטבל לחצר כדי שיתחייב, \u0003שנאמר: \"\u0004כי תכלה לעשר... ונתתה... \u0003ואכלו בשעריך ושבעו\"\u0004 (שם יב).","ושואלים: \u0003ור' יוחנן נמי, הא כתיב\u0004 \u0005[גם כן, הלא נאמר]\u0006 \u0003\"מן הבית\"! אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 בית זה אינו בית דווקא, אלא בא ללמדנו שהכנסת פירות הטבל ל\u0003חצר\u0004 הריהי \u0003דומיא\u0004 \u0005[בדומה]\u0006 להכנסתם ל\u0003בית; מה בית\u0004 כוונתו מקום \u0003המשתמר\u0004 — \u0003אף חצר\u0004 הכוונה דווקא לזו \u0003המשתמרת,\u0004 ולא לחצר הפתוחה לרבים.","ושואלים, לצד אחר: \u0003ור' ינאי נמי, הכתיב\u0004 \u0005[גם כן, הרי נאמר]\u0006 \u0003\"בשעריך\"!\u0004 ומשיבים: הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמוד \u0003דמעייל ליה\u0004 \u0005[שמכניס אותו]\u0006 את המעשר לבית \u0003דרך\u0004 ה\u0003שער, לאפוקי\u0004 \u0005[להוציא]\u0006 מקרה שבו מכניסו \u0003דרך גגות וקרפיפות\u0004 (חצרות אחוריות) שבדרך זו הוא \u0003לא\u0004 מתחייב.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חנינא חוזאה\u0004 על כך ממה ששנינו: \u0003\"כנפשך\"\u0004 (דברים כג, כה) — \u0003כך נפשו של פועל, מה נפשך\u0004 \u0003אוכל\u0004 קודם גמר מלאכה \u0003ופטור\u0004 מן המעשר, \u0003אף נפשו של פועל\u0004 — \u0003אוכל ופטור.\u0004","ונדייק מכאן: \u0003הא\u0004 \u0005[הרי\u0006 נלמד\u0005]\u0006 כי \u0003לוקח\u0004 (הקונה) שבא לקנות תבואה \u0003חייב\u0004 במעשר, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שלוקח \u0003בשדה\u0004 עצמו? ואם כן שנתחייב במעשר עוד לפני הכנסה לחצר!","\u0003אמר רב פפא: הכא\u0004 \u0005[כאן]\u0006 הלכה זו בפועל \u0003בתאנה העומדת בגינה\u0004 בחוץ \u0003ונופה נוטה לחצר עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאמר]\u0006 שמתחייב רק שהמעשר ב\u0003בית\u0004 — שהתאנה שבגינה נוטה \u0003לבית.\u0004","שואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003בעל הבית נמי ניחייב\u0004 \u0005[שגם כן יתחייב\u0006 במעשר\u0005],\u0006 שהרי הפירות בתוך הבית הם! ומשיבים: \u0003בעל הבית עיניו בתאנתו,\u0004 שהרי הוא מעונין בעץ התאנה בשלמותו, ועבורו הכל הולך לפי הגזע, מה שאין כן ה\u0003לוקח עיניו במקחו,\u0004 באותן תאנים שקטף, והן כבר בתוך הבית או החצר.","ושואלים: \u0003ולוקח מדאורייתא מי מחייב\u0004 \u0005[והקונה האם חייב מן התורה]\u0006 הפרשת מעשרות? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מפני מה חרבו חנויות של\u0004 המקום \u0003בית הינו\u0004 שהיה פרבר של ירושלים \u0003שלש שנים קודם\u0004 שחרבה \u0003ירושלים\u0004 עצמה — \u0003מפני שהעמידו דבריהם על דברי תורה,\u0004 שהיו נוהגים רק על פי דין תורה, ולא קיבלו על עצמם כחומרת חכמים. \u0003שהיו אומרין:\u0004"],["\u0003\"עשר תעשר... ואכלת\"\u0004 — \u0003ולא מוכר\u0004 שהוא אינו אוכל מן התבואה. \u0003\"תבואת זרעך\"\u0004 — \u0003ולא\u0004 ה\u0003לוקח.\u0004 ומשמע מכאן שאכן מדין תורה אין הלוקח חייב בהפרשת מעשרות. \u0003אלא\u0004 יש לדחות מה שאמרנו שחובת ההפרשה בלוקח היא רק \u0003מדרבנן\u0004 \u0005[\u0006\u0005מדברי סופרים],\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והכתוב\u0006 הובא רק \u0005לסמך,\u0006 לרמז, \u0005בלבד].\u0006","ושואלים: אם כן, \u0003אלא \"כנפשך\" למאי אתא\u0004 \u0005[למה בא\u0006 ללמדנו\u0005]?\u0006 ומשיבים: \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003\"כנפשך\", מה נפשך\u0004 — אתה עצמך, \u0003אם חסמת\u0004 את עצמך ולא אכלת \u0003פטור\u0004 אתה, ואין עליך איסור של \"לא תחסום שור בדישו\", \u0003אף פועל אם חסמת\u0004 ולא הנחת לו לאכול — \u0003פטור\u0004 אתה מעונש על \"לא תחסום\".","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא\u0004 ממה ששנינו: \u0003איזהו גורנן,\u0004 איזהו זמן שבו אנו חושבים שפירות הגיעו לגמר בישולם ואפשר לעשות מהם גורן, ואז הם מתחייבים \u0003למעשרות? בקישואים ובדלועים משיפקסו. ואמר ר' אסי:\u0004 מה הוא \"משיפקסו\" — \u0003משינטל פיקס שלהן,\u0004 שיבול הפרח היבש שבראש הפרי. ו\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003משיפקסו\u0004 — \u0003אפילו\u0004 בעודם \u0003בשדה!\u0004","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003משיפקסו בבית\u0004 דווקא. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון \u0003\"משיפקסו\"\u0004 אינה מדוייקת ו\u0003\"עד שיפקסו\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר!","ומשיבים: \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 בלשון \u0003\"עד שיפקסו\"\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003עד דגמר לפיקוסייהו\u0004 \u0005[שנגמר פיקוסם]\u0006 ומאז חייבים הם, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003משיפקסו,\u0004 שכוונתו: \u0003מכי אתחולי פיקוסייהו\u0004 \u0005[משעה שמתחיל פיקוסם].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן\u0004 ממה ששנינו: ממתי נחשב \u0003גורנו ל\u0004הצריכו ב\u0003מעשר\u0004 ו\u0003לחייב עליו משום טבל\u0004 — \u0003משתגמר מלאכתן. ואיזהו גמר מלאכתן\u0004 — \u0003מלאכת הכנסתן. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003הכנסתן\u0004 למקום קבוע ו\u0003אפילו בשדה!\u0004","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003הכנסתן לבית זה הוא גמר מלאכתן. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 לתרץ כך: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' ינאי\u0004 (ור' יוחנן) שחובת מעשר רק בכניסה לבית — אמר זאת \u0003בזיתים וענבים, דלאו\u0004 \u0005[שלא]\u0006 \u0003בני גורן נינהו\u0004 \u0005[הם],\u0006 שהרי אין כונסים אותם לגורן, אלא מביאים אותם לבית הבד. \u0003אבל חטין ושעורין\u0004 — \u0003\"גורן\" בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו,\u0006 בהן\u0005]\u0006 ומתחייבות במעשרות עוד לפני שנכנסו לחצר או לבית.","ומכאן שבים לביאור המשנה לענין פועל האוכל אצל בעל הבית. \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 אפוא ש\u0003אדם\u0004 העובד אצל בעל הבית אוכל \u0003במחובר\u0004 לקרקע. \u0003ו\u0004הכתוב מפרש כי \u0003שור\u0004 הדש אוכל \u0003בתלוש\u0004 (ככתוב \"לא תחסום שור בדישו\". דברים כה, ד). ואולם \u0003אדם\u0004 שמותר לו לאכול כשהוא עובד \u0003בתלוש מנלן\u0004 \u0005[מנין לנו]?\u0006","ומשיבים, דבר זה נלמד ב\u0003קל וחומר משור: ומה שור שאינו אוכל\u0004 בעבודתו \u0003במחובר\u0004 — \u0003אוכל בתלוש, אדם שאוכל במחובר\u0004 — \u0003אינו דין שאוכל בתלוש?\u0004 ודוחים: מה קל וחומר הוא? הלא אפשר לומר גם שיש חומרה בשור: \u0003מה לשור שכן אתה מצווה על חסימתו,\u0004 שהחוסם אותו עובר בלאו, \u0003תאמר באדם שאי\u0004 (אין) \u0003אתה מצווה על חסימתו!\u0004 ושואלים: ומנין לנו דבר זה שאמרנו אותו כך, בפשטות?","\u0003ויהא אדם מצווה על חסימתו\u0004 של אדם אחר מישראל העובד אצלו \u0003מקל וחומר משור,\u0004 ונאמר כך: \u0003ומה שור שאי אתה מצווה להחיותו,\u0004 שהרי אין מצווה להחיות ולפרנס שוורים שאין להם מה לאכול, ובכל זאת \u0003אתה מצווה על חסימתו, אדם\u0004 מישראל \u0003שאתה מצווה להחיותו\u0004 אם עני הוא וזקוק לכך — \u0003אינו דין שאתה מצווה על חסימתו?!\u0004","ומשיבים: דבר זה נלמד ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"כנפשך\"\u0004 (דברים כג, כה) ללמד: \u0003כנפשו של פועל, מה נפשו\u0004 של בעל הבית \u0003אם חסמתו פטור\u0004 — \u0003אף פועל אם חסמתו פטור.\u0004","\u0003ואלא\u0004 בטל קל וחומר זה שאמרנו וחוזרת השאלה: \u0003אדם בתלוש מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"קמה\" \"קמה\"\u0004 בפסוק \u0003שתי פעמים\u0004 (\"כי תבוא בקמת רעך... וחרמש לא תניף על קמת רעך\". דברים כג, כו), ו\u0003אם אינו ענין ל\u0004למד על \u0003אדם במחובר\u0004 שהרי כבר למדנו דין זה, \u0003תנהו ענין\u0004 מריבוי הכתוב להתיר \u0003לאדם\u0004 לאכול \u0003בתלוש.\u0004","\u0003ר' אמי אמר\u0004 טעם אחר: \u0003אדם בתלוש לא צריך קרא\u0004 \u0005[כתוב]\u0006 מיוחד להתירו, שהרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כי תבא בכרם רעך\u0004 ואכלת ענבים\u0003\"\u0004 (דברים שם כה) – \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה \u0003ששכרו לכתף\u0004 (לשאת) את הענבים מן הכרם החוצה, \u0003ואמר רחמנא ליכול\u0004 \u0005[ואמרה התורה שיאכל].\u0006","ושואלים לצד אחר: \u0003שור במחובר מנלן\u0004 \u0005[מנין לנו]\u0006 שאוכל? ומשיבים: \u0003קל וחמר מאדם: ומה אדם שאינו אוכל בתלוש\u0004 (כלומר, שלא אמר המקרא דבר זה במפורש) — מכל מקום \u0003אוכל\u0004 הוא \u0003במחובר, שור שאוכל בתלוש\u0004 — \u0003אינו דין שאוכל במחובר?\u0004 ודוחים: \u0003מה לאדם\u0004 — \u0003שכן אתה מצווה להחיותו, תאמר בשור שאי אתה מצווה להחיותו!\u0004 ומקשים: ובאמת מנין לנו דבר זה?","\u0003ויהא שור מצווה להחיותו\u0004 משום צער בעלי חיים, ועל פי \u0003קל וחומר\u0004 זה: \u0003ומה אדם שאי אתה מצווה על חסימתו\u0004 — \u0003אתה מצווה להחיותו, שור שאתה מצווה על חסימתו\u0004 — \u0003אינו דין שאתה מצווה להחיותו?!\u0004","ודוחים: דבר זה לא יתכן, ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וחי אחיך עמך\"\u0004 (ויקרא כה, לו) ונדייק: \u0003אחיך ולא שור.\u0004 ושואלים: \u0003ואלא\u0004 אם כן, \u0003שור במחובר מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"רעך\" \"רעך\" שתי פעמים\u0004 (שם כג, כו), \u0003אם אינו ענין לאדם במחובר\u0004 שהרי כבר למדנו דינו – \u0003תנהו ענין לשור במחובר.\u0004","\u0003רבינא אמר\u0004 למוד אחר: \u0003לא אדם בתלוש ולא שור במחובר צריכי קראי\u0004 \u0005[צריכים מקרא]\u0006 מיוחד לדרוש מהם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תחסם שור בדישו\"\u0004 (דברים כה, ד)"],["\u0003מכדי\u0004 \u0005[הלא],\u0006 \u0003כל מילי\u0004 \u0005[הדברים],\u0006 כל בעלי החיים, \u0003איתנהו\u0004 \u0005[ישנם],\u0006 חל עליהם דין \u0003חסימה,\u0004 \u0003דילפינן\u0004 \u0005[שאנו לומדים]\u0006 \u0003\"שור\" \"שור\" משבת,\u0004 שדין שביתה ממלאכה בשבת לא בשור בלבד נאמר אלא בכל בעלי חיים (כמפורש שם \"לא תעשה כל מלאכה... וכל בהמתך\". שמות כ, י. דברים ה, יד), אף דין חסימה לא בשור בלבד נאמר, אלא בכל בעלי חיים.\u0003 אם כן\u0004 שאין שור שבכתוב זה בא להגביל את הדין לשור בלבד — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 בלשון כוללת: \u0003\"לא תדוש בחסימה\", שור דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 במפורש \u0003למה לי?\u0004","— הרי זה בא \u0003לאקושי\u0004 \u0005[להקיש,\u0006 להשוות\u0005]\u0006 \u0003חוסם\u0004 שהוא אדם (פועל) \u0003לנחסם\u0004 שהוא שור, \u0003ו\u0004כן להקיש \u0003נחסם לחוסם.\u0004 וכך הלימוד: \u0003מה חוסם\u0004 (כלומר, אדם) \u0003אוכל במחובר\u0004 — \u0003אף נחסם אוכל במחובר. ומה נחסם אוכל בתלוש\u0004 — \u0003אף חוסם אוכל בתלוש.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בלימוד דומה מ\"לא תחסום\": בכתוב העוסק בענין חסימה הוזכר \u0003\"דיש\"\u0004 (\"לא תחסום... בדישו\". דברים כה, ד), \u0003מה דיש מיוחד\u0004 — \u0003דבר שגידולי קרקע ובשעת גמר מלאכה ופועל אוכל בו, אף כל שגידולי קרקע\u0004 — \u0003פועל אוכל בו. יצא החולב\u0004 את הפרה או \u0003המחבץ\u0004 (עושה חמאה מן השמנת) או \u0003המגבן\u0004 (עושה גבינה מחלב) \u0003שאין\u0004 הם בכלל העבודה ב\u0003גידולי קרקע, ואין פועל אוכל בו.\u0004","ושואלים: לימוד זה \u0003למה לי? מ\"כי תבא בכרם רעך\"\u0004 (שם כג, כה) \u0003נפקא\u0004 \u0005[יוצא]\u0006 הדבר, שהרי אין זה כרם, ואינו דומה לכרם! ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להילמד במפורש, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"קמה\",\u0004 וכפי שאמרנו בא הדבר \u0003לרבות כל בעלי קמה\u0004 (כל הגידולים), והיינו יכולים להעלות כי \u0003לרבות נמי מידי דלאו\u0004 \u0005[גם כן דברים שלא]\u0006 \u0003גדולי קרקע נינהו\u0004 \u0005[הם],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שרק בגידולי קרקע אמרו.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בענין זה: \u0003\"דיש\"\u0004 שנאמר בענין חסימה בא ללמד: \u0003מה דיש מיוחד\u0004 — \u0003דבר שבשעת גמר מלאכה פועל אוכל בו, אף כל שהוא בשעת גמר מלאכה פועל אוכל בו. יצא המנכש בשומים ובבצלים\u0004 שנשכר להוציא את העשבים השוטים מבין השומים והבצלים \u0003הואיל ואין\u0004 מלאכה זו בכלל \u0003גמר מלאכה\u0004 — \u0003אין פועל אוכל בהם.\u0004","ושואלים: לימוד זה \u0003למה לי?\u0004 והלא דבר זה \u0003מ\"ואל כליך לא תתן\"\u0004 (שם) \u0003נפקא\u0004 \u0005[יוצא\u0006 ונלמד\u0005],\u0006 כאמור, שאם אינו נותן לכלי בעל הבית — אף הוא אינו אוכל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 דרשה זו להיאמר אלא לאופן מסויים, ש\u0003אף על גב דקא משליף קטיני מביני אלימי\u0004 \u0005[אף על פי שהוא שולף\u0006 ומוציא גם \u0005את הקטנים מבין העבים]\u0006 והבצלים והשומים הקטנים הרי כבר נגמרה מלאכתם בכך, בכל זאת אין פועל אוכל בהם, לפי שאין זה בכלל גמר מלאכת השדה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"דיש\", מה דיש מיוחד\u0004 — \u0003דבר שלא נגמרה מלאכתו\u0004 עדיין \u0003למעשר פועל אוכל בו, אף כל שלא נגמרה מלאכתו למעשר פועל אוכל בו. יצא הבודל\u0004 (מפריד) \u0003בתמרים ובגרוגרות,\u0004 שתחילה צוברים אותם יחד והם נדבקים זה לזה, והפועל מפרידם במגרפה, \u0003הואיל ונגמרה מלאכתו למעשר\u0004 בשעה שנגמר יבולם — \u0003אין\u0004 ה\u0003פועל אוכל בו.\u0004","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 האומרת: \u0003הבודל בתמרים ובגרוגרות פועל אוכל בו! אמר רב פפא: כי תניא\u0004 \u0005[כאשר שנוייה]\u0006 הברייתא \u0003ההיא\u0004 שהפועל אוכל — הרי זה דווקא \u0003בתוחלני\u0004 \u0005[בתמרים המתבשלים בהבחלה],\u0006 שגודרים (קוטפים) אותם לפני גמר בישולם, ומניחים אותם על גבי קרקע כדי שיבשילו, ועדיין לא נגמרה מלאכתן אפילו בשעת בדילה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו נושא: \u0003\"דיש\", מה דיש מיוחד – דבר שלא נגמרה מלאכתו\u0004 עדיין עד חובת הפרשת \u0003חלה ופועל אוכל בו, אף כל דבר שלא נגמרה מלאכתו לחלה פועל אוכל בו. יצא הלש\u0004 את העיסה, \u0003והמקטף\u0004 (מושח פניה במים ובשמן) \u0003והאופה\u0004 שכיון \u0003שנגמרה מלאכתו לחלה\u0004 ש\u0003אין פועל אוכל בו.\u0004 ומקשים: ולמה לו ללמוד מכאן? \u0003והלא\u0004 כבר \u0003נגמרה מלאכתו למעשר\u0004 משעה שהובאה התבואה הביתה, וכבר למדנו שכאשר נגמרה מלאכתו למעשר שוב אין פועל אוכל בו!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 שבברייתא זו \u0003בחוצה לארץ עסקינן\u0004 \u0005[עוסקים אנו]\u0006 \u0003דליכא\u0004 \u0005[שאין\u0006 שם\u0005]\u0006 חובת \u0003מעשר.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שבחוצה לארץ מדובר, הלא חובת הפרשת \u0003חלה נמי ליכא\u0004 \u0005[גם כן אינה]!\u0006 \u0003אלא\u0004 יש לומר: \u0003לעולם\u0004 מדובר \u0003בארץ, ולא קשיא\u0004 \u0005[ואין זה קשה],\u0006 שבברייתא זו מדובר \u0003ב\u0004אותן \u0003שבע\u0004 שנים \u0003שכיבשו\u0004 ישראל את הארץ \u0003ובשבע שחילקו,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שבע\u0004 שנים \u0003שכיבשו\u0004 ישראל את הארץ \u0003ושבע\u0004 שנים \u0003שחילקו נתחייבו בחלה ולא נתחייבו במעשר.\u0004","ומקשים על תירוץ זה: \u0003מידי\u0004 \u0005[וכי]\u0006 ה\u0003מעשר קא גרים\u0004 \u0005[הוא\u0006 ש\u0005גורם]?\u0006 וכי החובה ההלכתית להפריש מעשר היא הקובעת לגבי הפועל? הלא \u0003גמר מלאכה קא גרים\u0004 \u0005[הוא הגורם]\u0006 וחובת הפרשת המעשר הוזכרה רק כציון מה הוא הנחשב לגמר מלאכה. ולכן, גם כשאין חלה חובת מעשר — עדיין יש כאן גמר מלאכה!","\u0003אלא אמר רבינא: כרוך ותני\u0004 \u0005[צרף\u0006 את שתי הברייתות \u0005ושנה]\u0006 אותן כאחת. כיצד? \u0003\"דיש\", מה דיש מיוחד\u0004 — \u0003דבר שלא נגמר מלאכתו למעשר\u0004 (בשאר גידולים) \u0003ולחלה\u0004 (במיני דגן) \u0003ופועל אוכל בו, אף כל שלא נגמר מלאכתו למעשר ולחלה פועל אוכל בו.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003פועל, מהו שיהבהב\u0004 (יחרוך מעט) \u0003באור\u0004 (באש) את הפירות או את המלילות שהוא אוכל בהן, כדי להשביח את טעמם? והשאלה היא: \u0003מי הוי\u0004 \u0005[האם הוא]\u0006 האם דינו \u0003כענבים ודבר אחר\u0004 שאסור לפועל \u0003או לא?\u0004 ומציעים, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא: \u0003רשאי בעל הבית להשקות פועלים יין כדי שלא יאכלו\u0004 אחר כך \u0003ענבים הרבה\u0004 מן הבציר, ומצד שני \u0003רשאין פועלין לטבל פיתם בציר\u0004 מלוח \u0003כדי שיאכלו ענבים הרבה,\u0004 משמע שמותר לפועל לעשות זאת!"],["\u0003לאכשורי גברא\u0004 \u0005[להכשיר\u0006 את \u0005האיש]\u0006 לאכילה \u0003לא קמיבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שבוודאי מותר לאדם לעשות כדי להכין עצמו לאכול הרבה, \u0003כי קמיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה היה זה בענין \u0003לאכשורי פירא, מאי\u0004 \u0005[להכשיר\u0006 את \u0005הפרי\u0006 לאכילה, \u0005מהו].\u0006 ומציעים עוד: \u0003תא שמע,\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא: \u0003פועלין אוכלין ענבים בראשי אומניות שלהם,\u0004 כלומר, בראשי השורות של הגפנים שבכרם ששם הענבים משובחים יותר, \u0003ובלבד שלא יהבהבו\u0004 את הענבים \u0003באור!\u0004","ודוחים: משם אין ראיה, \u0003התם\u0004 \u0005[שם]\u0006 אין האיסור משום ההבהוב באור אלא \u0003משום ביטול מלאכה,\u0004 שהוא מבטל מזמן עבודתו עבור בעל הבית. \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 השאלה הרי זה כשאין במעשה הפועל משום ביטול מלאכה, וכגון \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003אשתו ובניו\u0004 עמו, והם יכולים להבהב עבורו בלא שיתבטל ממלאכתו, ואז \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003לא יהבהב\u0004 הפועל בשעת עבודתו כתות של פירות \u0003באור ויאכל, ולא יכמור\u0004 (יחמם באדמה) \u0003ויאכל, ולא יפריך\u0004 (ישבור פירות) \u0003על גבי הסלע ויאכל, אבל מפריך\u0004 הוא \u0003על יד על יד\u0004 (מעט מעט) \u0003ואוכל.\u0004 ודוחים: משם אין ראיה, \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא \u0003משום ביטול מלאכה.\u0004 ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר\u0005].\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003משום מתוקי פירא\u0004 \u0005[מיתוק הפרי]\u0006 אסור — בשבירת הפרי על גבי \u0003סלע מאי מתוקי פירא איכא\u0004 \u0005[מה מיתוק פרי יש בו]?\u0006 ומשיבים: זו איננה ראיה חותכת, \u0003אי אפשר,\u0004 לא יתכן, \u0003ש\u0004\u0003לא ממתיק פורתא\u0004 \u0005[מתמתק\u0006 בכך הפרי \u0005מעט].\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו: \u0003פועלין שהיו עודרים\u0004 (קוטפים) \u0003בתאנים וגודרים\u0004 (קוטפים) \u0003בתמרים ובוצרים בענבים ומוסקין בזיתים\u0004 — \u0003הרי אלו אוכלים, ופטורים\u0004 מן המעשר, \u0003שהתורה זיכתה להם\u0004 לאכול. אבל \u0003בפיתם,\u0004 כלומר, מעורב בפת \u0003לא יאכלו, אלא אם כן נטלו רשות מבעל הבית. ו\u0004כן \u0003לא יספות\u0004 (יטבול) \u0003במלח ויאכל,\u0004 ומשמע שמיתוק הפרי אסור!","ודוחים: \u0003מלח ודאי כענבים ודבר אחר דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שכיון שמוסיף דבר מה — אסור. אבל כשממתיקם באש, שאין בכך תוספת של דבר אחר, שמא מותר. והשאלה ששאלנו מתחילה לא נמצאה לה תשובה.","שנינו בברייתא ש\u0003לא יספות\u0004 \u0005[יטבול]\u0006 \u0003במלח ויאכל. ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 לדבר ממה ששנינו: \u0003השוכר את הפועל לעדר ולקשקש\u0004 (לכסות את שרשי העץ המגולים) \u0003תחת הזיתים\u0004 — \u0003הרי זה לא יאכל\u0004 מן הזיתים, \u0003שכרו לבצור\u0004 ענבים או \u0003שכרו למסוק\u0004 זיתים או \u0003שכרו ללקט\u0004 פירות אחרים — \u0003הרי זה אוכל ופטור\u0004 ממעשר \u0003שהתורה זיכתה להן.\u0004 ואם \u0003קצץ\u0004 — קבע מראש עם בעל הבית שיאכל גם כשאינו זכאי מן התורה לכך, \u0003אחת ואחת\u0004 — \u0003יאכל\u0004 בלא הפרשת מעשר, \u0003שתים שתים\u0004 — \u0003לא יאכל, וסופת\u0004 \u0005[וטובל]\u0006 \u0003במלח ויאכל.\u0004","ונברר הלכה זו שסופת במלח ואוכל, \u0003אהייא\u0004 \u0005[על מה]\u0006 על איזה חלק של הברייתא נאמר; \u0003אילימא אסיפא\u0004 \u0005[אם תאמר על סופה]\u0006 כשהתנה עם בעל הבית — ואולם אז הדבר מיותר, \u0003כיון\u0004 ש\u0003קצץ\u0004 והתנה שאוכל, אם כן ב\u0003כל היכי דבעי ליכול\u0004 \u0005[אופן שרוצה\u0006 — \u0005יאכל],\u0006 \u0003אלא לאו ארישא\u0004 \u0005[האם לא\u0006 מדובר \u0005על ראשה]\u0006 של ברייתא, בפועל האוכל מדין תורה. ואם כן, הרי שהפועל סופת במלח בלא הפרשת מעשר!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן\u0004 שאסור — מדובר \u0003בארץ\u0004 ישראל, \u0003כאן\u0004 — \u0003בחוצה לארץ.\u0004 וזהו טעם ההבדל: \u0003בארץ קבעא ספיתא\u0004 \u0005[קובעת הטבילה\u0006 במלח\u0005]\u0006 שנחשב הדבר בכך כאכילת קבע, ומחייבת את הפירות למעשר. \u0003בחוצה לארץ לא קבעא ספיתא\u0004 \u0005[קובעת הטבילה].\u0006 \u0003אמר רבא: מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003בארץ קבעא ספיתא מדאורייתא\u0004 \u0005[קובעת הטבילה מן התורה]\u0006 \u0003ובחוצה לארץ לא קבעא ספיתא\u0004 \u0005[קובעת הטבילה]\u0006 \u0003ומותר\u0004 אפילו \u0003לכתחילה?!\u0004 לא יתכן שיהיה הבדל גדול כל כך בין המקומות, שהרי תקנות חכמים נעשו כעין דברי תורה.","\u0003אלא אמר רבא,\u0004 יש לדחות את דברי אביי ולתרץ בדרך אחרת: \u0003בין בארץ בין בחוצה לארץ,\u0004 אם אוכל \u0003חדא\u0004 \u0005[אחת]\u0006 — \u0003לא קבעא ספיתא\u0004 \u0005[אין הטבילה קובעת]\u0006 שעדיין זו אכילת ארעי, ואולם \u0003תרתי\u0004 \u0005[שתים]\u0006 — \u0003קבעא ספיתא\u0004 \u0005[קובעת טבילה].\u0006 ואם \u0003קצץ\u0004 שיאכל, \u0003בין ספת\u0004 \u0005[טבל]\u0006 \u0003ובין\u0004 אם \u0003לא ספת\u0004 \u0005[טבל],\u0006 \u0003אחת אחת\u0004 — \u0003אוכל, שתים שתים\u0004 — \u0003לא יאכל. לא קצץ ולא ספת\u0004 \u0005[טבל]\u0006 — \u0003אוכל שתים שתים,\u0004 ואם \u0003ספת\u0004 \u0005[טבל],\u0006 אם \u0003אחת אחת\u0004 — \u0003אוכל,\u0004 ואם \u0003שתים שתים\u0004 — \u0003לא יאכל, ואף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003נטל רשות מבעל הבית\u0004 לאכול אפילו שתים. והטעם הוא \u0003דאיטביל להו\u0004 \u0005[שנעשו להם\u0006 הפירות \u0005טבל]\u0006 \u0003ל\u0004ענין \u0003מעשר, וקבעא ספיתא\u0004 \u0005[\u0006משום \u0005שקובעת\u0006 אותם ה\u0005טבילה]\u0006 ואסור לפועל לאכול מהם בלא שהפריש מעשרות.","ושואלים: \u0003ותרתי דקבעא ספיתא מנא לן\u0004 \u0005[בשתים שקובעת\u0006 בהם \u0005טבילה מנין לנו]?\u0006 \u0003אמר רב מתנא,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי קבצם כעמיר גרנה\"\u0004 (מיכה ד, יב), שמכאן למדים שהמקבץ דברים יחד (ומיעוט של קבוצה הוא שנים יחד) הרי זה נחשב כמכניסם לגורן. וכיון שכך, אם גם טובלם במלח הרי זו אכילת קבע וחייבת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פרות המרכסות בתבואה,\u0004 שדשות בתבואה שכבר נידושה ונגמרה מלאכתה, אלא שדשים אותה שנית כדי להכין ממנה מאכל מיוחד,"],["\u0003והדשות בתרומה ומעשר\u0004 שאסור לפרות לאכול מהם, \u0003אינו עובר משום \"בל תחסום\"\u0004 כשחוסם אותן, \u0003אבל מפני מראית העין\u0004 שהרי אין הרואים יודעים שעושה בהיתר — \u0003מביא בול\u0004 (חתיכה) \u0003מאותו המין\u0004 שדשה בו \u0003ותולה לה בטרסקלין\u0004 (בסל) \u0003שבפיה, ר' שמעון בן יוחאי אומר:\u0004 אינו צריך להביא מאותו מין דווקא, אלא \u0003מביא כרשינים ותולה לה, שהכרשינים יפות לה מן הכל.\u0004","\u0003ורמינהי\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: החוסם \u0003פרות המרכסות בתבואה\u0004 — \u0003אינו עובר משום \"בל תחסום\", ו\u0004החוסם את הפרות \u0003הדשות בתרומה ומעשר\u0004 — \u0003עובר משום \"בל תחסום\", וגוי הדש בפרתו של ישראל\u0004 — \u0003אינו עובר משום \"בל תחסום\"\u0004 אבל \u0003ישראל הדש בפרתו של גוי\u0004 — \u0003עובר משום \"בל תחסום\"\u0004 שהכל תלוי בעושה, ולא בצער הפרה ולא בבעלות עליה. אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003תרומה\u0004 על דין \u0003תרומה,\u0004 וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003מעשר\u0004 על דין \u0003מעשר!\u0004","ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדין \u0003תרומה\u0004 על דין \u0003תרומה לא קשיא\u0004 \u0005[אינו קשה]\u0006 — \u0003כאן\u0004 ששנינו שאינו מאכיל אותה הרי זה מדובר \u0003בתרומה\u0004 ממש, \u0003כאן\u0004 ששנינו שמותר להאכילה הרי זה \u0003בגידולי תרומה\u0004 שאיסורם רק מדברי סופרים. \u0003אלא\u0004 מדין \u0003מעשר\u0004 על דין \u0003מעשר קשיא\u0004 \u0005[קשה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדין \u0003מעשר\u0004 על דין \u0003מעשר נמי לא קשיא\u0004 \u0005[גם כן אינו קשה];\u0006 כי \u0003כאן\u0004 — \u0003במעשר, כאן\u0004 — \u0003בגידולי מעשר,\u0004 אולם תירוץ זה אינו אפשרי: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גידולי תרומה\u0004 הלא דינם לפחות מדברי סופרים \u0003כ\u0004\u0003תרומה,\u0004 ואולם \u0003גידולי מעשר\u0004 הלא \u0003חולין נינהו\u0004 \u0005[הם].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003גידולי טבל וגידולי מעשר שני\u0004 — \u0003חולין\u0004 הן!","\u0003אלא\u0004 יש לתרץ אחרת: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שהחוסם את השור בשעה שדש תבואת מעשר עובר ב\"לא תחסום\" — הרי זה כשהוא דש \u0003במעשר ראשון\u0004 שנחשב כדישו שלו, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאינו עובר — הרי זה בדש \u0003במעשר שני\u0004 שהוא ממון גבוה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ כך: \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר \u0003במעשר שני, ולא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 — הברייתא האוסרת כשיטת \u0003ר' מאיר\u0004 היא, \u0003הא\u0004 \u0005[זו]\u0006 המתירה — כשיטת \u0003ר' יהודה\u0004 היא.","ומסבירים: \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' מאיר,\u0004 ש\u0003אמר: מעשר שני ממון גבוה\u0004 (של הקדוש ברוך הוא) \u0003הוא,\u0004 ולבעלים יש כאן רק זכות אכילה, וכיון שכך אסור שתאכל ממנו הפרה, \u0003הא\u0004 \u0005[זו]\u0006 כ\u0003ר' יהודה,\u0004 ש\u0003אמר: מעשר שני ממון הדיוט הוא.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק],\u0006 כיצד יכול להיות דבר כזה שהפרה תדוש במעשר? שהרי בדרך כלל הפרשת המעשר היא לאחר דישה ועשיית כרי של גרעינים! ומשיבים: \u0003כגון שהקדימו בשבלין,\u0004 שהלוי הקדים את הכהן, שלא כדרך הרגילה, ולקח מעשר בעודו בשבלים.","ושואלים: ולשיטת \u0003ר' יהודה\u0004 שאמרנו שמדובר במעשר שני, בכל זאת כיצד מותר לאכול מן המעשר לפני שנכנס לירושלים? \u0003הא בעי\u0004 \u0005[הרי צריך]\u0006 להכניסו בתוך ה\u0003חומה\u0004 של ירושלים! ומשיבים: \u0003כגון שדש לפנים מחומת בית פאגי\u0004 שהיא החומה החיצונית של ירושלים, והיה בה גם פרוור כפרי למחצה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ לסתירה הראשונה: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 — \u0003במעשר ודאי\u0004 אסור לפרה לאכול, \u0003כאן\u0004 — \u0003במעשר דמאי\u0004 שאינו אלא מתקנת חכמים. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 ותירצת שמדובר בדמאי, אם כן מדין \u0003תרומה\u0004 על דין \u0003תרומה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 ואפשר לתרץ כך: \u0003כאן\u0004 — \u0003בתרומת ודאי, כאן\u0004 — \u0003בתרומת דמאי.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מעשר דמאי\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 שהרי תיקנו חכמים להפריש מעשר מן הדמאי, \u0003אלא תרומת דמאי מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף הוא\u0004 יוחנן כהן גדול \u0003ביטל את הוידוי\u0004 שמתוודים בשעת ביעור מעשרות ששוב לא נהגו בו הכל כראוי \u0003וגזר על הדמאי\u0004 שיפרישו מעשר מתבואה של עם הארץ — \u0003לפי ששלח בכל גבול ישראל וראה שלא היו מפרישין אלא תרומה גדולה בלבד\u0004 ולא מעשר. אם כן, ברור שלענין תרומה גדולה לא נחשדו ישראל כלל וממילא אין דמאי בכך!","\u0003אלא\u0004 יש לתרץ באופן שונה במקצת ולומר כי \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 — \u0003בתרומת מעשר\u0004 שמפריש הלוי תרומה ממעשר של \u0003ודאי, כאן\u0004 — \u0003בתרומת מעשר\u0004 של \u0003דמאי.\u0004","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מרב ששת: היתה\u0004 הבהמה \u0003אוכלת\u0004 מן הדבר שדשה בו \u0003ומתרזת\u0004 (משלשלת), \u0003מהו\u0004 הדין? וצדדי השאלה, האם הטעם הוא \u0003משום דמעלי לה הוא\u0004 \u0005[שטוב הדבר\u0006 לפרה\u0005]\u0006 שתאכל, \u0003והא לא מעלי\u0004 \u0005[וזה\u0006 הלא \u0005אינו טוב]\u0006 \u0003לה,\u0004 ולכן יש לחסום אותה כדי שלא תינזק. \u0003או דלמא דחזיא ומצטערא, והא חזיא ומצטערא\u0004 \u0005[שמא\u0006 מפני \u0005ש\u0006היא \u0005רואה ומצטערת\u0006 כשאינה יכולה לאכול, \u0005והרי זו רואה ומצטערת]?\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת:\u0004 כבר \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 את הברייתא שיש בה תשובה לדבר, שהרי שנינו: \u0003ר' שמעון בן יוחי אומר: מביא כרשינים ותולה לה, שהכרשינים יפות לה מן הכל. שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהטעם \u0003משום דמעלי\u0004 \u0005[שטוב]\u0006 \u0003לה הוא.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003מהו שיאמר אדם לגוי \"חסום פרתי ודוש בה\"? מי אמרינן\u0004 \u0005[האם אנחנו אומרים]:\u0006 \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנחנו]\u0006 בהלכה את הכלל ש\u0003אמירה לגוי שבות,\u0004 שאם אומר לגוי לעשות בשבילו מלאכה בשבת עובר משום איסור שביתה — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003לענין שבת,\u0004 שעשיית מלאכה בה היא \u0003איסור\u0004 שהעובר עליו נדון ב\u0003סקילה, אבל חסימה\u0004 שהיא עצמה אינה אלא \u0003איסור לאו\u0004 (לא תעשה) שהעובר עליו דינו במלקות — \u0003לא,\u0004 אין איסור באמירה לגוי לעשות עבורו, \u0003או דלמא לא שנא\u0004 \u0005[שמא אינו שונה]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה מן הברייתא שהבאנו: \u0003גוי הדש בפרתו של ישראל\u0004 — \u0003אינו עובר משום \"בל תחסום\".\u0004 ונדייק מן הלשון: \u0003מעבר\u0004 \u0005[לעבור]\u0006 \u0003הוא\u0004 ש\u0003לא עבר\u0004 \u0005[עובר],\u0006 \u0003הא איסורא\u0004 \u0005[אבל איסור]\u0006 — \u0003איכא\u0004 \u0005[יש כאן].\u0006 ודוחים: אין זו הוכחה, \u0003בדין\u0004 (מן הדין) \u0003הוא דאיסורא נמי ליכא\u0004 \u0005[שאיסור גם כן אין\u0006 בכך\u0005],\u0006 \u0003ו\u0004אולם, \u0003איידי דתנא סיפא\u0004 \u0005[על ידי,\u0006 מפני, \u0005ששנה בסוף]\u0006 \u0003ישראל הדש בפרתו של גוי עובר, תנא רישא\u0004 \u0005[שנה בראש]\u0006 בסגנון דומה: \u0003אינו עובר,\u0004 ואין לדקדק מן הלשון.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מזה ש\u0003שלחו ליה לאבוה\u0004 \u0005[לו לאביו]\u0006 של \u0003שמואל\u0004 שאלה הלכתית זו: \u0003הלין תורי\u0004 \u0005[שוורים אלו]\u0006"],["\u0003דגנבין ארמאי ומגנחין יתהון\u0004 \u0005[שגונבים הגויים ומסרסים אותם],\u0006 שהיו הגויים יודעים שליהודים אסור לסרס בעלי חיים, והיו ידידיו הגויים של אדם גונבים ממנו כביכול את בהמתו ומסרסים אותה, ומחזירים אותה לו. שכן קל יותר לעבוד בבעלי חיים שסורסו. \u0003מהו\u0004 הדין בענין זה? \u0003שלח להו\u0004 \u0005[להם]\u0006 בתשובה: \u0003הערמה אתעביד בהו\u0004 \u0005[נעשתה בהם],\u0006 \u0003אערימו עלייהו ויזדבנון\u0004 \u0005[הערימו עליהם\u0006 כעונש \u0005וימכרו],\u0006 משמע שמעשה האסור לישראל אסור שייעשה אף על ידי גוי לצורך הישראל, שהרי קנסו שלא יהנו ישראל מדבר זה.","\u0003אמר רב פפא:\u0004 מכאן אין ראיה גמורה \u0003בני מערבא\u0004 \u0005[ארץ ישראל]\u0006 ששאלו דבר זה \u0003סברי לה\u0004 \u0005[סבורים הם]\u0006 \u0003כ\u0004שיטת \u0003ר' חידקא,\u0004 ש\u0003אמר: בני נח מצווין על הסירוס,\u0004 שאף להם אסור הדבר, \u0003ו\u0004אם כן \u0003קא עברי\u0004 \u0005[נמצא שעוברים]\u0006 היהודים הגורמים להם לעשות זאת \u0003משום \"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד).","\u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]\u0006 שאותן בהמות מסורסות לא די שלא ישתמשו בהן הבעלים אלא אף \u0003ימכרו לשחיטה,\u0004 כדי שלא יהנו כלל מהשבחת הערך שנעשתה בעבירה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: דיין שקנסת עליהם מכירה.\u0004","באותו ענין מעירים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שאם מוכר את הבהמה המסורסת ל\u0003בנו גדול\u0004 — \u0003כי\u0004 \u0005[כמו]\u0006 אדם \u0003אחר דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ואין צורך למכרו לזר דווקא. ואולם \u0003בנו קטן מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003רב אחי אסר, ורב אשי שרי\u0004 \u0005[התיר].\u0006 \u0003מרימר ומר זוטרא, ואמרי לה הנהו תרי חסידי\u0004 \u0005[ויש אומרים אותם שני חסידים]\u0006 שלא נתפרש שמם, \u0003מחלפי אהדדי\u0004 \u0005[היו מחליפים זה עם זה]\u0006 שוורים שכאלה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: הושיב לה\u0004 לבהמה הדשה \u0003קוץ בפיה, מהו\u0004 הדין? ותוהים: \u0003הושיב לה\u0004 — הלא \u0003חסימה מעלייתא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא!\u0004 \u0003אלא\u0004 כך יש לשאול: \u0003ישב לה קוץ בפיה\u0004 מעצמו ולא הוציאו \u0003מהו?\u0004","ושאלה דומה: \u0003הרביץ לה ארי מבחוץ\u0004 שתיבהל הבהמה ולא תאכל, \u0003מהו\u0004 הדין? ואף כאן תוהים: \u0003הרביץ לה?!\u0004 הלא \u0003חסימה מעלייתא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא!\u0004 \u0003אלא\u0004 כך יש לשאול: \u0003רבץ לה ארי\u0004 מעצמו \u0003מבחוץ מהו\u0004 הדין? וכן אם \u0003העמיד בנה מבחוץ\u0004 והיא רוצה לצאת אליו, ולכן אינה אוכלת, \u0003מהו?\u0004 או אם \u0003היתה צמאה למים מהו? פרס לה קטבליא\u0004 (שמיכת עור) \u0003על גבי דישה\u0004 שאינה רואה את מה שהיא דשה, \u0003מהו\u0004 הדין בכל אלה?","ומעירים, \u0003פשוט מהא חדא\u0004 \u0005[פטור מזו\u0006 שאלה \u0005אחת],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רשאי בעל\u0004 ה\u0003פרה\u0004 המשכיר פרתו לאחר לדוש \u0003להרעיב\u0004 את \u0003פרתו כדי שתאכל מן הדישה הרבה, ורשאי בעל הבית להתיר פקיע עמיר\u0004 (קש) \u0003לפני הבהמה כדי שלא תאכל מן הדישה הרבה,\u0004 והרי זה כפורס כיסוי על הדישה, והרי ששנינו שהדבר מותר!","ודוחים: משם אין ראיה, שכן \u0003שאני התם דקא אכלה\u0004 \u0005[שונה שם שהיא אוכלת]\u0006 על כל פנים דבר מה ולכן הותר הדבר, ואין איפוא ראיה לפורס כיסוי שהיא מניעה מוחלטת. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 והסבר את הברייתא כך: \u0003רשאי בעל הבית להתיר פקיע עמיר לפני בהמה מעיקרא\u0004 \u0005[מתחילה]\u0006 קודם הדישה \u0003כדי שלא תאכל הרבה מן הדישה.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' יונתן מר' סימאי: חסמה מבחוץ\u0004 לפני שהיא נכנסת לדוש \u0003מהו\u0004 הדין? וצדדי השאלה: \u0003\"שור בדישו\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 (דברים כה,ד) \u0003והא לאו\u0004 \u0005[וזה לא]\u0006 \u0003בדישו הוא\u0004 שכן נעשה מעשה החסימה מחוץ לדישו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש להבין שמשמעות הכתוב היא \u0003לא תדוש בחסימה אמר רחמנא\u0004 \u0005[אמרה תורה]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' סימאי: \u0003מבית אביך אתה למד,\u0004 כלומר, שאתה יכול ללימוד הלכה זו מהלכות הכהנים, שאף אתה אחד מהם. שנאמר: \u0003\"יין ושכר אל תשת אתה ובניך אתך בבואכם\u0004 אל אהל מועד\u0003\"\u0004 (ויקרא י, ט), שאם נפרש בדיוק כלשון הכתובים, אם כן \u0003בבואכם הוא\u0004 ש\u0003אסור, הא מישתא ומיעל שרי\u0004 \u0005[הרי לשתות\u0006 יין \u0005ולהיכנס מותר].\u0006","וזה בלתי אפשרי, שהרי באותו ענין \u0003\"ולהבדיל בין הקדש ובין החל\"\u0004 (שם י) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 ומשמעו — שיהא הכהן מסוגל להבחין בין הדברים בבואו לקודש. \u0003אלא, מה התם\u0004 \u0005[מה שם]\u0006 באיסור יין במקדש — הכוונה היא: \u0003בשעת ביאה לא תהא שכרות,\u0004 בין ששותה בפנים או בחוץ, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה: \u0003בשעת דישה לא תהא חסימה.\u0004","\u0003תנו רבנן: החוסם את הפרה\u0004 שלא הוא אלא חבירו דש בה, וכן \u0003המזווג בכלאים,\u0004 שרותם כלאים, כגון שור וחמור, באותה עגלה ולא הוא המנהיג — \u0003פטור, ואינו לוקה אלא\u0004 ה\u0003דש\u0004 בבהמה החסומה עצמה, או ה\u0003מנהיג\u0004 בכלאים עצמו \u0003בלבד.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה אם \u0003חסמה בקול,\u0004 שלא עשה מעשה חסימה, אלא כשהיתה אוכלת היה גוער בה, וכן אם \u0003הנהיגה\u0004 בכלאים \u0003בקול,\u0004 בלי לעשות בה מעשה, מה הדין? \u0003ר' יוחנן אמר: חייב, ריש לקיש אמר: פטור.\u0004 ומסבירים את טעמיהם, \u0003ר' יוחנן אמר: חייב,\u0004 שלדעתו \u0003עקימת פיו\u0004 בשעת דיבור \u0003הויא\u0004 \u0005[הרי היא]\u0006 \u0003מעשה,\u0004 ואף שהוא מעשה קטן — מכל מקום מעשה הוא. \u0003ריש לקיש אמר: פטור, קלא לא הוי\u0004 \u0005[קול איננו\u0006 נחשב\u0005]\u0006 \u0003מעשה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש:\u0004"],["\u0003לא שאדם רשאי להמיר, אלא שאם המיר\u0004 — \u0003מומר,\u0004 שחלה התמורה על בהמת החולין, \u0003וסופג את הארבעים,\u0004 שלוקה מלקות מן התורה. ומכאן שדיבור בלבד, אף בלא מעשה – נחשב, וחייב עליו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: לאו שאין בו מעשה\u0004 — \u0003לוקים עליו.\u0004 ואילו אנו דנים לשיטת חכמים, שאין נענשים על עבירה אלא אם כן עשה בה מעשה ממש.","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[האם יכול אתה להעמיד,\u0006 להסביר, \u0005אותה],\u0006 את המשנה הזאת \u0003כ\u0004שיטת \u0003ר' יהודה? והא קתני רישא\u0004 \u0005[והרי שנינו בראשה]:\u0006 \u0003הכל ממירין, אחד האנשים ואחד הנשים, והוינן\u0004 \u0005[היינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה:\u0004 לשון \u0003\"הכל\"\u0004 ששנינו \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה],\u0006 מה באה לשון זו להוסיף? ותירצנו: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003יורש\u0004 שאף הוא ממיר קרבן שירש, \u0003ו\u0004ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004","\u0003דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כשיטת \u0003ר' יהודה\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003יורש אינו ממיר, יורש אינו סומך!\u0004 את הקושי הזה דוחים: מכאן אין הוכחה גמורה, כי אפשר לומר: \u0003האי תנא סבר לה כוותיה בחדא, ופליג עליה בחדא\u0004 \u0005[תנא זה\u0006 של מסכת תמורה \u0005סבר כמותו ב\u0006דבר \u0005אחד וחלק עליו באחד].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החוסם את הפרה ודש בה – לוקה,\u0004 ונוסף לכך \u0003משלם\u0004 לבעל הפרה \u0003ארבעה קבין לפרה\u0004 שזה שיעור אכילתה הרגיל בזמן דישה, \u0003ושלשה קבין לחמור.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 כלל הוא בדיני עונשים שעבריין \u0003אינו לוקה ו\u0004גם \u0003מת\u0004 (נענש בעונש מוות), \u0003ו\u0004כן \u0003אינו לוקה ומשלם,\u0004 אלא מענישים עבריין רק בעונש אחד בלבד. \u0003אמר אביי: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר\u0004 בכלל: \u0003לוקה ומשלם.\u0004","\u0003רבא אמר\u0004 שיש מקום לחלק, שהרי האיסור הוא בינו ובין המקום ומשום כך לוקה, ואילו את ההפסד שגרם לבעל הפרה צריך הוא לשלם לו. וכשם שיש הלכה בענין אתנן זונה שאסור להשתמש בו לצרכי קרבנות ואמרו כל \u0003אתנן אסרה תורה, ואפילו בא על אמו\u0004 ונתן לה אתנן זה הריהו באיסור זה. ואם כן, אף שוודאי אין האיש מתחייב לשלם בבית דין, שהרי הוא חייב מיתה משום שעבר בביאה על אמו, מכל מקום יש לו התחייבות מסויימת לתת, ולכן חל האיסור עליו.","\u0003רב פפא אמר\u0004 שאפשר לתרץ באופן אחר: \u0003משעת משיכה\u0004 שמשך את הפרה כששכרה לדוש אצלו \u0003איחייב\u0004 \u0005[התחייב]\u0006 \u0003לה במזונותיה\u0004 שתאכל בשעת דישה, \u0003ומילקא\u0004 \u0005[וללקות]\u0006 הוא \u0003לא לקי\u0004 \u0005[לוקה]\u0006 \u0003עד שעת חסימה\u0004 ממש. וכיון שכך, נמצא שהתחייב בתשלום ממון קודם חיוב במלקות, שיש כאן שני חיובים שונים.","אגב הדיון בהלכות אלה, \u0003אמר רב פפא: הני מילי בעו מינאי דבי\u0004 \u0005[דברים אלה שאלו ממני,\u0006 אותי בני \u0005ביתו]\u0006 של \u0003רב פפא בר אבא, ופשטי להו לאיסורא\u0004 \u0005[ופתרתי,\u0006 עניתי, \u0005להם לאיסור]\u0006 בשניהם, \u0003חדא כהלכתא וחדא דלאו כהלכתא\u0004 \u0005[אחד\u0006 לפי \u0005ההלכה, ואחד שלא כהלכה].\u0006","\u0003בעו מינאי\u0004 \u0005[שאלו אותי]:\u0006 \u0003מהו\u0004 הדין בענין \u0003ללוש את העיסה\u0004 של בצק \u0003בחלב? ופשטי להו לאיסורא כהלכתא\u0004 \u0005[ופתרתי להם לאיסור כהלכה],\u0006 שכן שנויה ברייתא: \u0003אין לשין את העיסה בחלב\u0004 שמא יבוא לאכול מן הפת עם בשר, \u0003ואם לש\u0004 — \u0003כל הפת כולה אסורה, מפני הרגל עבירה. כיוצא בו אין טשין\u0004 (מורחים) \u0003את התנור באליה\u0004 (בשומן מאליית הכבש), \u0003ואם טש\u0004 — \u0003כל הפת כולה אסורה\u0004 מחשש שמא יאכל אותה עם חלב, \u0003עד שיסיק את התנור\u0004 בלי פת למשך זמן מסוים ותישרף המשיחה הזו.","\u0003ואידך בעו מינאי\u0004 \u0005[ו\u0006שאלה \u0005אחרת שאלו ממני,\u0006 אותי\u0005]:\u0006 \u0003מהו\u0004 הדין בענין \u0003להכניס\u0004 בעלי חיים זכר ונקבה \u0003מין ושאינו מינו לדיר\u0004 יחד, שהרי קיים חשש שמא יזדווגו, האם יש לחשוש משום איסור כלאיים, \u0003ופשטי להו לאיסורא דלאו כהלכתא\u0004 \u0005[ופתרתי להם לאיסור שלא\u0006 על פי \u0005ההלכה],\u0006 ש","\u0003אמר שמואל: ובמנאפים\u0004 מעידים עליהם העדים שנאפו זה עם זה \u0003עד שיראו\u0004 אותם שנוהגים הם \u0003כדרך המנאפים,\u0004 ואינם צריכים לראות את פרטי הפרטים של מעשה הביאה. אבל אם הרביע \u0003בכלאים\u0004 אין מענישים \u0003עד\u0004 שיעידו עליו \u0003שיכניס\u0004 אבר הזכר לנקבה \u0003כמכחול בשפופרת.\u0004 ואם כן, מובן מכאן שאין איסור בכלאים אלא במעשה גמור של הרבעה ביד, ואינו אסור כשרק היו יחד בדיר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אחדבוי בר אמי,\u0004 ממה ששנינו: \u0003אילו נאמר\u0004 רק \u0003\"בהמתך לא תרביע\"\u0004 (ויקרא יט, יט) \u0003הייתי אומר\u0004 שבכלל אסור לאדם לסייע בזיווג בעלי חיים, ולכן \u0003לא יאחוז אדם הבהמה בשעה שעולה עליה זכר,\u0004 ועל כן \u0003תלמוד לומר: \"כלאים\"\u0004 (שם), שרק בכלאים אסור הדבר ולא בבעלי חיים מאותו מין.","על כל פנים \u0003לאו\u0004 \u0005[האם לא]\u0006 תלמד \u0003מכלל\u0004 הדברים שב\u0003כלאים אחיזה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יעשה? ואם כן משמע שבכלאים אסורה לא רק הפעולה הממשית של זיווג בעלי החיים, אלא גם סיוע לכך (כאחיזה). ואם כן, הכנסה לדיר אחד אסורה מעיקר הדין! ודוחים: לא, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המושג \u0003\"אחיזה\"\u0004 האמור בברייתא זו — הכוונה היא \u0003הכנסה\u0004 ממש של האבר, \u0003ואמאי קרי\u0004 \u0005[ומדוע קורה]\u0006 \u0003לה \"אחיזה\"\u0004 — \u0003לישנא מעליא\u0004 \u0005[בלשון מעולה,\u0006 נקיה\u0005]\u0006 נקט, שאינו רוצה לומר במפורש.","\u0003אמר רב יהודה: מין במינו\u0004 כשרוצה לזווג אותם זכר ונקבה בהיתר, \u0003מותר להכניס כמכחול בשפופרת, ואפילו משום פריצותא ליכא\u0004 \u0005[פריצות\u0006 וחשש להרהור \u0005אין כאן].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003בעבידתיה טריד\u0004 \u0005[בעבודתו\u0006 הוא \u0005טרוד]\u0006 ואינו בא לידי הרהור פריצות. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אחדבוי בר אמי:\u0004"],["\u0003אלו נאמר\u0004 סתם \u0003\"בהמתך לא תרביע\" הייתי אומר: לא יאחוז אדם את הבהמה כדי שיעלה עליה זכר,\u0004 ועל כן \u0003תלמוד לומר: \"כלאים\".\u0004 ומכאן נלמד: \u0003כלאים הוא\u0004 ש\u0003אסור,\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מין במינו\u0004 — \u0003שרי\u0004 \u0005[מותר].\u0006","\u0003ו\u0004אולם \u0003מין במינו נמי\u0004 \u0005[גם כן]\u0006 \u0003אחיזה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מותרת, \u0003הכנסה\u0004 ממש — \u0003לא!\u0004 ודוחים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"אחיזה\"\u0004 כאן — \u0003הכנסה, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לה]\u0006 \u0003\"אחיזה\"\u0004 — משום \u0003לישנא מעליא\u0004 \u0005[לשון, מעולה,\u0006 נקיה\u0005].\u0006","\u0003אמר רב אשי: הא מילתא בעו מינאי דבי\u0004 \u0005[דבר זה שאלו ממני,\u0006 אותי בני \u0005ביתו]\u0006 של \u0003רב נחמיה ריש גלותא\u0004 \u0005[ראש הגולה]:\u0006 \u0003מהו\u0004 הדין בענין \u0003להכניס מין ומינו ושאינו מינו\u0004 יחד \u0003לדיר?\u0004 האם נאמר \u0003כיון דאיכא מיניה\u0004 \u0005[שיש\u0006 בן \u0005מינו]\u0006 — \u0003בתר מיניה גריר\u0004 \u0005[אחרי\u0006 בן \u0005מינו\u0006 הוא \u0005נגרר]\u0006 ואין לחשוש כלל לכלאים. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו הכי\u0004 \u0005[כך]\u0006 — \u0003לא\u0004 יעשה, שמא בכל זאת יבוא לרביעה? \u0003ופשטי להו לאיסורא\u0004 \u0005[ופתרתי להם\u0006 את השאלה \u0005לאיסור]\u0006 ש\u0003לא כהלכתא\u0004 \u0005[על פי ההלכה],\u0006 \u0003משום פריצותא דעבדי\u0004 \u0005[פריצותם של העבדים],\u0006 שאם יתירו להם יבואו להרביע כלאים בכוונה, ויאמר שמאליו נהיה הדבר.","\u0003היה\u0004 הפועל \u0003עושה\u0004 מלאכה \u0003בידיו אבל לא ברגליו,\u0004 או שהיה עושה \u0003ברגליו אבל לא בידיו\u0004 (כעין דריכת ענבים בגת), ו\u0003אפילו בכתיפו\u0004 לבד — \u0003הרי זה אוכל\u0004 מפירות השדה שעוסק בהם. \u0003ר' יוסי בר' יהודה אומר:\u0004 לא יאכל \u0003עד שיעשה בידיו וברגליו.\u0004","שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של חכמים בכך שלדעתם די בעשיית הפועל בידיו או רגליו בלבד? ומשיבים, שנאמר: \u0003\"כי תבא בכרם רעך\"\u0004 (דברים כג, כה) שלא פירט הכתוב בכך, וממילא הכוונה היא: \u0003בכל מאי דעביד\u0004 \u0005[מה ש\u0006הוא \u0005עושה].\u0006","שנינו במשנה ש\u0003ר' יוסי בר' יהודה אומר\u0004 שאין הפועל אוכל \u0003עד שיעשה בידיו וברגליו.\u0004 ושאלו: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי בר' יהודה?\u0004 ומסבירים: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003שור\u0004 בדישו, \u0003מה שור עד שיעשה בידיו וברגליו\u0004 שהרי דש הוא בכל ארבע רגליו — \u0003אף פועל עד שיעשה בידיו וברגליו.\u0004","באותו ענין \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה בר רב הונא: דש באווזין ותרנגולים\u0004 ולא בבהמה, \u0003ל\u0004שיטת \u0003ר' יוסי בר' יהודה מהו\u0004 הדין? וצדדי השאלה: האם דישה \u0003בכל כחו בעינן\u0004 \u0005[צריכים אנו],\u0006 ומטעם זה אמר שצריך לדוש בידיו וברגליו — \u0003והא איכא\u0004 \u0005[והרי יש כאן],\u0006 שהרי עופות אלה דשים בכל כחם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בידיו וברגליו\u0004 דווקא \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והא ליכא\u0004 \u0005[והרי אינו].\u0006 לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רב נחמן אמר רבה בר אבוה: פועלים\u0004 העובדים בכרם, \u0003עד שלא הילכו\u0004 (הלכו) \u0003שתי וערב בגת\u0004 שהיא תחילת מלאכת עשיית היין — \u0003אוכלין ענבים,\u0004 שהרי מלאכתם בענבים, אבל עדיין \u0003אין שותין יין\u0004 — לפי שאין עדיין יין מפרי מלאכתם. \u0003משהילכו שתי וערב בגת\u0004 נמצא שעבודתם היא גם ביין, ולכן \u0003אוכלין ענבים ושותין יין.\u0004","\u0003היה\u0004 הפועל \u0003עושה\u0004 מלאכה \u0003בתאנים\u0004 — \u0003לא יאכל בענבים\u0004, עושה מלאכה \u0003בענבים\u0004 — \u0003לא יאכל בתאנים,\u0004 שאינו אוכל אלא ממין שעובד בו. \u0003אבל\u0004 מותר לו להיות \u0003מונע את עצמו\u0004 מאכילה \u0003עד שמגיע למקום\u0004 ענבים או תאנים \u0003יפות ואוכל\u0004 מהן, שהרי הן מאותו מין שעושה בו.","\u0003וכולן לא אמרו אלא בשעת מלאכה\u0004 — באותה שעה יכול לקחת ולאכול, \u0003אבל משום השב אבידה לבעלים\u0004 כדי שלא יבטלו הפועלים ממלאכתם באכילה \u0003אמרו: פועלין אוכלין בהליכתן מאומן לאומן\u0004 (משורה לשורה בכרם או במטע), \u0003ובחזירתן\u0004 (כשחוזרים) \u0003מן הגת, ובחמור כשהיא פורקת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו בבירור הלכה שבמשנה: היה הפועל \u0003עושה בגפן זה, מהו שיאכל בגפן אחר?\u0004 האם רק \u0003ממין שאתה נותן לכליו של בעל הבית בעינן\u0004 \u0005[צריכים אנו]\u0006 — \u0003והא איכא\u0004 \u0005[והרי יש כאן]\u0006 ומתקיים תנאי זה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 דווקא \u0003ממה שאתה נותן לכליו של בעל הבית\u0004 מאותו דבר עצמו \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 — \u0003והא ליכא\u0004 \u0005[והרי איננו]?\u0006","\u0003ואם תמצי לומר\u0004 \u0005[תמצא לומר]\u0006 ותחליט שאכן \u0003עושה בגפן זה לא יאכל בגפן אחר,\u0004 יש לשאול שאלה נוספת: \u0003שור\u0004 שעושה מלאכה \u0003במחובר היכי אכיל\u0004 \u0005[כיצד\u0006 הוא רשאי \u0005לאכול]?\u0006 שהרי בשעה שעושה מלאכה עושה הוא ברגליו, וראשו נמצא במקום אחר, ונמצא שאיננו יכול לאכול ממש מאותו דבר שבו הוא עושה מלאכה! \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: בשרכא\u0004 \u0005[בענפים ארוכים]\u0006 שבהם יתכן שעושה מלאכה בקצה אחד של הענף, ומקצהו האחר אוכל. קושי זה נפתר, אבל גופה של השאלה צריכה תשובה.","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003היה עושה בתאנים\u0004 — \u0003לא יאכל בענבים,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היו אלה \u0003תאנים ותאנים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003תאנים וענבים\u0004 שאינם אותו דבר עצמו — מכל מקום \u0003אוכל. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי ה\u0003עושה בגפן זה אינו אוכל בגפן אחר, היכי משכחת לה\u0004 \u0005[כיצד אתה יכול למצוא אותה,\u0006 אפשרות כזו\u0005]?\u0006 \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 כאן מדובר \u0003ב\u0004גפן \u0003מודלית,\u0004 שיתכן שמעבד צד אחד שלה, ואילו האכילה היא מצד אחר.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מממה ששנינו עוד: \u0003אבל מונע\u0004 הפועל \u0003את עצמו\u0004 מאכילה \u0003עד שמגיע למקום היפות, ואוכל. ואי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי ה\u0003עושה בגפן זה אוכל בגפן אחר,\u0004 אם כן \u0003ניזיל וניתי וניכול\u0004 \u0005[שילך ויבוא ויאכל]\u0006 ולא יצטרך להמתין עד שיגיע לאותה גפן משובחת! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא \u0003משום ביטול מלאכה\u0004 שמבטל בהליכתו, ולכן \u0003לא קא מיבעיא לן\u0004 \u0005[נשאלה לנו]\u0006 שאלה זו שוודאי אסור לו לבטל ממלאכתו כדי לאכול במקום אחר, \u0003כי קא מבעיא לן היכא דאיכא\u0004 \u0005[כאשר נשאלה לנו\u0006 השאלה, הרי היא \u0005במקום שיש]\u0006 \u0003אשתו ובניו\u0004 שאינם עובדים, ומותרים לאכול — השאלה היא האם להם מותר לקטוף מאותם הפירות שאין הוא עושה בהם באותה שעה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003וכולם לא אמרו אלא בשעת מלאכה, אבל מפני השב אבידה לבעלים אמרו: פועלים אוכלים בהליכתן מאומן לאומן ובחזירתן מן הגת.\u0004","\u0003סברוה\u0004 \u0005[סברו]\u0006 לומר, כהנחה יסודית בפתרון שאלה זו, שהפועל ה\u0003מהלך כעושה מעשה\u0004 מלאכה \u0003דמי\u0004 \u0005[נחשב],\u0006 שהילוכו זה נחשב כחלק מעבודתו והיה ראוי לו לאכול באותה שעה, \u0003ו\u0004בכל זאת שנינו ש\u0003משום השב אבידה לבעלים הוא דאכיל\u0004 \u0005[שאוכל]\u0006 ואילו \u0003מדאורייתא לא אכיל\u0004 \u0005[מדין תורה אינו אוכל],\u0006 ואם עובד מדוע אינו אוכל? \u0003אלמא\u0004 \u0005[מכאן]\u0006 שה\u0003עושה בגפן זה אינו אוכל בגפן אחר,\u0004 ולכן כשמהלך ואינו עוד בצד הגפן — אסור היה לו מדין תורה לאכול.","ודוחים: \u0003לא, לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי ה\u0003עושה בגפן זה\u0004 אף \u0003אוכל בגפן אחר,\u0004 אלא \u0003מהלך לאו\u0004 \u0005[לא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[נחשב],\u0006 ומדין תורה אינו אוכל באותה שעה, אלא אמרו חכמים שיאכל אז כדי שלא יימצאו הבעלים מפסידים מזמן עבודתו על ידי אכילתו. בעיה זו היתה לה גם נוסחא אחרת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003סברוה\u0004 \u0005[סברו\u0006 חכמים\u0005]\u0006 כהנחת יסוד לומר ש\u0003מהלך לאו\u0004 \u0005[לא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[נחשב]\u0006 \u0003והיינו טעמא דמדאורייתא לא אכיל\u0004 \u0005[זה הטעם שמן התורה אינו אוכל]\u0006 — \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[נחשב],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 את היה \u0003עושה מעשה\u0004 — הריהו \u0003אוכל מדאורייתא\u0004 \u0005[מדין תורה],\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003עושה בגפן זה אוכל בגפן אחר!\u0004","ודוחים: \u0003לא,\u0004 משם אין ראיה ו\u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שה\u0003עושה בגפן זה אינו אוכל בגפן אחר,\u0004"],["\u0003מהלך כעושה מעשה דמי\u0004 \u0005[נחשב]\u0006 ולכן מעיקר הדין היה יכול לאכול, אלא שהגבילו חכמים לזמן זה רק משום העבודה.","שנינו במשנה: \u0003ובחמור כשהיא פורקת.\u0004 ותוהים: \u0003כשהיא פורקת מהיכן אכלה\u0004 הלא נפרק ממנה משאה! אלא \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003עד שתהא פורקת,\u0004 כלומר, במשך הזמן שהיא נושאת משאה עד שהיא פורקת יכולה היא לאכול מן המטען שעל גבה. ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו\u0006 דבר \u0005זה]\u0006 במפורש, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003חמור וגמל אוכלים ממשאוי שעל גביהן, ובלבד שלא יטול\u0004 בעל הבהמות \u0003בידו\u0004 מן המשא \u0003ויאכילם.\u0004","\u0003אוכל פועל\u0004 בשעת מלאכתו \u0003קישות ואפילו ב\u0004שווי \u0003דינר,\u0004 אוכל \u0003כותבת\u0004 (תמרים) \u0003ואפילו ב\u0004שווי \u0003דינר. ר' אלעזר חסמא אומר: לא יאכל פועל\u0004 על כל פנים \u0003יתר על שכרו, וחכמים מתירין\u0004 מצד הדין. \u0003אבל מלמדין את האדם שלא יהא רעבתן ויהא סותם\u0004 בכך \u0003את הפתח בפניו\u0004 מלהתפרנס, שהרי כשידעו בו שהוא זולל כך לא ישכרוהו עוד למלאכה.","שואלים: שיטת \u0003חכמים היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003ה\u0004\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה טעם לחזור ולשנות אותה שיטה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל ביחס לענין \u0003\"אבל מלמדין\", ל\u0004דעת ה\u0003תנא קמא לית ליה\u0004 \u0005[אין לו]\u0006 ענין זה ש\u0003\"מלמדין\"\u0004 ויעשה הפועל כרצונו. \u0003לרבנן אית להו\u0004 \u0005[ל\u0006דעת \u0005חכמים\u0006 שבסוף \u0005יש להם]\u0006 ענין זה ש\u0003\"מלמדין\",\u0004 שראוי לתת לפועל עצה טובה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי ההלכה שאמר \u0003רב אסי.\u0004 ש\u0003אמר רב אסי: אפילו לא שכרו אלא לבצור אשכול אחד\u0004 — \u0003אוכלו\u0004 הפועל. \u0003ואמר רב אסי: אפילו לא בצר אלא אשכול אחד\u0004 — \u0003אוכלו.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיאמר את שתי ההלכות הללו אף שהן לכאורה זהות, \u0003דאי אשמעינן הך קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 את \u0005זו הראשונה]\u0006 — הייתי אומר שכן הדין \u0003משום דלא איכא למיתב\u0004 \u0005[משום שאין מקום להשיב]\u0006 \u0003לכליו של בעל הבית,\u0004 שהרי שכרו בעל הבית לבצור רק אשכול זה ולא יותר, והוא השתמש בזכותו לאכול ממה שעובד בו. \u0003אבל היכא דאיכא למיתב\u0004 \u0005[במקום שיש להשיב]\u0006 \u0003לכליו של בעל הבית\u0004 — \u0003אימא ליתב ברישא, והדר ליכול\u0004 \u0005[אמור שיתן מתחילה ואחר כך יאכל].\u0006","\u0003ואי אשמעינן בהא\u0004 \u0005[ואם היה משמיע לנו בזו]\u0006 — שהרי \u0003אפשר לקיומי\u0004 \u0005[לקיים]\u0006 \u0003לבסוף\u0004 נתינה לכלי בעל הבית, \u0003אבל היכא דלא אפשר לקיומי\u0004 \u0005[במקום שאי אפשר לקיים]\u0006 \u0003לבסוף\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 בין תנא קמא וחכמים אחרונים הבדל בענין ההלכה שאמר רב. ש\u0003אמר רב: מצאתי מגילת סתרים\u0004 — מגילה שהיו כתובות בה הלכות בקיצור, שכיון שלא הותרה בדורות ראשונים כתיבת תורה שבעל פה היו רושמים רק רשימות קצרות ושומרים אותן בסתר, \u0003בי\u0004 \u0005[בבית]\u0006 \u0003ר' חייא, וכתוב בה\u0004 במגילה זו: \u0003איסי בן יהודה אומר:\u0004 מה שנאמר \u0003\"כי תבא בכרם רעך\u0004 ואכלת ענבים כנפשך שבעך\u0003\"\u0004 (דברים כג, כה) — \u0003בביאת כל אדם\u0004 העובר ליד הכרם \u0003הכתוב מדבר,\u0004 ולאו דווקא בפועל.","\u0003ואמר רב\u0004 על כך: \u0003לא שבק\u0004 \u0005[הניח]\u0006 \u0003איסי חיי\u0004 \u0005[חיים]\u0006 \u0003לכל בריה,\u0004 שהרי אפשר שיבואו אנשים רבים ויאכלו את כל פירות הכרם. ותנא קמא סבור כרב, וחכמים אחרונים סבורים כאיסי, שמצד הדין אין כל מניעה, שהרי יכול לאכול גם בלא שיהא שכיר.","\u0003אמר רב אשי: אמריתה לשמעתא קמיה\u0004 \u0005[אמרתי הלכה\u0006 זו \u0005לפני]\u0006 \u0003רב כהנא:\u0004 \u0003דלמא\u0004 \u0005[שמא]\u0006 אמר איסי \u0003ב\u0004פועלים ה\u0003עושין\u0004 מלאכה \u0003ב\u0004שכר \u0003סעודתם, דעבדו ואכלו\u0004 \u0005[ש\u0006הם \u0005עובדים ואוכלים]?\u0006 \u0003אמר לי: אפילו הכי\u0004 \u0005[כך],\u0006 \u0003ניחא ליה לאיניש לאוגר אגורי וניקטפיה לפרדיסיה\u0004 \u0005[נוח לו לאדם לשכור שכירים ולקטוף את פרדסו]\u0006 \u0003ו\u0004ש\u0003לא ניתו כולי עלמא ואכלו ליה\u0004 \u0005[יבואו כל העולם ויאכלו אותו].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003פועל\u0004 האוכל בשעת מלאכתו האם \u0003משלו הוא אוכל,\u0004 כלומר, זכות זו נחשבת לו כתוספת שכר רגילה ודינה כרכושו הפרטי, \u0003או משל שמים הוא אוכל,\u0004 כלומר, שהתורה נתנה לו זכות זו כמתנה מיוחדת.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 מה ההבדל למעשה אם זה או זה הוא הטעם? ומשיבים: כגון ש\u0003אמר\u0004 \"אני איני אוכל, אבל \u0003תנו לאשתי ובני\u0004 שיאכלו במקומי\". \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003משלו הוא אוכל\u0004 — \u0003יהבינן להו\u0004 \u0005[נותנים אנו להם],\u0006 שהרי שלו הוא זה, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003משל שמים הוא אוכל\u0004 — \u0003לדידיה זכי ליה רחמנא\u0004 \u0005[לו\u0006 עצמו \u0005זיכתה לו התורה],\u0006 \u0003לאשתו ובניו\u0004 — \u0003לא זכי להו רחמנא\u0004 \u0005[זיכתה להם התורה]\u0006 ואם כן, \u0003מאי\u0004 \u0005[מה]\u0006 הדין?","ומציעים, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003אוכל פועל קישות ואפילו ב\u0004שווי \u0003דינר,\u0004 וכן \u0003כותבת ואפילו ב\u0004שווי \u0003דינר.\u0004 ומעתה \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003משלו הוא אוכל,\u0004 וכי אפשר לומר \u0003אוגיר בדנקא אכיל בזוזא\u0004 \u0005[נשכר בששית\u0006 הדינר \u0005ואוכל בדינר\u0006 שלם\u0005]?!\u0006 ודוחים: \u0003ואלא מאי\u0004 \u0005[מה\u0006 תאמר\u0005]\u0006 — \u0003משל שמים הוא אוכל, סוף סוף\u0004 גם שם \u0003אוגיר בדנקא אכיל בזוזא\u0004 \u0005[נשכר בששית אוכל בדינר]!\u0006 \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 — כי \u0003רחמנא זכי ליה\u0004 \u0005[התורה\u0006 היא ש\u0005זיכתה לו]\u0006 ואפילו יותר על שכרו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר כי \u0003רחמנא זכי ליה\u0004 \u0005[התורה זיכתה לו].\u0006","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו, \u0003ר' אלעזר חסמא אומר: לא יאכל פועל יותר על שכרו, וחכמים מתירין. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006נושא \u0005זה נחלקו];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אלעזר, \u0005סבור]\u0006 כי \u0003משלו הוא אוכל, ומר סבר\u0004 \u0005[וחכם זה\u0006 חכמים, \u0005סבורים]\u0006 כי \u0003משל שמים הוא אוכל.\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003משלו הוא אוכל, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004פירוש המלה \u0003\"כנפשך\" קמיפלגי\u0004 \u0005[חלוקים הם]\u0006 כיצד יש להבין את הכתוב בענייננו \"ואכלת ענבים כנפשך שבעך\" (דברים כג, כה). \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבורים]\u0006 כי \u0003\"כנפשך\"\u0004 פירושו: \u0003בדבר שמוסר נפשו עליו,\u0004 כלומר, כיון שהפועל נשכר לעבודה ומקבל על עצמו גם סכנת נפשות העלולה להיות בה — לכן נקנית לו זכות האכילה ואף יותר משכרו,","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר, \u0005סבור]\u0006 שלהיפך \u0003\"כנפשך\"\u0004 בא למעט: \u0003מה נפשך\u0004 עצמך, בעל הבית \u0003אם חסמת\u0004 — \u0003פטור, אף פועל אם חסמת\u0004 — \u0003פטור\u0004 שיש מקרים בהם הפועל אינו זכאי לאכול, ובכלל זה גם ביותר משכרו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003נזיר ש\u0004היה עובד בכרם ו\u0003אמר: \"תנו לאשתו ובניו\u0004 של הפועל \u0003\",\u0004 כלומר לאשתי ובני — \u0003אין שומעין לו. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משלו הוא אוכל\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין שומעין לו?\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא אחר, \u0003משום\u0004 הפתגם המקובל לגבי נזיר: \"\u0003לך לך\" אמרין נזירא\u0004 \u0005[אומרים לנזיר],\u0006 \u0003\"סחור סחור לכרמא\u0004 \u0005[סביב סביב לכרם]\u0006 \u0003לא תקרב\",\u0004 וכדי להרחיק את הנזיר מפיתוי קנסוהו שלא יוכל לתת מפירות עבודתו למשפחתו, כדי שלא יקבל עבודה בכרמים, והטעם הוא איפוא מחשש איסור ולא מצד הלכות פועלים.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003פועל שאמר \"תנו\u0004 מן הפירות \u0003לאשתי ובני\"\u0004 — \u0003אין שומעין לו. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משלו הוא אוכל\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין שומעין לו?\u0004 ודוחים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"פועל\"\u0004 כאן — הכוונה היא לפועל \u0003נזיר.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 ברייתא \u0003אחת ב\u0004\u0003נזיר והתניא\u0004 \u0005[והרי שנינו]\u0006 ברייתא \u0003אחרת ב\u0004\u0003פועל,\u0004 ומשמע ששתי הלכות שונות הן! ודוחים: \u0003מידי גבי הדדי תניין\u0004 \u0005[וכי זו ליד זו הן שנויות]\u0006 שאפשר ללימוד משינוי הסגנון? הלא אלה הן שתי ברייתות נפרדות ומשינוי הלשון ביניהן אין להוכיח שמדובר בשתי הלכות שונות.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא אחרת: \u0003מנין לפועל שאמר \"תנו\u0004 מן הפירות \u0003לאשתי ובני\" שאין שומעין לו, שנאמר: \"ואל כליך לא תתן\"\u0004 (שם). \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ב\u0003נזיר,\u0004 \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הרי לא \u0003משום \"אל כליך לא תתן\"\u0004 הוא הטעם, אלא \u0003משום\u0004 הפתגם המקובל \u0003\"לך לך\" אמרין נזירא\u0004 \u0005[אומרים לנזיר]\u0006 \u0003הוא\u0004 הטעם!","ודוחים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן]\u0006 שמדובר כאן בנזיר, \u0003ו\u0004לענין השאלה שהועלתה — \u0003איידי דקתני לה\u0004 \u0005[כיון ששנה אותה,\u0006 את ההלכה הזו\u0005]\u0006 \u0003בלשון \"פועל\"\u0004 ולא פירש שהוא נזיר — \u0003קא נסיב לה קרא\u0004 \u0005[הביא את הכתוב]\u0006 של ה\u0003פועל,\u0004 אבל זה איננו מקור הדין, ועיקר הטעם הוא משום הנזירות, ולפועל אחר מותר.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003השוכר את הפועל לקצות בתאנים\u0004 (להכשיר תאנים לייבוש כקציעות)"],["\u0003הרי זה אוכל ופטור מן המעשר,\u0004 שכיון שהתורה נתנה לו היתר לאכול — אוכל באותה שעה ואינו מעשר, כשאר מתנות עניים שאין מעשרים מהן. אבל התנה ואמר \u0003\"על מנת שאוכל אני ובני\", או \"\u0004על מנת \u0003שיאכל בני בשכרי\"\u0004 — \u0003הוא אוכל ופטור\u0004 ממעשר, שהרי הוא אוכל מדין תורה, \u0003ובנו אוכל וחייב\u0004 להפריש מעשר.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משלו הוא אוכל, בנו אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב?\u0004 הלא הבן אוכל משל אביו, ופירות אלה לא נתחייבו! \u0003אמר רבינא:\u0004 אפשר לומר \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כמקח,\u0004 שאף שמדין תורה הפירות של הפועל הם, כיון שנעשתה כאן איזו עיסקה ומשתפים את הבן — נראה זה כעין מקח וממכר, ואז צריך להפריש מעשר כדי שלא לגרום לטעות.","ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003השוכר את הפועל לעשות בנטע רבעי שלו,\u0004 במטע עצים בשנה הרביעית לנטיעתו שצריך להעלות פירותיו לירושלים ולאכלם שם — \u0003הרי אלו לא יאכלו,\u0004 שהרי הפירות אסורים מחוץ לירושלים. \u0003ואם לא הודיעם\u0004 לפועלים מראש שנטע רבעי הוא, ושאינם אוכלים פירות, ונמצא שנשכרו בטעות — בכגון זה \u0003פודה\u0004 מן הפירות \u0003ומאכילן.\u0004","\u0003ואי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003משל שמים הוא אוכל\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פודה ומאכילן?\u0004 הלא \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003לא זכי להו רחמנא\u0004 \u0005[זיכתה להם התורה]\u0006 שהרי זכות זו שנתנה התורה לפועל עצמו לאכול ודאי היא רק בדברים שמותר לאכול מהם ולא באחרים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 הדבר \u0003כמקח טעות,\u0004 שעל מנת שלא לאכול לא נשכרו הפועלים ומשום כך צריך לתת להם.","ומביאים ראיה אחרת, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא: \u0003נתפרסו\u0004 (התפרקו והתפוררו) \u0003עגוליו\u0004 שנכבשו קודם התאנים בתוכו, וצריך לחזור ולכובשן, או \u0003נתפתחו\u0004 מגופות \u0003חביותיו\u0004 של יין ושוכר פועלים כדי לחזור ולסתמן — \u0003הרי אלו לא יאכלו,\u0004 כיון שהתאנים והיין התחייבו כבר במעשרות, ומאותה שעה שוב אין פועל אוכל, \u0003ואם לא הודיען\u0004 בשעה ששכרן שאסורים הם באכילה — הריהו \u0003מעשר ומאכילן. ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 כי \u0003משל שמים הוא אוכל, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעשר ומאכילן?\u0004 הלא \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003לא זכי להו רחמנא\u0004 \u0005[זיכתה להם התורה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003משום דמיחזי\u0004 \u0005[שנראה]\u0006 הדבר \u0003כמקח טעות, בשלמא\u0004 \u0005[נניח]\u0006 במקרה \u0003ש\u0004\u0003נתפרסו עגוליו\u0004 — \u0003מיחזי\u0004 \u0005[נראה]\u0006 \u0003כמקח טעות\u0004 שהרי אין הפועלים יודעים שהתאנים כבר היו בעיגול, וסבורים שעדיין לא נגמרו למעשר. \u0003אלא נתפתחו חביותיו מאי\u0004 \u0005[מה]\u0006 \u0003מקח טעות איכא\u0004 \u0005[יש\u0006 כאן\u0005]?\u0006 הלא \u0003מידע ידע דאיטביל להו\u0004 \u0005[הלא יודעים הם שכבר נעשו טבל]\u0006 \u0003ל\u0004ענין \u0003מעשר,\u0004 שכן משנאסף היין לבור שליד הגת — כבר התחייב במעשר!","\u0003אמר רב ששת:\u0004 כאן מדובר \u0003שנתפתחו חביותיו\u0004 באופן שנשפך יינן שוב \u0003לבור\u0004 היין וסבורים שעוד לא נתחייבו במעשר, ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005];\u0006 \u0003יין\u0004 חייב במעשרות מיד \u0003משירד לבור!\u0004","ומשיבים: הרי זה \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 שיין חייב במעשר רק \u0003משיקפה\u0004 (משמתחילים להוציא את הגרעינים והפסולת הצפה), \u0003דאמרו ליה\u0004 \u0005[שאומרים הם לו]:\u0006 \u0003לא הוה ידעינן\u0004 \u0005[היינו יודעים]\u0006 שכבר הוצא היין מן הבור. ושואלים, \u0003ונימא להו\u0004 \u0005[ושיאמר להם]:\u0006 \u0003איבעי לכו אסוקי אדעתייכו דלמא מקפה\u0004 \u0005[צריכים הייתם להעלות על דעתכם שמא\u0006 כבר \u0005הוקפה]!\u0006 ומשיבים: \u0003באתרא דההוא גברא דנגיד איהו מקפה\u0004 \u0005[במקום שאותו\u0006 אדם \u0005שמושך\u0006 ומוציא מן הבור \u0005הוא\u0006 גם ש\u0005מקפה]!\u0006 ולכן חשבו שמלאכה זו עדיין לא נעשתה.","ומעירים עוד: \u0003והשתא דתני\u0004 \u0005[ועכשיו ששנה]\u0006 \u0003רב זביד\u0004 ממקור שנוסח \u0003בדבי\u0004 \u0005[בבית\u0006 המדרש\u0005]\u0006 של \u0003ר' הושעיא: יין\u0004 חייב במעשר \u0003משירד לבור ויקפה, ו\u0004\u0003ר' עקיבא אומר: משישלה בחביות,\u0004 ששופכים את היין לחבית ולאחר שנגמרת התסיסה שולים ומוציאים את כל הפסולת. אם כן \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ותפרש \u0003שלא נתפתחו חביותיו לבור\u0004 אלא נפתחו בלבד, \u0003דאמרו ליה\u0004 \u0005[שאומרים לו]:\u0006 \u0003לא הוה ידעינן דמשלי\u0004 \u0005[ידענו שכבר שלו\u0006 את הפסולת\u0005].\u0006","ושואלים, \u0003ונימא להו\u0004 \u0005[ושיאמר להם]:\u0006 \u0003איבעי לכו אסוקי אדעתייכו דלמא משלי\u0004 \u0005[היה לכם להעלות על דעתכם שמא\u0006 כבר \u0005נשלה]!\u0006 ומשיבים: \u0003באתרא\u0004 \u0005[במקום]\u0006 ש\u0003ההוא דשריק\u0004 \u0005[שמגיף\u0006 את החביות במגופה\u0005]\u0006 \u0003ההוא\u0004 גם \u0003משלי\u0004 \u0005[שולה\u0006 את פסולתן\u0005],\u0006 ולכן סברו שנשכרו לשתי העבודות יחד.","\u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה: \u0003קוצץ\u0004 (קובע) \u0003אדם על ידי עצמו\u0004 מחיר מסויים כתוספת שכר על מנת שלא יאכל מן הפירות שעובד בהם, וכן קוצץ \u0003על ידי\u0004 (עבור) \u0003בנו ובתו הגדולים, על ידי עבדו ושפחתו הגדולים, ועל ידי אשתו\u0004 — \u0003מפני שיש בהן דעת\u0004 ויכולים לוותר על זכותם. \u0003אבל אינו קוצץ לא על ידי בנו ובתו הקטנים, ולא על ידי עבדו ושפחתו הקטנים, ולא על ידי בהמתו\u0004 — \u0003מפני שאין בהן דעת.\u0004","\u0003קא סלקא דעתך\u0004 \u0005[עלתה על הדעת]\u0006 שכל אלה הם \u0003ב\u0004מקרה ש\u0003מעלה\u0004 (נותן) \u0003להן\u0004 בעל הבית \u0003מזונות\u0004 והן מסייעים לפועל בעבודתו אצל בעל הבית. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003משל שמים הוא אוכל\u0004 — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אינו קוצץ\u0004 עבור הקטנים, שהרי התורה זיכתה אף לאותם קטנים לאכול בשעת מלאכה, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003משלו הוא אוכל\u0004 ויש כאן התחייבות ממונית בלבד — \u0003קטנים נמי נקוץ להו\u0004 \u0005[גם כן שיקצוץ להם]!\u0006","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשאין מעלה להן מזונות.\u0004 והם מסייעים לעבודת אביהם בלא לקבל כל תשלום, אף במזונות. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003גדולים נמי\u0004 \u0005[גם כן]\u0006 יתן להם! ומשיבים: \u0003גדולים ידעי וקא מחלי\u0004 \u0005[יודעים\u0006 על התנאי \u0005ומוחלים]\u0006 ואילו הקטנים אינם יכולים למחול.","ושואלים: \u0003והא תנא\u0004 \u0005[והרי שנה]\u0006 \u0003ר' הושעיא\u0004 בברייתא אחרת: \u0003קוצץ אדם על ידי עצמו ועל ידי אשתו אבל לא על ידי בהמתו, ועל ידי בנו ובתו הגדולים אבל לא על ידי בנו ובתו הקטנים, וקוצץ על ידי עבדו ושפחתו הכנענים בין גדולים ובין קטנים.\u0004 ואילו במשנה הקודמת נאמר שאינו יכול לקצוץ עבור עבד קטן.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש, כי \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 בשני המקורות מדובר \u0003במעלה להן מזונות,\u0004 \u0003ו\u0004אם כן עלינו לפרש כי \u0003בהא קא מיפלגי\u0004 \u0005[ב\u0006ענין \u0005זה נחלקו];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 במשנה \u0005סבור]\u0006 כי \u0003משלו הוא אוכל\u0004 ולכן יכול לוותר עבור עבדו הקטן, \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 בברייתא \u0005סבור]\u0006 כי \u0003משל שמים הוא אוכל?!\u0004 ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003משלו הוא אוכל, ולא קשיא\u0004 \u0005[ואינו קשה];\u0006 \u0003כאן\u0004 במשנה מדובר כפי שפירשנו \u0003בשאין מעלה להן מזונות, וברייתא\u0004 — \u0003במעלה להן מזונות.\u0004","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את הברייתא — \u0003במעלה להן\u0004 מזונות, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003קטנים נמי נקוץ להו\u0004 \u0005[גם כן שיקצוץ להם]\u0006 ויקבע מראש שאף הם יוותרו! ומשיבים: את \u0003צערייהו\u0004 \u0005[צערם]\u0006 של \u0003בנו ובתו הקטנים לא זכי ליה רחמנא\u0004 \u0005[זיכתה לו התורה]\u0006 שיוכל לוותר על כך, שכיון שרואים שיש אוכל הם מצטערים אם הם חייבים לוותר עליו.","ושואלים: \u0003במאי אוקימתא למתניתין\u0004 \u0005[במה העמדת,\u0006 הסברת, \u0005את משנתנו]\u0006 — \u0003בשאין מעלה להן מזונות,\u0004"],["\u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003אין הרב\u0004 (בעלים) \u0003יכול לומר\u0004 \u0003לעבד: עשה\u0004 (עבוד) \u0003עמי ואיני זנך,\u0004 אלא חובה היא עליו לפרנסו ובענייננו שאין האדון (הפועל) יכול לקצוץ ולוותר על שכר העבדים, לשיטה זו — \u0003שפיר\u0004 \u0005[יפה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003יכול הרב לומר לעבד: עשה עמי ואיני זנך, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי יכול לקצוץ בכל מקרה, גם אם לא יקבל העבד מאומה!","\u0003אלא\u0004 לשיטה זו יש לפרש אחרת, \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 במשנה ובברייתא, מדובר \u0003ב\u0004אופן \u0003שאין מעלה להן מזונות, ובהא פליגי\u0004 \u0005[וב\u0006נושא \u0005זה\u0006 עצמו \u0005חלוקים\u0006 הם\u0005];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה סבור]:\u0006 \u0003יכול\u0004 הרב לומר לעבדו איני מפרנסך, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]\u0006 \u0003אין יכול.\u0004 ותוהים: אם כן נמצא כי \u0003ר' יוחנן,\u0004 ש\u0003אמר: יכול הרב, שביק מתניתין ועביד\u0004 \u0005[עזב את משנתנו ועשה,\u0006 פסק\u0005]\u0006 \u0003כברייתא?!\u0004","\u0003אלא\u0004 צריכים אנחנו לחזור בנו מן ההסבר הקודם ולישב כך: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003משל שמים הוא אוכל,\u0004 ואפילו אם הרב מעלה לו מזונות, \u0003ולא מצי קציץ\u0004 \u0005[ואינו יכול לקצוץ],\u0006 שהרי אין זכות באכילה שלו. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"קוצץ\"\u0004 ש\u0003אמר ר' הושעיא\u0004 — אין הכוונה כמו במשנה שמוותר על זכות האכילה של העובדים, אלא שקוצץ ומקציב \u0003מזונות,\u0004 שיאכלו אלה לשבעה קודם עבודתם וימנעו מאכילה אחר כך.","ומקשים: אם כן \u0003דכוותיה\u0004 \u0005[כיוצא בזה]\u0006 \u0003גבי בהמתו\u0004 אין כאן שום מקום לדיון \u0003תבן נקוץ לה\u0004 (יתן לה) קודם עבודתה, שהרי זה מותר לדעת הכל! \u0003אלא\u0004 יש לחזור מפירוש זה ולומר כי \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006ענין \u0005זה חלוקים הם];\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה סבור]:\u0006 \u0003משלו הוא אוכל, ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003משל שמים הוא אוכל?\u0004 והוכחנו איפוא שהבעיה שעמדה בפנינו תחילה כבר היתה שנויה במחלוקת תנאים.","\u0003קוצץ אדם על ידי עצמו,\u0004 שיקבל תוספת שכר ולא יאכל מן הפירות בזמן העבודה, וכן קוצץ \u0003על ידי\u0004 (לצורך) \u0003בנו ובתו הגדולים, על ידי עבדו ושפחתו הגדולים,\u0004 ו\u0003על ידי אשתו, מפני שיש בהן\u0004 בכל המנויים כאן \u0003דעת,\u0004 והם יכולים לוותר על זכותם המוקנית להם מן התורה. \u0003אבל אינו קוצץ על ידי בנו ובתו הקטנים, ולא על ידי עבדו ושפחתו הקטנים ולא על ידי בהמתו, מפני שאין בהן דעת\u0004 ולכן אינם יכולים לוותר.","\u0003השוכר את הפועלים לעשות בנטע רבעי\u0004 (מטע פירות בשנה הרביעית לנטיעתו) \u0003שלו,\u0004 כיון שנטע רבעי אסור באכילה עד שיביאנו לירושלים — \u0003הרי אלו לא יאכלו.\u0004 ו\u0003אם לא הודיען\u0004 מראש שיעבדו בנטע רבעי — \u0003פודה\u0004 מן האוכל \u0003ומאכילן\u0004 בו. שהרי גם על דעת אכילה מן הפירות נשכרו לעבודתם, \u0003נתפרסו\u0004 (נתפרקו והתפוררו) \u0003עגולי\u0004 הדבילה שלו וצריך לחזור ולכבוש את התאנים, \u0003נתפתחו חביותיו\u0004 וצריך לסותמן — \u0003הרי אלו לא יאכלו,\u0004 שכיון שכבר נגמרה מלאכתם למעשר — אין אוכלים מהם בלא עישור. \u0003אם לא הודיען\u0004 מראש שכך הוא — \u0003מעשר ומאכילן.\u0004","\u0003שומרי פירות אוכלין\u0004 בפירות השדה או הכרם \u0003מהלכות מדינה,\u0004 כלומר, על פי התקנות שהתקינו והסכימו לעצמם בני המדינה, \u0003אבל לא מן התורה.\u0004","דובר במשנה בענין \u0003שומרי פירות. אמר רב: לא שנו\u0004 הלכה זו במשנתנו אלא לענין \u0003שומרי גנות ופרדסין\u0004 דווקא, שכיון שהפירות עדיין מחוברים אין להם כל זכות בהם, ורק מכח התקנה הם אוכלים. \u0003אבל שומרי גיתות וערימות\u0004 ששומרים על פירות תלושים — \u0003אוכלים מן התורה,\u0004 שאין חילוק אלא בין שומרי פירות תלושים או מחוברים. \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003משמר כעושה מעשה דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","ואילו \u0003שמואל אמר:\u0004 \u0003לא שנו\u0004 הלכה זו במשנתנו \u0003אלא\u0004 לענין \u0003שומרי גיתות וערימות\u0004 שאוכלין לפי מנהג המדינה. \u0003אבל שומרי גנות ופרדסים\u0004 — \u0003אינן אוכלים לא מן התורה ולא מהלכות מדינה.\u0004 ומסבירים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003משמר לאו\u0004 \u0005[לא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ולכן אין כל שומר זכאי לאכול מדין תורה, אלא שנהגו בני המדינה להתיר בשומרי פירות תלושים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על סברה זו \u0003רב אחא בר רב הונא,\u0004 ממה ששנינו: \u0003המשמר את הפרה\u0004 האדומה לאחר שריפתה — \u0003מטמא בגדים\u0004 ככל שאר העוסקים בפרה אדומה, שאמרה תורה שנטמאים בגדיהם. ולענייננו: \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משמר לאו\u0004 \u0005[לא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מטמא בגדים?\u0004 הלא לא עשה דבר! \u0003אמר רבה בר עולא:\u0004 אינו מטמא מחמת שמירתו, אלא מפני \u0003גזירה שמא יזיז בה אבר.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב כהנא\u0004 ממה ששנינו: \u0003המשמר ארבע וחמש מקשאות\u0004 (שדות שמגדלים בהם מיני קשואים ודלעת) השייכים לאנשים שונים — \u0003הרי זה לא ימלא כרסו מ\u0004שדה \u0003אחד מהן\u0004 בלבד, \u0003אלא מכל אחד ואחד אוכל לפי חשבון. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003משמר לאו\u0004 \u0005[לא]\u0006 \u0003כעושה מעשה דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אוכל\u0004 בכלל?","\u0003אמר רב שימי בר אשי:\u0004 כאן \u0003ב\u0004קישואים \u0003עקורין שנו\u0004 שאמרנו שאף לשמואל אוכל בהם מהלכות מדינה. ומקשים: \u0003עקורין\u0004 — \u0003והלא\u0004 כבר \u0003נגמרה מלאכתן למעשר,\u0004 ואמרנו שפירות שנגמרה מלאכתן אין הפועל אוכל מהן, ומשיבים: מדובר באופן \u0003שלא ניטל\u0004 עדיין \u0003פיקס שלהם,\u0004 שעדיין לא נבל הפרח היבש שבראש הפרי, שזהו סוף מלאכתן. וכיון שעדיין לא נגמרה מלאכתן — אינם חייבים עדיין במעשר.","\u0003א\u0004 \u0003מר רב אשי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003שמואל מסתברא\u0004 \u0005[מסתבר]\u0006 לומר: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ואלו אוכלין מן התורה: העושה במחובר לקרקע בשעת גמר מלאכה, ובתלוש\u0004 עד שלא נגמרה מלאכתו. ומלשון המשנה (\"מן התורה\") אפשר לדייק: \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא דלא קא אכיל\u0004 \u0005[שיש מי שאינו אוכל]\u0006 \u0003מן התורה אלא מהלכות מדינה.\u0004","ומעתה \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה משנה, ששנינו: \u0003ואלו שאינן אוכלין.\u0004 ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינן אוכלין\"? אילימא\u0004 \u0005[אם תאמר]\u0006 הכוונה היא \u0003שאין אוכלין מן התורה אלא מהלכות מדינה\u0004 — אם כן, \u0003היינו רישא\u0004 \u0005[זוהי ההתחלה],\u0006 \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא \u0003שאין אוכלין\u0004 כלל, \u0003לא מן התורה ולא מהלכות מדינה. ומאי ניהו\u0004 \u0005[ומה הם]\u0006 אלה המנויים שם — \u0003עושה במחובר לקרקע בשעה שאין גמר מלאכה, וכל שכן שומרי גנות ופרדסות\u0004 שאין מלאכתם מלאכה גמורה.","\u0003ארבעה\u0004 סוגי \u0003שומרים הן,\u0004 שיש ביניהם חילוקי דינים, והם: \u0003שומר חנם,\u0004 שאינו מקבל כל תמורה עבור שמירת החפץ, \u0003והשואל\u0004 חפץ מחבירו כדי להשתמש בו, \u0003נושא שכר,\u0004 שהוא שומר המקבל שכר עבור שמירתו, \u0003והשוכר,\u0004 זה המשתמש בכלי או בבהמה ומשלם לבעלים עבור זה. ודיניהם: \u0003שומר חנם נשבע על הכל,\u0004 שאם אבד או נגנב או נשבר החפץ או מת בעל חיים בכל אופן שיהיה, נשבע שהדבר היה כפי שהוא מספר, ופטור מלשלם. \u0003והשואל משלם את הכל\u0004 בין בגניבה ובאבידה ובין באונס.","\u0003נושא שכר והשוכר\u0004 דינם שווה: \u0003נשבעים על השבורה ועל השבויה ועל המתה\u0004 שאכן אירע בהן אונס זה, ופטורים, \u0003ומשלמים את האבידה ואת הגניבה.\u0004","שואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 ששנה משנה זו \u0003בארבעה שומרים? אמר רב נחמן אמר רבה בר אבוה:\u0004 שיטת \u0003ר' מאיר היא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מי איכא דלית ליה\u0004 \u0005[האם יש\u0006 חכם \u0005שאין לו]\u0006 \u0003ארבעה שומרין?\u0004 והלא מקובל בידי כל החכמים לומר שארבעה שומרים אלה כתובים בתורה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי קאמינא\u0004 \u0005[כך אומר אני]\u0006 \u0003לך,\u0004 זו היתה כוונתי: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 ששנה ש\u0003שוכר\u0004 דינו \u0003כנושא שכר\u0004 — שיטת \u0003רבי מאיר היא.\u0004","ומקשים: \u0003והא\u0004 \u0005[והארי]\u0006 \u0003ר' מאיר איפכא שמעינן ליה\u0004 \u0005[ההיפך שמענו אותו\u0006 אומר\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שוכר\u0004 שלא נתפרש דינו בתורה \u0003כיצד משלם? ר' מאיר אומר:\u0004 משלם \u0003כשומר חנם, ר' יהודה אומר: כשומר שכר!\u0004 ומסבירים: \u0003רבה בר אבוה איפכא קתני\u0004 \u0005[ההיפך למד]\u0006 שגירסתו באותה ברייתא היתה להיפך מגירסתנו.","על עצם מנין השומרים מקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 ששוכר דינו כשומר שכר, מדוע מונה \u0003ארבעה?\u0004 הרי \u0003שלשה נינהו\u0004 \u0005[הם]!\u0006 \u0003אמר רב נחמן בר יצחק,\u0004 כך יש להבין: \u0003ארבעה\u0004 מיני \u0003שומרין\u0004 הם, \u0003ודיניהם שלשה.\u0004","מסופר: \u0003ההוא רעיא דהוה קא רעי חיותא אגודא\u0004 \u0005[רועה אחד שהיה רועה בהמות על חוף]\u0006 \u0003נהר פפא.\u0004 \u0003שריג חדא מינייהו ונפלת למיא\u0004 \u0005[החליקה אחת מהן ונפלה למים]\u0006 וטבעה. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבה ופטריה\u0004 \u0005[ופטרו\u0006 מתשלומין\u0005].\u0006 \u0003אמר: מאי הוה ליה למיעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 שטביעה כזו יש לראות כאונס, והרועה אף שהוא שומר שכר — פטור הוא מן האונסים."],["\u0003הא נטר כדנטרי אינשי\u0004 \u0005[הרי שמר כמו ששומרים בני אדם]\u0006 ואינו חייב ביותר מזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי שיטתך זו, אם \u0003על למתא בעידנא דעיילי אינשי\u0004 \u0005[נכנס לעיר בזמן שנכנסים בני אדם]\u0006 כדרך שעושים הרועים, שכאשר הבהמות רועות במקום שקט ובטוח הם נכנסים לענייניהם לעיר, ואם באותה שעה אירעה גניבה — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פטור?!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 והקשה עוד: אם \u0003גנא פורתא בעידנא דגנו אינשי\u0004 \u0005[ישן קצת בזמן שאנשים\u0006 כרגיל \u0005ישנים]\u0006 — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פטור?!\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו בברייתא: \u0003אלו הם אונסין ששומר שכר פטור עליהן\u0004 — \u0003כגון: \"\u0004... הבקר היו חורשות והאתונות רועות על ידיהם. \u0003ותפל שבא ותקחם ואת הנערים הכו לפי חרב\"\u0004 (איוב א, יד-טו) משמע כי רק שוד על ידי צבא נחשב לאונס, ולא פחות מזה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם בחזני מתא\u0004 \u0005[שם\u0006 מדובר \u0005בשומרי העיר],\u0006 שכיון שהם שומרים מקצועיים ונשכרו לצורך שמירה על רכוש העיר אם אין אונס של מלחמה ואימת מוות — אינם נפטרים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו בברייתא אחרת: \u0003עד מתי\u0004 (עד כמה) \u0003שומר שכר חייב לשמור\u0004 — \u0003עד כדי\u0004 מה שאמר יעקב ללבן \u0003\"הייתי ביום אכלני חרב וקרח בלילה\"\u0004 (בראשית לא, מ). \u0003אמר\u0004 \u0005[לו]\u0006 רבה: \u0003התם נמי בחזני מתא\u0004 \u0005[שם גם כן\u0006 מדובר \u0005בשומרי העיר]\u0006 כמה חייבים הם לשמור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003יעקב אבינו חזן מתא הוה\u0004 \u0005[שומר העיר היה]?\u0006 והלא ממנו אנו מביאים ראיה זו! אמר לו רבה: ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 יעקב \u0003ללבן: נטרי\u0004 \u0005[שמרתי]\u0006 \u0003לך נטירותא יתירתא כחזני מתא\u0004 \u0005[שמירה יתירה כ\u0006דרך ששומרים \u0005שומרי העיר].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו בברייתא אחרת: \u0003רועה שהיה רועה\u0004 בהמות של אחרים \u0003והניח עדרו ובא לעיר,\u0004 \u0003ו\u0004בינתים \u0003בא זאב וטרף,\u0004 או \u0003בא ארי ודרס\u0004 — \u0003אין אומרים: אילו היה שם היה מציל.\u0004 וכיון שלא היה — צריך לשלם. \u0003אלא אומדין אותו\u0004 כך: \u0003אם יכול\u0004 היה \u0003להציל,\u0004 שהיה בכוחו להבריח חיה כזו — הרי זה \u0003חייב,\u0004 שברור שבשל עזיבתו את המקום נגרם הנזק, ו\u0003אם לאו\u0004 \u0005[לא]\u0006 — \u0003פטור.\u0004","וממשיך אביי: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר בברייתא זו באופן \u0003דעל בעידנא דעיילי אינשי\u0004 \u0005[שנכנס\u0006 לעיר \u0005בזמן שרגילים אנשים להיכנס],\u0006 וקשה איפוא לרבה! ודחה רבה: \u0003לא,\u0004 מדובר באופן \u0003דעל בעידנא דלא עיילי אינשי\u0004 \u0005[שנכנס בזמן שאין אנשים רגילים להיכנס].\u0006 והקשה אביי: \u0003אי הכי, אמאי\u0004 \u0005[אם כך, מדוע]\u0006 \u0003פטור\u0004 גם כשהיה זה באופן שאינו יכול להציל? הלא זהו מקרה ש\u0003תחילתו בפשיעה וסופו באונס,\u0004 וכיון שהיתה פשיעה מתחילה \u0003חייב\u0004 אף על האונס!","והסביר רבה: מדובר באופן ש\u0003שמע קל\u0004 \u0005[קול]\u0006 \u0003אריה\u0004 שואג בסביבה \u0003ועל\u0004 \u0005[\u0006\u0005ונכנס\u0006 לעיר כדי להנצל\u0005],\u0006 ואם כן לא היתה תחילתו פשיעה אלא באונס. והקשה: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה ענין \u0003אומדין אותו? מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]\u0006 כנגד אריה? השיב לו: \u0003היה לו לקדם\u0004 את האריה \u0003ברועים ובמקלות\u0004 להבריחו.","ושואלים: \u0003אי הכי, מאי איריא\u0004 \u0005[אם כך, מה שייך,\u0006 מדוע דווקא\u0005]\u0006 שנה דין זה ב\u0003שומר שכר? אפילו שומר חנם נמי\u0004 \u0005[גם כן]\u0006 זה דינו, \u0003דהא מר\u0004 \u0005[שהרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 הלכה זו: \u0003שומר חנם שהיה לו\u0004 מקום ואפשרות \u0003לקדם ברועים ובמקלות ולא קידם\u0004 — \u0003חייב,\u0004 שאם לא עשה דבר הרי הוא כפשיעה בשמירה. ענה לו רבה: \u0003שומר חנם\u0004 מתחייב רק כאשר היה יכול לאסוף רועים להגן על הצאן \u0003בחנם, שומר שכר\u0004 חייב אפילו לא היה יכול לאסוף רועים להגן על הצאן אלא \u0003בשכר.\u0004","ושואלים: \u0003ועד כמה\u0004 צריך להוציא לשכירת עזרה והגנה כזו? ומשיבים: \u0003עד כדי דמיהן\u0004 של הבהמות, שקיבל עליו לשמור עליהן. ושואלים: אם כך, נמצא ששומר שכר משלם משלו עבור הגנת הבהמות מחיות טרף, \u0003והיכן מצינו בשומר שכר שחייב באונסין,\u0004 שהרי דבר זה אונס הוא לכל הדעות, ובכל זאת מתברר שהשומר משלם עבורו בעקיפין! ומשיבים: \u0003דהדר שקיל\u0004 \u0005[שחוזר ולוקח]\u0006 את \u0003דמיהן\u0004 של השומרים הללו \u0003מבעל הבית.\u0004","\u0003אמר\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי מאי אהני ליה מינה\u0004 \u0005[אם כך, מה הנאה לו מזה]\u0006 לבעל הבהמות? שהרי בעל הבית משלם, ומה שלא הפסיד בשביל האריה — הפסיד על ידי השומרים! ומשיבים: \u0003נפקא מינה לכושרא דחיותא\u0004 \u0005[יוצא מזה\u0006 הענין \u0005לכושרן,\u0006 הרגלן, \u0005של הבהמות],\u0006 שאף שמבחינת הכסף אין הבדל, בכל זאת אם היה צריך לקנות בהמות אחרות הריהו מפסיד את ההרגל והכושר של הבהמות שהיו שלו, ועדיף לו להחזיק בבהמותיו שלו. \u0003אי נמי לטרחא יתירתא\u0004 \u0005[או גם כן ל\u0006ענין \u0005הטרחה היתירה]\u0006 שיש בקניית בהמות חדשות.","שיטת רבה היתה איפוא כי אף שומר שכר חייב רק בשמירה ובטיפול רגיל, ואולם \u0003רב חסדא ורבה בר רב הונא לא סבירא להו הא\u0004 \u0005[\u0006היו \u0005סבורים\u0006 כשיטתו \u0005זו]\u0006 של \u0003רבה,\u0004 \u0003דאמרי\u0004 \u0005[שהם אומרים]\u0006 שהמפקיד אומר לשומר: \u0003להכי יהבי\u0004 \u0005[לזה נתתי]\u0006 \u0003לך אגרא\u0004 \u0005[שכר]\u0006 כדי \u0003לנטורי\u0004 \u0005[שתשמור]\u0006 \u0003לי נטירותא יתירתא\u0004 \u0005[שמירה יתירה]\u0006 ולא שתלך ותאכל ותישן כשאר בני אדם.","מסופר: \u0003בר אדא סבולאה\u0004 \u0005[הסבל]\u0006 \u0003הוי קא מעבר חיותא אגמלא\u0004 \u0005[היה מעביר בהמות על הגשר הצר]\u0006 של \u0003נרש.\u0004 \u0003דחפה\u0004 בהמה \u0003חדא\u0004 \u0005[אחת]\u0006 את \u0003חברתה ושדיתה במיא\u0004 \u0005[וזרקתה במים]\u0006 וטבעה. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדבר \u0005לפני]\u0006 \u0003רב פפא, חייביה\u0004 \u0005[וחייבו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר אדא: \u0003מאי הוה\u0004 \u0005[מה היה]\u0006 \u0003לי למעבד\u0004 \u0005[לעשות]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003אבעי\u0004 \u0005[היה]\u0006 \u0003לך לעבורי חדא חדא\u0004 \u0005[להעביר אותן אחת אחת]\u0006 \u0003אמר\u0004 \u0005[לו]\u0006 בר אדא: האם \u0003ידעת ביה בבר אחתיך דמצי למעבר חדא חדא\u0004 \u0005[יודע אתה בבן אחותך שיכול להעביר אחת אחת]?\u0006 כלומר, האם יודע אתה מישהו שיכול לעשות זאת? הלא הדבר הוא כמעט בלתי אפשרי! \u0003אמר\u0004 \u0005[לו]:\u0006 רב פפא: \u0003כבר צווחו קמאי דקמך\u0004 \u0005[צעקו\u0006 וטענו על כך \u0005ראשוני ראשונים]\u0006 \u0003ולא איכא דאשגח בהו\u0004 \u0005[היה\u0006 מי \u0005שישגיח בהם],\u0006 שכיון שאתה מומחה ולכך נשכרת — עליך האחריות.","ומסופר עוד: \u0003איבו אפקיד כיתנא בי\u0004 \u0005[איבו הפקיד פשתן בבית,\u0006 אצל\u0005]\u0006 איש בשם \u0003רוניא. אזל\u0004 \u0005[הלך]\u0006 גנב ששמו \u0003שבו שמטיה מיניה\u0004 \u0005[\u0006ו\u0005חטף אותו ממנו]\u0006 בכוח, בגזילה. \u0003לסוף\u0004 \u0005[לבסוף]\u0006 \u0003הוכר הגנב\u0004 ונתפס. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הענין \u0005לפני]\u0006 \u0003רב נחמן, חייביה\u0004 \u0005[\u0006ו\u0005חייב אותו],\u0006 את רוניא. ושואלים: \u0003לימא פליגא\u0004 \u0005[האם לומר שחלוקה]\u0006 פסיקה זו על דברי \u0003רב הונא בר אבין?\u0004","ש\u0003שלח רב הונא בר אבין\u0004 הלכה זו: בהמה ש\u0003נגנבה באונס ואחר כך הוכר הגנב\u0004 ונתפס, \u0003אם שומר חנם הוא\u0004 השומר הראשון, \u0003רצה\u0004 — \u0003נשבע\u0004 שלא שלח ידו בה והבעלים יגבו מן הגנב, \u0003רצה\u0004 — \u0003עושה עמו,\u0004 עם הגנב, \u0003דין,\u0004 ומקבל ממנו. \u0003אם שומר שכר הוא\u0004 — \u0003עושה עמו דין ואינו נשבע.\u0004 ורוניא, כיון ששומר חנם היה, מדוע צריך הוא לעשות דין?","\u0003אמר רבא:\u0004 אינו דומה, שכן \u0003התם גברי דפרמוסקא הוו קיימי\u0004 \u0005[שם\u0006 במקרה של רוניא \u0005אנשי השלטון היו עומדים שם],\u0006 \u0003דאי רמא קלא הוו אתו ומצלין ליה\u0004 \u0005[שאם היה מרים את קולו היו באים ומצילים אותו],\u0006 ואם כן רשלנותו ופשיעתו היא שגרמה לגניבה, ולכן חובה עליו לטפל בהוצאת הכסף מן הגנב.","\u0003זאב אחד\u0004 שמתנפל על עדר — \u0003אינו אונס,\u0004 לפי שיכול הרועה לגרשו. \u0003שני זאבים\u0004 — \u0003אונס. ר' יהודה אומר: בשעת משלחת זאבים,\u0004 כשהזאבים יוצאים ממחבואיהם ומתנכלים בכל מקום, \u0003אף זאב אחד\u0004 — \u0003אונס.\u0004","\u0003שני כלבים\u0004 — \u0003אינו אונס.\u0004 החכם \u0003ידוע הבבלי אומר משום\u0004 (בשם) \u0003ר' מאיר:\u0004 אם באו שני הכלבים \u0003מרוח אחת\u0004 (מצד אחד) — \u0003אינו אונס, משתי רוחות\u0004 — \u0003אונס,\u0004 שהרי אינו יכול להתגונן כראוי. \u0003הלסטים\u0004 (שודדים) — \u0003הרי זה אונס. הארי הדוב והנמר והברדלס והנחש\u0004 — \u0003הרי אלו אונס.\u0004","\u0003אימתי\u0004 נחשבים אלה כאונס לפטור את שומר השכר — \u0003בזמן שבאו\u0004 חיות רעות או גזלנים \u0003מאליהן\u0004 למקום המרעה הרגיל. \u0003אבל\u0004 אם \u0003הוליכן\u0004 הרועה \u0003למקום גדודי חיה ולסטים\u0004 — \u0003אינו אונס,\u0004 שהרי מעשיו הם שגרמו.","\u0003מתה\u0004 בהמה \u0003כדרכה\u0004 — \u0003הרי זה אונס, סגפה\u0004 (עינה אותה) במלאכה ובחוסר טיפול בה \u0003ומתה\u0004 — \u0003אינו אונס. עלתה\u0004 הבהמה \u0003לראשי צוקין ונפלה\u0004 משם ומתה — \u0003הרי זה אונס. העלה\u0004 אותה הוא עצמו \u0003לראשי צוקין ונפלה ומתה\u0004 — \u0003אינו אונס.\u0004","על דברי המשנה שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זאב אחד\u0004 — \u0003אונס! אמר רב נחמן בר יצחק:\u0004 הברייתא \u0003ההיא\u0004 מדברת \u0003בשעת משלחת זאבים, ו\u0004שיטת \u0003ר' יהודה היא.\u0004","שנינו במשנה: \u0003הלסטים\u0004 — \u0003הרי זה אונס.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003לוקי גברא להדי גברא\u0004 \u0005[שיעמוד אדם מול אדם]\u0006 ויתגונן הרועה, שהרי לשמירה נשכר, ואם כן ילחם בגנב! \u0003אמר רב:\u0004 מדובר כאן \u0003בלסטים מזויין\u0004 שאין הרועה יכול להתגונן מפניו.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003לסטים מזויין ורועה מזויין מהו\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן אוקי גברא להדי גברא\u0004 \u0005[האם אומרים אנו\u0006 ש\u0005יעמוד אדם מול אדם]\u0006 וילחם, \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003האי מסר נפשיה\u0004 \u0005[זה\u0006 הגנב \u0005מוסר\u0006 את \u0005נפשו],\u0006 \u0003והאי\u0004 \u0005[וזה\u0006 הרועה\u0005]\u0006 \u0003לא מסר נפשיה\u0004 \u0005[מוסר\u0006 את \u0005נפשו]?\u0006 ומשיבים: \u0003מסתברא דהאי מסר נפשיה\u0004 \u0005[מסתבר\u0006 לומר \u0005שזה מוסר\u0006 את \u0005נפשו],\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 \u0003לא מסר נפשיה\u0004 \u0005[מוסר\u0006 את \u0005נפשו],\u0006 ואין על הרועה אחריות אם לא נכנס למלחמה כזו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא:\u0004 מה יהיה הדין במקרה ש\u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 ה\u0003רועה\u0004 לגנב מפורסם, \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003גנבא סריא\u0004 \u0005[גנב מסריח]!\u0006 \u0003בדוכתא פלניא יתיבינן\u0004 \u0005[במקום פלוני אנו\u0006 הרועים \u0005יושבים]\u0006"],["\u0003כך וכך גברי איכא בהדן\u0004 \u0005[אנשים יש איתנו],\u0006 \u0003כך וכך כלבי איכא בהדן\u0004 \u0005[כלבים יש איתנו],\u0006 \u0003כך וכך זוקתא פסיקא לן\u0004 \u0005[קלעים יש לנו],\u0006 כלומר, יש לנו הגנה מושלמת, ואתה לא תעיז לקחת מאיתנו. \u0003ואזל ושקל מיניה, מאי\u0004 \u0005[והלך\u0006 הגנב \u0005ולקח ממנו, מה]\u0006 הדין? \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003הרי הוליכן למקום גדודי חיה ולסטים,\u0004 שכן על ידי שהתגרה בגנב גרם לו שיעיז ויתאמץ ויגנוב.","דיני שומרים ששנינו הם בדרך כלל, ואולם אפשר לעשות בדברים שבממון גם הסכמים מיוחדים. למשל: \u0003מתנה שומר חנם\u0004 עם המפקיד \u0003להיות פטור משבועה\u0004 אם אבד החפץ, וכן \u0003השואל\u0004 מתנה \u0003להיות פטור מלשלם\u0004 בדבר שהוא פטור ממנו, וכגון במתה מחמת מלאכה, או \u0003נושא שכר\u0004 (שומר שכר) \u0003והשוכר\u0004 מתנים \u0003להיות פטורין משבועה ומלשלם\u0004 באונס, לפי שאלה הם הסכמים שבממון, ויכול אדם לוותר על ממונו. אבל בשאר דברים \u0003כל המתנה על מה שכתוב בתורה\u0004 לעשות שלא כדיני התורה — \u0003תנאו בטל,\u0004","\u0003וכל תנאי שיש מעשה בתחילתו,\u0004 כלומר, שניסוח ההסכם הוא כזה, שבתחילה יש הבטחה (מעשה) ואחר כך נכתב שדבר זה הוא רק בתנאי מסויים, הרי \u0003תנאו בטל\u0004 וההבטחה קיימת. \u0003וכל\u0004 תנאי \u0003שאפשר לו לקיימו בסופו,\u0004 שהוא ניתן לביצוע, אף על פי ש\u0003התנה עמו מתחילתו\u0004 שבפועל נאמר התנאי קודם מעשה, וצריך לקיים את התנאי לאחר מכן, כיון שנכתב כראוי — \u0003תנאו קיים.\u0004 אבל תנאי שאינו ניתן לביצוע בסופו, כיון שנעשה המעשה — התנאי בטל.","על האמור במשנה שיכולים השומרים להתנות ולשנות מחובתם שלפי דין תורה, שואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 יהא הדין כך? הלא \u0003מתנה על מה שכתוב בתורה הוא\u0004 ושם נקבע מי שנשבע ומי משלם, \u0003וכל המתנה על מה שכתוב בתורה תנאו בטל!\u0004","ומסבירים: \u0003הא מני\u0004 \u0005[\u0006הלכה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר:\u0004 אם התנה \u0003בדבר שבממון\u0004 — \u0003תנאו קיים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי על מנת שאין ליך\u0004 (לך) \u0003עלי\u0004 לתת לך \u0003שאר\u0004 (מזונות) \u0003כסות\u0004 (לבוש) \u0003ועונה\u0004 (תשמיש) \u0003\"\u0004— \u0003הרי זו מקודשת\u0004 אבל \u0003תנאו\u0004 שהתנה \u0003בטל,\u0004 אלו \u0003דברי ר' מאיר. ור' יהודה אומר:\u0004 אם התנאי \u0003בדבר שבממון\u0004 (כגון שאר וכסות) — \u0003תנאו קיים.\u0004","ומקשים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד,\u0006 לפרש, \u0005אותה\u0006 את משנתנו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה? אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של המשנה\u0005]\u0006 ששנינו: \u0003כל המתנה על מה שכתוב בתורה\u0004 — \u0003תנאו בטל,\u0004 ואם כן \u0003אתאן\u0004 \u0005[הגענו]\u0006 לפיכך \u0003ל\u0004שיטת \u0003ר' מאיר!\u0004 ומתרצים: \u0003הא לא קשיא\u0004 \u0005[\u0006דבר \u0005זה אינו קשה];\u0006 \u0003לעולם\u0004 תפרש שמשנתנו כ\u0003ר' יהודה היא, וסיפא\u0004 \u0005[וסופה]\u0006 מדובר \u0003בדבר שאינו של ממון.\u0004 ומקשים עוד: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003כל תנאי שיש בו מעשה בתחילתו\u0004 — \u0003תנאו בטל, מאן שמעת ליה דאית ליה הא סברא\u0004 \u0005[מי שמעת אותו שיש לו,\u0006 שהוא סובר, \u0005סברה זו]\u0006 — \u0003ר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבא חלפתא איש כפר חנניא אמר משום\u0004 (משמו של) \u0003ר' מאיר:\u0004 אם היה \u0003תנאי קודם למעשה\u0004 — \u0003הרי זה תנאי\u0004 ודבריו קיימים, ואם היה ה\u0003מעשה קודם לתנאי\u0004 — \u0003אינו תנאי.\u0004","","\u0003אלא,\u0004 עלינו לחזור בנו מן ההסבר הקודם ולומר כי המשנה \u0003כולה\u0004 כשיטת \u0003ר' מאיר היא,\u0004 \u0003ו\u0004משום מה אין השומר משלם או נשבע למרות שכתוב בתורה כי \u0003שאני הכא דמעיקרא\u0004 \u0005[שונה כאן שמתחילה]\u0006 \u0003לא שעבד נפשיה\u0004 \u0005[עצמו]\u0006 לקבל עליו דין שומר הכתוב בתורה, שמראש אמר שאינו מתחייב להיות כשומר חנם או שומר שכר הכתוב בתורה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 כשם שמתנה שומר לפטור עצמו, כך גם להיפך — \u0003ומתנה שומר שכר להיות כשואל,\u0004 שמקבל על עצמו אחריות בכל מה ששואל מתחייב בו. ושואלים: \u0003במאי\u0004 \u0005[במה]\u0006 כיצד נעשית התחייבות זו? האם רק \u0003בדברים,\u0004 באמירה בלבד?! \u0003אמר שמואל:\u0004 לא, אלא \u0003בשקנו מידו\u0004 כשעושים מעשה של קנין, שרק על ידי זה חלה ההתחייבות.","\u0003ור' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי מדובר \u0003ב\u0004אופן \u0003שלא קנו מידו\u0004 בכל זאת נקנית ההתחייבות לגמרי כי \u0003בההיא הנאה דקא נפיק ליה קלא דאיניש מהימנא\u0004 \u0005[באותה הנאה\u0006 שנהנה \u0005שיוצא עליו קול שאדם נאמן]\u0006 \u0003הוא\u0004 — \u0003גמיר ומשעבד נפשיה\u0004 \u0005[גומר ומשעבד עצמו]\u0006 בהבטחה בלבד, ואיננו צריך שיעבוד בדרך קנין.","שנינו במשנה: \u0003וכל שאפשר לו לקיימו בסופו\u0004 גם אם התנה עמו מתחילתו — תנאו קיים. \u0003אמר רב טבלא אמר רב: זו דברי ר' יהודה בן תימא, אבל חכמים אומרים: אף על פי שאי אפשר לו לקיימו בסופו והתנה עליו מתחילתו\u0004 — \u0003תנאו קיים.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 אמר לאשה: \u0003\"הרי זה גיטך על מנת שתעלי לרקיע\"\u0004 או \u0003\"על מנת שתרדי לתהום\",\u0004 או \u0003\"על מנת שתבלעי קנה של מאה אמה\",\u0004 או \u0003\"על מנת שתעברי את הים הגדול ברגליך\";\u0004 אם \u0003נתקיים התנאי\u0004 ועשתה מה שאמר לה לעשות — \u0003הרי זה גט, לא נתקיים התנאי\u0004 — \u0003אינו גט.\u0004 וכמובן, תנאי כזה אי אפשר לקיימו, אבל לדעת תנא קמא יש לתנאי זה תוקף. \u0003ר' יהודה בן תימא אומר: כזה\u0004 — \u0003גט,\u0004 כלומר, התנאי איננו תופס, והגט חל למרות שלא נתקיים התנאי. כי \u0003כלל אמר ר' יהודה בן תימא: כל שאי אפשר לו לקיימו בסופו,\u0004 כלומר, תנאי שאיננו ניתן למילוי כלל \u0003והתנה עליו\u0004 אפילו \u0003מתחילתו\u0004 — \u0003אינו אלא כמפליגה\u0004 בדברים \u0003וכשר,\u0004 שתנאו הוא רק כדברי הבאי, ואינם מחייבים. \u0003אמר ר' נחמן אמר רב: הלכה כ\u0004שיטת \u0003ר' יהודה בן תימא. אמר רב נחמן בר יצחק: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003כל שאפשר לו לקיימו בסופו והתנה עליו מתחילתו\u0004 — \u0003תנאו קיים,\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אי אפשר לו לקיימו\u0004 — משמע ש\u0003תנאו בטל.\u0004 ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, וסתם משנתנו כר' יהודה בן תימא.","","","","\u0003השואל את הפרה ושאל בעליה עמה,\u0004 שגם ביקש מבעלי הפרה שיבואו ויסייעו לו בעבודתו, \u0003או שכר בעליה עמה,\u0004 ששכר את בעל הפרה לעבודתו, או \u0003שאל\u0004 את \u0003הבעלים או שכרן ואחר כך שאל את הפרה\u0004, בכל מקרה כזה אם \u0003מתה\u0004 הפרה — \u0003פטור.\u0004 למרות שבדרך כלל שואל חייב לשלם גם עבור אונס מיתה, \u0003שנאמר: \"אם בעליו עמו לא ישלם\"\u0004 (שמות כב, יד)."],["\u0003אבל\u0004 אם \u0003שאל את הפרה ואחר כך שאל את הבעלים, או שכרן, ומתה,\u0004 גם אם הם עדיין עובדים עבורו — \u0003חייב,\u0004 והוא \u0003שנאמר: \"בעליו אין עמו שלם ישלם\"\u0004 (שמות כב, יג).","תחילה מבררים בעיה מעשית בנושא זה, \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה בסוף]:\u0006 שאל את הבעלים \u0003ואחר כך שאל את הפרה, מכלל\u0004 הדברים אתה למד \u0003דרישא דקתני\u0004 \u0005[שמתחילה ששנה]\u0006 שאל בעליה \u0003עמה\u0004 — הכוונה \u0003עמה ממש,\u0004 באותו רגע. ואולם \u0003עמה ממש, מי משכחת לה\u0004 \u0005[איך יכול אתה למצוא אותה],\u0006 כלומר, כיצד יכול להיות דבר כזה? הלא את ה\u0003פרה\u0004 הוא קונה לענין שאילה רק ב\u0003משיכה, ובעלים\u0004 נשאלים לו \u0003באמירה\u0004 בלבד, וכשאומר לבעלים ששואל אותו ואת בהמתו, הרי שאילתו קודמת!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר \u0003כגון דקיימא\u0004 \u0005[שעומדת]\u0006 ה\u0003פרה בחצרו\u0004 של ה\u0003שואל, דלא מחסרא\u0004 \u0005[שאינה מחוסרת]\u0006 \u0003משיכה,\u0004 ומיד כשמסכים בעל הפרה הרי היא כבר מושאלת לשואל אגב חצירו. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003את גופך\u0004 \u0005[אתה עצמך]\u0006 \u0003לא תשאל\u0004 לי לעבודה \u0003עד שעת משיכת פרת\u0004 \u0003ך.\u0004","דיני ארבעה שומרים כבר נדונו בפרק הקודם. (דף צג, א–ב) אבל לא נתבררו לעומקם, ומעתה באים לדון בהם לגופם. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003ארבעה שומרים הם: שומר חנם, והשואל, נושא שכר, והשוכר.\u0004","\u0003שומר חנם\u0004 — \u0003נשבע\u0004 ונפטר מתשלום \u0003על הכל, והשואל\u0004 — \u0003משלם את הכל, נושא שכר והשוכר\u0004 — \u0003נשבעין\u0004 ונפטרים מתשלום \u0003על השבורה ועל השבויה ועל המתה, ומשלמים את האבידה ואת הגניבה.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מה מקורם במקרא? ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 מדרש הלכה זה: \u0003פרשה ראשונה\u0004 בדיני שומרים שבתורה (שמות כב, ו–ח) \u0003נאמרה בשומר חנם, שניה\u0004 (שם ט–יב) — \u0003בשומר שכר, שלישית\u0004 (שם יג–יד) — \u0003בשואל.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שלישית\u0004 ברור לך שהיא עוסקת \u0003בשואל\u0004 — שכן דבר זה \u0003מפורש\u0004 במקרא, שנאמר: \u0003\"וכי ישאל איש מעם רעהו ונשבר או מת בעליו אין עמו שלם ישלם\"\u0004 (שם יג). \u0003אלא\u0004 שהפרשה ה\u0003ראשונה\u0004 עוסקת \u0003בשומר חנם\u0004 וה\u0003שניה בשומר שכר\u0004 אולי תאמר ש\u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר להיפך, שהרי לא נאמר הדבר במפורש במקרא!","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר שה\u0003שניה\u0004 עוסקת \u0003בשומר שכר, שכן\u0004 הוא חמור ו\u0003חייב בגניבה ואבידה.\u0004 ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 מסתבר לומר שה\u0003ראשונה\u0004 עוסקת \u0003בשומר שכר, שכן\u0004 הוא חמור יותר שכן הוא \u0003משלם תשלומי כפל בטוען טענת גנב!\u0004","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 הפרשה הראשונה מקילה יותר על השומר, שכן לשלם \u0003קרנא\u0004 \u0005[קרן]\u0006 \u0003בלא שבועה עדיפא מכפילא\u0004 \u0005[עדיף,\u0006 חמור \u0005מ\u0006תשלום \u0005כפל]\u0006 \u0003בשבועה.\u0004","ומוסיפים, \u0003תדע\u0004 שכן הוא, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שואל כל הנאה\u0004 מן הבהמה \u0003שלו, ואינו משלם אלא קרן.\u0004","ותוהים: \u0003והשואל כל הנאה שלו? והא בעיא מזוני\u0004 \u0005[והרי צריכה\u0006 הבהמה \u0005מזונות]\u0006 ונמצא שאף השואל משלם משהו, ולא נהנה בלבד! ומשיבים: מדובר באופן \u0003דקיימא\u0004 \u0005[ש\u0006היא \u0005עומדת]\u0006 \u0003באגם\u0004 ויש לה מה לאכול מעצמה. ושואלים: \u0003והא בעיא נטירה\u0004 \u0005[והרי\u0006 היא \u0005צריכה שמירה]?\u0006 ומשיבים: מדובר \u0003ב\u0004שואל שהוא \u0003נטר מתא\u0004 \u0005[שומר העיר]\u0006 שממילא היא נשמרת בידו. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 בדיוק בלשון \u0003\"כל הנאה שלו\", אלא אימא\u0004 \u0005[אמור]\u0006 בלשון \u0003\"רוב הנאה שלו\". ואיבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 שאמרו זאת \u0003בשאילת כלים\u0004 שאינו צריך לפרנסם ולטפל בהם.","שנינו ש\u0003נושא שכר והשוכר נשבעין על השבורה ועל השבויה ועל המתה ומשלמין את האבידה ואת הגניבה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 תשלום על \u0003גניבה\u0004 מפורש במקרא, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004ו\u0003אם גנב יגנב מעמו ישלם לבעליו\"\u0004 (שם יא), \u0003אלא\u0004 תשלום על \u0003אבידה מנא לן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"\u0004ו\u0003אם גנב יגנב\"\u0004 — \u0003אין לי\u0004 שהשומר משלם \u0003אלא\u0004 על \u0003גניבה, אבידה מנין\u0004 שהוא משלם? \u0003תלמוד לומר: \"\u0004ו\u0003אם גנב יגנב\",\u0004 שמכפל הלשון למדנו שמשלם \u0003מכל מקום.\u0004","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 בכלל: \u0003לא אמרינן\u0004 \u0005[איו אנו אומרים]\u0006 \u0003דברה תורה כלשון בני אדם,\u0004 ולשונות כפולים אלה באים לרבות דבר מה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003דברה תורה כלשון בני אדם\u0004 וכפל לשון זה אינו מלמד, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 כך: \u0003קל וחומר; ומה גניבה ש\u0004היא \u0003קרובה\u0004 במהותה \u0003לאונס,\u0004 שהרי יד הגנב בדבר — אף על פי כן \u0003משלם\u0004 השומר, \u0003אבידה שקרובה לפשיעה\u0004 (רשלנות) — \u0003לא כל שכן\u0004 שחייב!","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלומד הלכה זו מרבוי המקרא, מה הוא אומר על סברה זו? ומשיבים: סבור הוא כי \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 שנלמד\u0005]\u0006 \u0003בקל וחומר טרח וכתב לה קרא\u0004 \u0005[אותו הכתוב]\u0006 לפעמים, אף שאפשר היה להבינו מדעתנו.","שנינו במשנה שם ש\u0003השואל משלם את הכל.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 זה שהוא משלם על \u0003שבורה ומתה,\u0004 משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וכי ישאל איש מעם רעהו ונשבר או מת\"\u0004 (שם יג). \u0003אלא\u0004 תשלום על ה\u0003שבויה בשואל מנא לן\u0004 \u0005[מנין לנו]?\u0006","\u0003וכי תימא נילף\u0004 \u0005[ואם תאמר שנלמד]\u0006 \u0003משבורה ומתה,\u0004 הלא אפשר לחלק: \u0003מה לשבורה ומתה\u0004 — \u0003שכן אונסא דסליק אדעתא\u0004 \u0005[אונס שעולה על הדעת]\u0006 \u0003הוא,\u0004 שהדבר עשוי לקרות ואפשר לומר שעל דעת כן קיבל עליו מתחילה. \u0003תאמר בשבויה שכן אונסא דלא סליק אדעתא\u0004 \u0005[אונס שאין עולה על הדעת]\u0006 \u0003הוא\u0004 שתהא מלחמה ותלקח הבהמה בשבי!","\u0003אלא\u0004 כך יש לומר: \u0003נאמרה שבורה ומתה בשואל, ונאמרה שבורה ומתה בשומר שכר\u0004 (\"\"ומת או נשבר\". שם ט), \u0003מה להלן\u0004 בשומר שכר \u0003שבויה עמו\u0004 (\"ומת או נשבר או נשבה\". שם), \u0003אף כאן שבויה עמו.\u0004","ודוחים: \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה ולומר: \u0003מה לשומר שכר שכן\u0004 כולם באים \u0003לפטור\u0004 שעל כל אלה איננו משלם, \u0003תאמר בשואל שכן\u0004 אתה רוצה ללמוד מכאן \u0003לחיוב,\u0004 ושמא אין הדברים דומים!","\u0003אלא\u0004 יש לפרש \u0003כ\u0004שיטת \u0003ר' נתן, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על מה שנאמר \"ונשבר או מת\" (שם יג), \u0003ר' נתן אומר:\u0004 \u0003\"או\"\u0004 שאמרו הרי זה בא \u0003לרבות שבויה.\u0004","ומקשים: \u0003האי \"או\" מיבעיא ליה\u0004 \u0005[\"או\" זה נחוץ לו]\u0006 כדי \u0003לחלק\u0004 בין הדברים, שלולא כן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על הדעת לומר]:\u0006 \u0003עד דמיתברא ומתה לא מחייב\u0004 \u0005[שתישבר ותמות\u0006 גם יחד \u0005אינו חייב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במה שאמר \"או\" שיש כאן שני דינים נפרדים.","ושואלים, \u0003הניחא\u0004 \u0005[דבר זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' יונתן\u0004 שלדעתו שני דברים המנויים יחד בתורה, גם אם אין דבר המחלק ביניהם, יש להבין את כל אחד מהם לעצמו, \u0003אלא\u0004 לדעת \u0003ר' יאשיה\u0004 הסבור ששני דברים הכתובים יחד, כאילו יש לראותם כאחד, אם אין הוכחה לחלוקה ביניהם \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","והדוגמה לשיטות שני תנאים אלה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"איש אשר יקלל את אביו ואת אמו\u0004 מות יומת\u0003\"\u0004 (ויקרא כ, ט) — \u0003אין לי אלא\u0004 אם קילל את \u0003אביו ואמו\u0004 יחד, אבל אם קילל את \u0003אביו בלא\u0004 שקילל את \u0003אמו,\u0004 או את \u0003אמו בלא אביו, מנין\u0004 שחייב? \u0003תלמוד לומר\u0004 מסיום אותו הפסוק: \u0003\"אביו ואמו קלל\u0004 דמיו בו \u0003\"\u0004— ללמד: \u0003אביו קלל, אמו קלל,\u0004 אלו \u0003דברי ר' יאשיה,\u0004 ואילו","\u0003ר' יונתן אומר:\u0004 אינו צריך כלל ללימוד זה, כי צירוף כזה של דברים \u0003משמע שניהם כאחד, ומשמע\u0004 כל \u0003אחד בפני עצמו,\u0004"],["\u0003עד שיפרוט לך הכתוב \"יחדו\".\u0004 ולשיטת ר' יאשיה דרוש איפוא \"או\" בכתוב זה!","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שאמרו כשיטת \u0003ר' יאשיה,\u0004 ואולם \u0003לחלק הכא\u0004 \u0005[כאן]\u0006 \u0003לא צריך. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003סברא הוא\u0004 בדבר, שכן \u0003מה לי\u0004 אם \u0003קטלה\u0004 \u0005[הרגה]\u0006 \u0003כולה, מה לי\u0004 אם \u0003קטלה פלגא\u0004 \u0005[הרגה מקצתה],\u0006 וכיון שחייב על מות הבהמה — ודאי חייב גם אם נשברה, שהיא כהרוגה למחצה.","ושואלים עוד: חיוב תשלום על \u0003גניבה ואבידה בשואל\u0004 \u0003מנא לן\u0004 \u0005[מנין לנו]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003משבורה ומתה\u0004 שאם עליהן חייב, ודאי חייב גם בגניבה ואבידה. אולם אפשר לומר להיפך: \u0003מה לשבורה ומתה\u0004 — \u0003דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר למיטרח ואתויי\u0004 \u0005[לטרוח ולהביא]\u0006 את הבהמה ולהשיבה לבעליה, ולכן השואל משלם מיד את הנזק, \u0003תאמר בגניבה ואבידה\u0004 ש\u0003אפשר למיטרח ואתויי\u0004 \u0005[לטרוח\u0006 בחיפוש אחריה \u0005ולהביא]\u0006 ושמא במקרה זה יצטרך בעל החפץ לטרוח ולנסות למצוא אותו!","\u0003אלא\u0004 הראיה לכך היא \u0003כי הא דתניא\u0004 \u0005[כפי זו ששנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \"וכי ישאל איש מעם רעהו \u0003ונשבר או מת\u0004 בעליו אין עמו שלם ישלם\" (שמות כב, יג) — \u0003אין לי\u0004 שחייב השואל \u0003אלא\u0004 ב\u0003שבורה ומתה,\u0004 ואולם שהוא חייב אף ב\u0003גניבה ואבידה מנין? אמרת קל וחומר: ומה שומר שכר שפטור מ\u0004\u0003שבורה ומתה\u0004 — \u0003חייב\u0004 בכל זאת \u0003בגניבה ואבידה, שואל שחייב בשבורה ומתה\u0004 — \u0003אינו דין שחייב בגניבה ואבידה? וזה הוא קל וחומר שאין עליו תשובה.\u0004","ושואלים \u0003מאי\u0004 \u0005[מה]\u0006 היא לשון זו \u0003\"אין עליו תשובה\"?\u0004 ומסבירים שדבר זה בא כנגד הטענה הבאה: \u0003וכי תימא איכא למיפרך\u0004 \u0005[ואם תאמר שיש מקום לפרוך\u0006 לשבור\u0005]\u0006 את הקל וחומר ולומר: \u0003מה לשומר שכר\u0004 — \u0003שכן משלם תשלומי כפל\u0004 אם \u0003טוען\u0004 במרמה \u0003טענת לסטים מזויין,\u0004 ואילו השואל במקרה כזה משלם רק קרן","\u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003קרנא\u0004 \u0005[הקרן],\u0006 גוף הדבר שמשלם ה\u0003שואל\u0004 בכל עת \u0003עדיפא\u0004 \u0005[\u0006\u0005עדיף].\u0006","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003לסטים מזויין גזלן הוא,\u0004 ושומר שכר לא יתחייב כפל על טענה זו, שאינו חייב כפל אלא אם טוען שנגנב החפץ ונמצא שהוא עצמו גנבו, אבל לא על גזילה.","\u0003אשכחן\u0004 \u0005[מצאנו,\u0006 למדנו\u0005]\u0006 בענין שואל \u0003לחיוב\u0004 גם בגניבה ואבידה, \u0003לפטור מנא לן\u0004 \u0005[מנין לנו]?,\u0006 שאם בעליו עמו פטור גם מגניבה ואבידה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003נילף\u0004 \u0005[נלמד]\u0006 \u0003משבורה ומתה,\u0004 הרי אפשר לפרוך זאת ולטעון: \u0003מה לשבורה ומתה\u0004 — \u0003שכן\u0004 אלה הם בגדר \u0003אונס,\u0004 ושמא באונס בלבד הקלה עליו התורה!","\u0003אלא\u0004 יש לומר כי \u0003גמר\u0004 \u0005[למד]\u0006 זאת \u0003משומר שכר\u0004 שנפטר מגניבה ואבידה כשהבעלים עמו. ושואלים: \u0003ושומר שכר גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שנפטר במקרה זה? ומשיבים: \u0003גמרי חיובא\u0004 \u0005[לומדי אנו\u0006 את ה\u0005חיוב]\u0006 של \u0003שומר שכר מחיובא\u0004 \u0005[מהחיוב]\u0006 של \u0003שואל;\u0004 \u0003מה להלן\u0004 בדברים שחייב בהם השואל אם היו \u0003בבעלים\u0004 — \u0003פטור, אף כאן\u0004 בדברים שחייב בהם שומר שכר \u0003בבעלים פטור.\u0004","ושואלים: \u0003במאי גמר\u0004 \u0005[במה,\u0006 באיזו שיטת לימוד, \u0005למד]?\u0006 \u0003אי\u0004 \u0005[אם\u0006 תאמר\u0005]\u0006 \u0003ב\u0004שיטת \u0003מה מצינו,\u0004 שכשם שקיים דין זה בנושא זה כן הוא גם בנושא אחר, הלא \u0003איכא למיפרך כדפרכינן\u0004 \u0005[יש מקום לשבור\u0006 את ההשוואה \u0005כפי ששברנו\u0006 זאת\u0005]\u0006 לפי הנימוק: \u0003שכן אונס!\u0004","\u0003אלא\u0004 לא באופן זה למדים, כי אם בצורה אחרת: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכי ישאל\"\u0004 (שם) — ואותה \u0003וי\"ו\u0004 שבאה בראש המשפט הריהי באה לומר שהוא \u0003מוסיף על ענין ראשון.\u0004 כלומר, דין השואל איננו הלכה נפרדת לעצמה, אלא רק מוסיף על ענין ראשון דינים שלא נאמרו בו, \u0003וילמד עליון מתחתון,\u0004 שדין שומר שכר (\"עליון\") יש לו המשך בדין שואל (\"תחתון\").","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003שואל משומר שכר לא גמר\u0004 \u0005[אינו לומד,\u0006 אינו ניתן להלמד\u0005]\u0006 \u0003דאיכא למיפרך\u0004 \u0005[שיש מקום לשבור]\u0006 את ההשוואה ולומר: \u0003מה לשומר שכר\u0004 — \u0003שכן פטור בשבורה ומתה, תאמר בשואל שחייב בשבורה ומתה!\u0004","\u0003אלא\u0004 יש לשנות את דרך ההוכחה מתחילה ולבנותה בצורה אחרת, וכך נלמד: \u0003גניבה ואבידה בשואל לחיובא מנלן\u0004 \u0005[לחייב\u0006 אותו \u0005מנין לנו]\u0006 — \u0003דגמר\u0004 \u0005[שלמד]\u0006 \u0003משומר שכר\u0004 בקל וחומר, ובדיני קל וחומר קיים הכלל: \u0003דיו לבא מן הדין להיות כנדון,\u0004 שאף שנראה שהוא חמור יותר — אין מחמירים על הנלמד (\"הבא מן הדין\") יותר מאשר במקור הדין (\"נדון\"), ולכן: \u0003מה גניבה ואבידה\u0004 שב\u0003שומר שכר\u0004 אם היה זה \u0003בבעלים\u0004 עימו — \u0003פטור,\u0004 \u0003אף גניבה ואבידה\u0004 שבשל \u0003שואל\u0004 שלמדנוה בקל וחומר משוכר — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003בבעלים פטור.\u0004","ומקשים: \u0003הניחא למאן דאית ליה\u0004 \u0005[זה נוח למי שיש לו]\u0006 שיטה זו של \u0003'דיו'\u0004 בקל וחומר\u0005,\u0006 \u0003אלא למאן דלית ליה\u0004 \u0005[אלא למי שאין לו]\u0006 שיטה זו של \u0003'דיו' מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 כך יש לומר לשיטתו שהדבר נלמד ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכי ישאל\"\u0004 ואותו \u0003וי\"ו\u0004 שבראש המשפט \u0003מוסיף על ענין ראשון\u0004 — לעשות את שניהם כיחידה אחת, \u0003וילמד עליון מתחתון ותחתון מעליון.\u0004","באותו ענין עצמו \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה זו: \u0003פשיעה בבעלים,\u0004 אם פשע השומר בשמירת החפץ והיה הדבר בנוכחותם של הבעלים (שהם שאולים או שכורים אצלו), מה יהא הדין? \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בשאלה זו, \u0003רב אחא ורבינא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003חייב, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003פטור.\u0004","\u0003מאן\u0004 \u0005[מי\u0006 ש\u0003אמר חייב קסבר\u0004 \u0005[הוא סבור]\u0006 ש\u0003מקרא נדרש לפניו,\u0004 שגם אם קושרים דבר האמור בנושא אחר לנושא הסמוך לו הרי זה רק לפרשה הסמוכה לפניו \u0003ולא לפני פניו,\u0004 לא לפרשה המצויה קודם לראשונה, ולעניננו:","\u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003\"אם בעליו עמו\u0004 לא ישלם\" — על ה\u0003שומר חנם\u0004 שהוא \"לפני פניו\" \u0003לא כתיב\u0004 \u0005[נאמר],\u0006 \u0003ופשיעה נמי\u0004 \u0005[גם כן]\u0006 \"על כל דבר פשע\" — \u0003בשומר שכר ובשואל לא כתיב\u0004 \u0005[נאמר].\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003בשומר שכר ובשואל לחיוב\u0004 שאף בהם חייב השומר על פשיעה מנין יודעים אנו — \u0003אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר \u0003בקל וחומר\u0004","\u0003אבל\u0004 דין זה \u0003בבעלים לפטור אף בשומר שכר ובשואל\u0004 — \u0003לא\u0004 יחול. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003כי כתיב\u0004 \u0005[כאשר נאמר]\u0006 במקרא \u0003\"אם בעליו עמו לא ישלם\"\u0004 — נאמר דין זה רק על \u0003שואל\u0004 ועל \u0003שומר שכר,\u0004 וכיון שכך \u0003אהנך חיובי דכתיב בהו בהדיא הוא דמיכתב\u0004 \u0005[על אותם חיובים שנאמר בהם במפורש הוא שנאמר]\u0006 ולא על דינים אחרים (כגון פשיעה).","\u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר פטור\u0004 \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 כי \u0003מקרא נדרש לפניו ולפני פניו, ו\u0004לכן \u0003כי כתיב\u0004 \u0005[כאשר נאמר\u0006 במקרא\u0005]\u0006 \u0003\"אם בעליו עמו\u0004 לא ישלם\u0003\"\u0004 (שם יד) — על \u0003שומר חנם נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 הדבר. ומנסים להביא ראיות לשתי השיטות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003השואל\u0004 את \u0003הפרה ושאל בעליה עמה,\u0004 וכן \u0003השואל\u0004 את \u0003הפרה ושכר בעליה עמה,\u0004 או \u0003שאל בעליה או שכרן ואחר כך שאל\u0004 את \u0003הפרה ומתה\u0004 — \u0003פטור. ואילו שומר חנם לא קתני\u0004 \u0005[שנה]\u0006 כאן, משמע שאינו נפטר בבעלים!","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך רצונך לדייק; \u0003שומר שכר מי קתני\u0004 \u0005[האם שנה\u0006 פה\u0005]?\u0006","\u0003אלא\u0004 חייב אתה להסביר כי ה\u0003תנא מילתא\u0004 \u0005[דבר]\u0006"],["\u0003דכתיבא בהדיא\u0004 \u0005[שנאמר במפורש]\u0006 בתורה — \u0003קתני\u0004 \u0005[שנה]\u0006 ואילו דבר \u0003דאתיא מדרשא\u0004 \u0005[שבא,\u0006 שנלמד \u0005מדרשה]\u0006 בלבד — \u0003לא קתני\u0004 \u0005[שנה].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו בברייתא: \u0003שאלה ושאל בעליה עמה,\u0004 או \u0003שכרה ושכר בעליה עמה,\u0004 או \u0003שאלה ושכר בעליה עמה,\u0004 או \u0003שכרה ושאל בעליה עמה, אף על פי שהבעלים עושין מלאכה במקום אחר, ומתה\u0004 — \u0003פטור.\u0004","כדי להסביר את ההוכחה מעירים תחילה כי \u0003סברוה\u0004 \u0005[סברו,\u0006 הבינו\u0005]\u0006 אותם מציעים כי \u0003הא מני\u0004 \u0005[\u0006הברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: שוכר כשומר שכר דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 ואם כן, \u0003והא\u0004 \u0005[והרי]\u0006 נמצא כי \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא קתני מילתא דאתיא מדרשא\u0004 \u0005[שנה\u0006 בכל זאת \u0005דבר שבא,\u0006 שנלמד, \u0005מדרשה]\u0006 \u0003ואילו שומר חנם לא קתני\u0004 \u0005[שנה],\u0006 משמע שאין דין זה כשומר חנם!","ודוחים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: שוכר כשומר חנם דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003ו\u0004לכן \u0003תנא\u0004 \u0005[שנה]\u0006 הלכה זו ב\u0003שומר חנם, והוא הדין לשומר שכר.\u0004","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003כדמחליף\u0004 \u0005[כפי שמחליף]\u0006 את השיטות \u0003רבה בר אבוה ותני\u0004 \u0005[ושונה]\u0006 היפך בגרסה שבידינו: \u0003שוכר כיצד משלם?\u0004 — \u0003ר' מאיר אומר: כשומר שכר\u0004 ו\u0003ר' יהודה אומר כשומר חנם.\u0004 ולשאלתנו לא נמצא איפוא תשובה סופית.","\u0003אמר רב המנונא: לעולם הוא,\u0004 השומר, \u0003חייב עד שתהא פרה וחורש בה, חמור ומחמר אחריה, ועד שיהו בעלים\u0004 מצויים עמו \u0003משעת שאילה עד שעת שבורה ומתה,\u0004 כלומר עד שעת האונס. \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור\u0006 הוא\u0005]\u0006 שיש לפרש \u0003\"בעליו עמו\"\u0004 — \u0003אכולה מילתא\u0004 \u0005[על כל הדבר]\u0006 \u0003משמע,\u0004 כלומר, מה שנאמר \"אם בעליו עמו\" מתייחס לכל המשך הדברים הכתוב שם, ולא למאורע אחד בלבד.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רבא\u0004 ממה ששנינו: \u0003שאלה ושאל בעליה עמה,\u0004 או \u0003שכרה ושכר בעליה עמה,\u0004 או \u0003שכרה ושאל בעליה עמה,\u0004 או \u0003שאלה ושכר בעליה עמה, אף על פי שהבעלים עושין מלאכה במקום אחר ומתה\u0004 — \u0003פטור. מאי לאו\u0004 \u0005[האם לא]\u0006 \"במקום אחר\" כוונתו \u0003במלאכה אחרת?\u0004","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003באותה מלאכה.\u0004 ושואלים: \u0003אלא,\u0004 אם כן, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקום אחר\"?\u0004 ומסבירים: הכוונה היא כגון שהבהמה חורשת \u0003דקא מרפי ואזיל קמה\u0004 \u0005[שזה\u0006 הבעלים \u0005מרפה\u0006 את הקרקע \u0005והולך לפניה]\u0006 לסייע בחרישה, ונמצא שהוא עושה באותה מלאכה אף כי לא באותו מקום.","ומקשים: \u0003והא מדסיפא\u0004 \u0005[והרי\u0006 ממה ששנוי \u0005בסופה]\u0006 של הברייתא \u0003\"על גבה\",\u0004 נמצא כי \u0003הוי רישא\u0004 \u0005[הרי שבתחילתה]\u0006 מדובר \u0003במלאכה אחרת, דקתני סיפא\u0004 \u0005[ששנה בסופה]\u0006 של אותה ברייתא: \u0003שאלה ואחר כך שאל בעליה,\u0004 או \u0003שכרה ואחר כך שכר בעליה עמה, אף על פי שהבעלים חורשין על גבה ומתה\u0004 — \u0003חייב.\u0004 משמע שרק בקטע זה מדובר שהבעלים נמצאים באותה מלאכה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003רישא וסיפא\u0004 \u0005[\u0006גם \u0005בתחילה\u0006 וגם \u0005בסוף]\u0006 מדובר שהבעלים עוסקים \u0003באותה מלאכה,\u0004 ושינוי הלשון יש לו טעם, כי \u0003רישא רבותא קא משמע לן, וסיפא רבותא קא משמע לן\u0004 \u0005[בתחילה רבותה,\u0006 דבר גדול וחדש, \u0005השמיע לנו. בסוף רבותה השמיע לנו].\u0006 ומסבירים: \u0003רישא רבותא קא משמע לן\u0004 \u0005[בראשונה רבותה\u0006 וחידוש \u0005השמיע לנו]\u0006 \u0003דאף על גב דלאו\u0004 \u0005[שאף על פי שלא]\u0006 \u0003על גבה\u0004 ממש \u0003אלא באותה מלאכה,\u0004 \u0003כיון דהוו\u0004 \u0005[שהיו]\u0006 \u0003בעלים בשעת שאילה\u0004 — \u0003פטור. וסיפא רבותא קא משמע לן\u0004 \u0005[ובסופה רבותה השמיע לנו]\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שהיו \u0003על גבה\u0004 ממש, כיון ש\u0003לא היו בעלים בשעת שאילה\u0004 — \u0003חייב.\u0004","על הסבר זה תוהים: \u0003האי מאי\u0004 \u0005[זה מה הוא]\u0006 מה טיבו של תירוץ זה?! \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ומפרש כי \u0003רישא\u0004 \u0005[ראשה]\u0006 של הברייתא כשהבעלים עוסקים ממש \u0003במלאכה אחרת, וסיפא\u0004 \u0005[וסופה]\u0006 \u0003באותה מלאכה\u0004 — \u0003היינו רבותא\u0004 \u0005[זהו החידוש],\u0006","\u0003אלא אי אמרת רישא וסיפא\u0004 \u0005[אם אומר אתה שראשה וסופה]\u0006 \u0003באותה מלאכה, מאי רבותא\u0004 \u0005[מה הרבותה,\u0006 החידוש, בדבר\u0005]?\u0006 הלא \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003באותה מלאכה הוי\u0004 \u0005[הוא]!\u0006","\u0003ועוד,\u0004 הלא \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003ממשמע שנאמר \"אם בעליו עמו לא ישלם\"\u0004 (שמות כג, יד) \u0003איני יודע\u0004 בעצמי ההיפך \u0003שאם בעליו אין עמו שלם ישלם? אלא\u0004 אם כן \u0003מה\u0004 בכל זאת \u0003תלמוד לומר\u0004 במפורש בכתוב \u0003\"בעליו אין עמו\u0004 שלם ישלם\u0003\"\u0004 (שם יג) — בא הכתוב \u0003לומר לך:\u0004 אם \u0003היה עמו בשעת שאילה\u0004 — \u0003אין צריך להיות עמו בשעת שבורה ומתה, היה עמו בשעת שבורה ומתה\u0004 — \u0003צריך להיות עמו בשעת שאילה.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 בנושא זה: \u0003ממשמע שנאמר \"בעליו אין עמו שלם ישלם\"\u0004 (שם) \u0003איני יודע שאם בעליו עמו לא ישלם? אלא מה תלמוד לומר \"אם בעליו עמו\"\u0004 — \u0003לומר לך: כיון שיצאה מרשות משאיל שעה אחת בבעלים ומתה\u0004 — \u0003פטור.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב המנונא,\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה היא]\u0006 ונדחו דבריו.","ומעירים: \u0003אביי סבר לה\u0004 \u0005[אביי היה סבור]\u0006 בפירוש המקראות \u0003כ\u0004שיטת \u0003ר' יאשיה,\u0004 שדברים שלא נאמר במפורש שהם מפורטים יש לראותם כמחוברים יחד, \u0003ומתרץ לקראי\u0004 \u0005[והיה מיישב את הכתובים]\u0006 \u0003כ\u0004שיטת \u0003ר' יאשיה. רבא סבר לה כ\u0004שיטת \u0003ר' יונתן\u0004 שדנים כל דבר לעצמו כל עוד לא נתחבר במפורש, \u0003ומתרץ\u0004 \u0003לקראי\u0004 \u0005[את המקראות]\u0006 \u0003כ\u0004שיטת \u0003ר' יונתן.\u0004","ומפרטים: \u0003אביי סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יאשיה ומתרץ לקראי\u0004 \u0005[ומיישב את הכתובים]\u0006 \u0003כ\u0004שיטת \u0003ר' יאשיה\u0004 באופן זה: נאמר \u0003\"בעליו אין עמו שלם ישלם\", טעמא דליתיה בתרוייהו\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שאינו בשניהם],\u0006 לא בשעת שאילה ולא בשעת שבורה, \u0003הא איתיה בחדא וליתיה בחדא\u0004 \u0005[אבל\u0006 אם \u0005ישנו באחת ואיננו באחת]\u0006 — \u0003פטור.\u0004","ויש להקשות: \u0003הא כתיב\u0004 \u0005[\u0006ו\u0005הרי נאמר]\u0006 \u0003\"אם בעליו עמו לא ישלם\"\u0004 ומכאן, \u0003טעמא דאיתיה בתרוייהו, הא אי איתיה בחדא וליתיה בחדא\u0004 \u0005[הטעם,\u0006 דווקא \u0005שישנו בשניהם, הרי אם היה באחת ואינו באחת]\u0006 — \u0003מחייב\u0004 \u0005[הריהו חייב].\u0006 ויש כאן לכאורה סתירה פנימית!","ויש לישב ולומר כי דבר זה בא \u0003לומר לך\u0004 שאם \u0003היה עמו\u0004 הבעלים \u0003בשעת שאילה\u0004 — \u0003אינו צריך להיות עמו בשעת שבורה ומתה,\u0004 אבל אם \u0003היה עמו בשעת שבורה ומתה\u0004 — \u0003צריך להיות עמו בשעת שאילה.\u0004"],["\u0003רבא סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יונתן ומתרץ לקראי\u0004 \u0005[ומיישב את הכתובים]\u0006 \u0003כ\u0004שיטת \u0003ר' יונתן,\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 ממה שנאמר \u0003\"אם בעליו עמו לא ישלם\"\u0004 (שמות כב, יד). \u0003משמע\u0004 מצד אחד \u0003דאיתיה בתרוייהו\u0004 \u0005[שישנו בשניהם],\u0006 בשעת שאילה ובשעת שכירה, \u0003ומשמע נמי\u0004 \u0005[גם כן]\u0006 \u0003דכי איתיה בחדא וליתיה בחדא\u0004 \u0005[שאם ישנו באחת ואיננו באחת]\u0006 \u0003פטור.\u0004","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"בעליו אין עמו שלם ישלם\"\u0004 (שם יג) — \u0003משמע דליתיה בתרוייהו\u0004 \u0005[שאיננו בשניהם],\u0006 ו\u0003משמע נמי\u0004 \u0005[גם כן]\u0006 \u0003דכי איתיה בחדא וליתיה בחדא\u0004 \u0005[שאם ישנו באחת ואיננו באחת]\u0006 — \u0003חייב,\u0004 ויש כאן איפוא סתירה.","אלא בא הכתוב \u0003לומר לך:\u0004 אם \u0003היה עמו בשעת שאלה\u0004 — \u0003אין צריך להיות עמו בשעת שבורה ומתה, היה עמו בשעת שבורה ומתה\u0004 — אין די בזה אלא \u0003צריך להיות עמו בשעת שאלה.\u0004","ומקשים: \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואתרץ את הסתירה שבמקראות להיפך: שאם היה בשעת שבירה — נפטר, ולא בשעת שאילה! ומתרצים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003שאלה עדיפא\u0004 — שבה דווקא צריכים להיות הבעלים, \u0003משום דקא מייתי לה לרשותיה\u0004 \u0005[שהרי מביא אותה לרשותו]\u0006 של השואל מאותה שעה.","ודוחים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003שבורה ומתה עדיפא\u0004 \u0005[עדיף\u0006 אז\u0005],\u0006 \u0003שכן חייב באונסין!\u0004","ומשיבים: אינו כן, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא שאלה\u0004 — \u0003שבורה ומתה מאי עביד\u0004 \u0005[מה עושה]?,\u0006 ודוחים: זו אינה ראיה, שהרי \u0003ואי לאו\u0004 \u0005[ואם לא\u0006 היתה\u0005]\u0006 \u0003שבורה ומתה,\u0004 ב\u0003שאלה מאי עביד\u0004 \u0005[מה עשה]\u0006 שהרי אז אין כל בעיה. ודוחים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003שאלה עדיפא\u0004 \u0005[עדיפה]\u0006 ומדוע — \u0003שכן חייב\u0004 באותה שעה \u0003במזונותיה.\u0004","\u0003רב אשי\u0004 סבור שאפשר ללמוד מלשון הכתוב, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכי ישאל איש מעם רעהו\"\u0004 (שם יג), \u0003ו\u0004משמע ש\u0003לא\u0004 היה \u0003רעהו עמו\u0004 — אז \u0003שלם ישלם, הא\u0004 \u0005[הרי]\u0006 אם היה \u0003רעהו עמו\u0004 — \u0003פטור.\u0004","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדיוק הלשון אנו למדים, מה שנאמר במפורש \u0003\"בעליו אין עמו\"\u0004 (שם), \u0003ו\"אם בעליו עמו\"\u0004 (שם יד) \u0003למה לי?\u0004 שהרי הכל נלמד מפסוק ראשון! ומסבירים: \u0003אי לאו הנך הוה אמינא\u0004 \u0005[אם לא אלה הייתי אומר]:\u0006 \u0003האי אורחיה דקרא\u0004 \u0005[זה דרכו של הכתוב]\u0006 \u0003הוא\u0004 לומר \"מעם רעהו\" ולא הייתי לומד מכאן הלכה, ולכן היה צריך להדגיש במפורש, ללמדנו שיש בכך כוונה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא\u0004 בדיני שאילה: \u0003שאלה\u0004 את הבהמה \u0003לרבעה,\u0004 כדי לרבוע אותה, שעושה בה איסור חמור מן התורה, \u0003מהו\u0004 הדין? האם שאלה צריך להיות \u0003כדשיילי אינשי בעינן ולהכי\u0004 \u0005[\u0006\u0005כמו ששואלים\u0006 כרגיל \u0005בני אדם, ו\u0006לצורך \u0005זה]\u0006 \u0003לא שיילי אינשי\u0004 \u0005[שואלים אנשים],\u0006 \u0003או דלמא טעמא מאי\u0004 \u0005[שמא הטעם מה הוא]\u0006 שהשואל חייב — \u0003משום\u0004 שיש לו \u0003הנאה\u0004 מן הבהמה, \u0003והאי נמי, הא אית ליה\u0004 \u0005[וזה גם כן, הרי יש לו]\u0006 \u0003הנאה.\u0004","ושאלה דומה: \u0003שאלה ליראות בה,\u0004 ששאל בהמה מחבירו לא לעבודה או לשימוש, אלא שייראה על ידי כך עשיר יותר, \u0003מהו\u0004 הדין? האם התחייבות \u0003ממונא בעינן והאיכא\u0004 \u0005[\u0006ל\u0005ממון צריכים אנו, ויש כאן],\u0006 \u0003או דלמא ממונא דאית ליה\u0004 \u0005[שמא ממון שיש לו]\u0006 \u0003הנאה\u0004 ממשית \u0003מיניה בעינן וליכא\u0004 \u0005[ממנו צריכים אנו, ואין כאן]?\u0006","ועוד: \u0003שאלה לעשות בה\u0004 מלאכה \u0003פחות מ\u0004שווה \u0003פרוטה, מהו\u0004 הדין? האם \u0003ממונא בעינן ואיכא\u0004 \u0005[ממון,\u0006 משהו שווה כסף, \u0005צריכים אנו, ויש כאן],\u0006 שהרי המלאכה שעשתה שווה משהו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 \u0003פחות מ\u0004שווה \u0003פרוטה\u0004 — \u0003לא כלום הוא.\u0004","וכן: אם \u0003שאל שתי פרות\u0004 יחד \u0003לעשות בהן\u0004 דבר השווה \u0003פרוטה, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003שואל ומשאיל, ואיכא\u0004 \u0005[ויש כאן]\u0006 דין ממון, שהרי קיבל השואל מן המשאיל הנאה של שווה פרוטה, \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 ה\u0003פרות\u0004 \u0003וכל חדא וחדא ליכא ממונא\u0004 \u0005[ובכל אחת ואחת\u0006 מהן \u0005אין\u0006 כאן צד של \u0005ממון]?\u0006 שפחות מפרוטה אינו נחשב ממון!","ויש לשאול עוד: \u0003שאל\u0004 משני \u0003שותפים\u0004 יחד \u0003ונשאל לו\u0004 לעבודה רק \u0003אחד מהן מהו\u0004 הדין? האם \u0003כולו \"בעליו\" בעינן\u0004 \u0005[צריכים אנו]\u0006 — \u0003והא ליכא\u0004 \u0005[והרי אין כאן],\u0006 שהרי בעליו שנים הם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מההוא פלגא דידיה מיהא מיפטר\u0004 \u0005[מאותה מחצית שלו,\u0006 של אותו שותף, \u0005על כל פנים נפטר]\u0006 השואל?","ועוד שאלה: \u0003שותפים ששאלו\u0004 חפץ מאחר \u0003ונשאל\u0004 בעל החפץ \u0003לאחד מהן, מהו\u0004 הדין? האם \u0003כולו שואל בעינן, וליכא\u0004 \u0005[צריכים אנו, ואין כאן],\u0006 \u0003או דלמא בההיא פלגא דשיילי מיהת מיפטר\u0004 \u0005[שמא באותה מחצית ששאלו על כל פנים\u0006 הוא \u0005נפטר]?\u0006","וכן: \u0003שאל מהאשה\u0004 דבר מה \u0003ונשאל בעלה\u0004 של האשה לעשות לו מלאכה, או \u0003אשה ששאלה\u0004 חפץ \u0003ונשאל\u0004 בעליו \u0003לבעל, מהו\u0004 הדין? ובשתי שאלות אלה, הבעיה המרכזית היא האם \u0003קנין פירות\u0004 (כקנין הבעל בנכסי מלוג של האשה) \u0003כקנין גוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי\u0004 עוד שאלה מעין אלו: \u0003האומר לשלוחו צא והשאל לי\u0004 (עבורי) לשואל \u0003עם פרתי, מהו\u0004 הדין? האם \u0003\"בעליו\" ממש בעינא\u0004 \u0005[צריכים אנו]\u0006 כדי לפטור את השואל, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 אף לענין זה \u0003שלוחו של אדם כמותו, ואיכא\u0004 \u0005[ויש כאן]\u0006 איפוא \"בעליו\"?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו של]\u0006 \u0003רב אויא לרב אשי:\u0004 בעיה זו בענין \u0003בעל\u0004 קשורה ב\u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יוחנן וריש לקיש\u0004 בענין אחר, והשאלה בענין \u0003שליח – פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יונתן ור' יאשיה.\u0004","ומסבירים: \u0003בעל, פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יוחנן וריש לקיש; דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה זו: \u0003המוכר שדהו לחבירו\u0004 ולא מכר את גוף השדה אלא \u0003לפירות\u0004 שיהנה הקונה מפירות השדה, \u0003ר' יוחנן אומר:\u0004 הקונה, בעל הפירות, \u0003מביא\u0004 ביכורים \u0003וקורא\u0004 עליהם את מקרא בכורים הכתוב בתורה (דברים כו, ה–י), כיון שבפועל הוא שלו, ו\u0003ריש לקיש אומר: מביא\u0004 אמנם ביכורים \u0003ו\u0004אולם \u0003אינו קורא\u0004 עליהם מקרא ביכורים,","שהרי גוף השדה אינו שלו. ומסבירים: \u0003ר' יוחנן אומר: מביא וקורא,\u0004 כי לדעתו \u0003קנין פירות\u0004 שיש לו כל ההנאה — \u0003כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 \u0003וריש לקיש אומר: מביא ואינו קורא,\u0004 כי \u0003קנין פירות לאו\u0004 \u0005[לא]\u0006 \u0003כקנין הגוף דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","בענין \u0003שליח פלוגתא\u0004 \u0005[מחלוקת]\u0006 היא של \u0003ר' יונתן ור' יאשיה: דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאפוטרופוס\u0004 הממונה על ביתו: \u0003כל נדרים שתהא אשתי נודרת מכאן\u0004 (מעכשיו) ו\u0003עד שאבא ממקום פלוני\u0004 — \u0003הפר לה,\u0004 שמניתיך שליח להפיר נדרים כמוני, \u0003והפיר לה\u0004 האפוטרופוס, \u0003יכול יהו\u0004 הנדרים \u0003מופרים\u0004 על ידי כך — \u0003תלמוד לומר,\u0004 שכתוב בהדגשה: \u0003\"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד), כלומר, בעלה ולא אחר, אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: מצינו בכל מקום ששלוחו של אדם כמותו.\u0004 ואף לענין הפרת נדרים. זו היא הבעיה אם שליחו כמותו לכל ענין.","ושאלה נוספת בבעיות אלה: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב עיליש לרבא: האומר לעבדו צא והשאל עם פרתי, מהו\u0004 הדין? ושאלה זו מורכבת יותר, \u0003תיבעי למאן דאמר\u0004 \u0005[תשאל\u0006 בעיה זו \u0005ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שלוחו של אדם כמותו\u0004 לגמרי, \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שלוחו של אדם אינו כמותו.\u0004 כיצד?","\u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003שלוחו של אדם כמותו,\u0004 שאפשר לומר: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003שליח\u0004 שהוא כמותו משום \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003מצוה הוא,\u0004 שהוא מחוייב במצוות כמותו. \u0003אבל עבד דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003מצוה הוא,\u0004 שאינו מחוייב במצוות כמוהו — \u0003לא,\u0004 אינו נעשה כמותו לגמרי לענין זה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין שלוחו של אדם כמותו, הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003שליח\u0004 שהוא אדם זר, \u0003אבל עבד\u0004 הוא יותר משליח, כי \u0003יד עבד כיד רבו דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003יד עבד כיד רבו דמיא\u0004 \u0005[נחשבת].\u0006","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא\u0004 בדיני שאילה: \u0003בעל בנכסי אשתו\u0004 שקיבל אותם כנכסי מלוג עם הנישואין"],["\u0003שואל הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]\u0006 עליהם, \u0003או שוכר הוי\u0004 \u0005[הוא\u0006 נחשב\u0005]?\u0006","\u0003אמר רבא: לפום חורפא\u0004 \u0005[לפי החריפות]\u0006 \u0003שבשתא\u0004 \u0005[השיבוש,\u0006 הטעות\u0005],\u0006 שמפורסם היה רמי בר חמא בחריפותו, אבל חריפות זו גרמה לו להשתבש כאן, ומדוע — \u0003מה נפשך\u0004 \u0005[רצונך],\u0006 כלומר, בכל צד שתרצה אין אפשרות לומר זאת, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003שואל הוי\u0004 \u0005[הוא]\u0006 — הלא \u0003שאלה בבעלים היא,\u0004 שהרי אשתו נמצאת עמו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003שוכר הוי\u0004 \u0005[הוא]\u0006 — \u0003שכירות בבעלים היא.\u0004","\u0003אלא\u0004 אין מקום לשאלה בנוסח זה, ויש לתקנה ולומר \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו השאלה]\u0006 \u0003לרמי בר חמא\u0004 היתה זו במקרה מיוחד: \u0003דאגר מינה\u0004 \u0005[ששכר ממנה]\u0006 קודם \u0003פרה והדר נסבה\u0004 \u0005[ואחר כך נשא אותה\u0006 לאשה\u0005],\u0006 האם \u0003שואל הוי\u0004 \u0005[הוא],\u0006 \u0003או שוכר הוי\u0004 \u0005[הוא]?\u0006","וצדדי השאלה: \u0003שואל הוי\u0004 \u0005[הוא]\u0006 הבעל, \u0003ואתיא\u0004 \u0005[ובאה]\u0006 \u0003שאלה בבעלים מפקעא\u0004 \u0005[\u0006ו\u0005מפקיעה]\u0006 אותה \u0003שכירות\u0004 ראשונה שהיתה \u0003שלא בבעלים,\u0004 ואין לו אחריות ־אונסים על הפרה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003שוכר הוי\u0004 \u0005[הוא]\u0006 גם כעת \u0003ושכירות כדקיימא קיימא\u0004 \u0005[כפי שעמדה עמדה]\u0006 ולא נעשה שינוי בה?","ומקשים: \u0003ומאי שנא\u0004 \u0005[ומה שונה],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003שואל הוי\u0004 \u0005[הוא]\u0006 \u0003דאתי\u0004 \u0005[שבאה]\u0006 \u0003שאלה בבעלים מפקעא\u0004 \u0005[מפקעת]\u0006 \u0003שכירות שלא בבעלים,\u0004 אם כן \u0003אי\u0004 \u0005[אם]\u0006 \u0003שוכר נמי הוי\u0004 \u0005[גם כן הוא]\u0006 \u0003תיתי\u0004 \u0005[תבוא]\u0006 \u0003שכירות בבעלים תיפוק\u0004 \u0005[\u0006ו\u0005תוציא]\u0006 \u0003שכירות שלא בבעלים!\u0004","\u0003אלא\u0004 יש לדחות נוסח זה ולומר: \u0003כי קא מיבעיא\u0004 \u0005[כאשר נסתפקה]\u0006 \u0003לרמי בר חמא\u0004 היה במקרה כגון זה: \u0003דאגרא איהי\u0004 \u0005[ששכרה היא]\u0006 \u0003פרה מעלמא\u0004 \u0005[מהעולם],\u0006 מאדם אחר, \u0003והדר נסבה\u0004 \u0005[\u0006\u0005ואחר כך נשא אותה\u0006 בעלה לאשה\u0005],\u0006","\u0003ואליבא דרבנן דאמרי\u0004 \u0005[ולפי דעת חכמים האומרים]\u0006 שאם שכר אדם דבר, והשאילו לאחר, ואבד מן העולם — \u0003שואל משלם לשוכר,\u0004 אם כן \u0003לא תיבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך\u0004 שאלה זו, ש\u0003ודאי\u0004 אין לבעל אחריות כלפי אשתו, שדבר זה דינו כ\u0003שאילה בבעלים היא.\u0004","\u0003כי תיבעי\u0004 \u0005כאשר תישאל\u0006 \u0003לך\u0004 השאלה, הרי זו \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יוסי,\u0004 ש\u0003אמר: תחזיר פרה לבעלים הראשונים\u0004 ואין מביאים בחשבון את השוכר, שהיה כעין מתווך כאן, ולכן יש מקום לשאול: \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם \u0003שואל הוי\u0004 \u0005[הוא],\u0006 \u0003או שוכר הוי\u0004 \u0005[הוא]?\u0006","\u0003אמר רבא:\u0004 לאמיתו של דבר \u0003בעל לא שואל הוי\u0004 \u0005[הוא]\u0006 \u0003ולא שוכר הוי\u0004 \u0005[הוא],\u0006 \u0003אלא לוקח\u0004 (קונה) \u0005[הוא],\u0006 שדינו כאילו קנה מאשתו את רכושה, כפי שאפשר להסיק מדברי \u0003ר' יוסי בר' חנינא.\u0004 ש\u0003אמר ר' יוסי בר' חנינא, באושא התקינו\u0004 תקנה זו: \u0003האשה שמכרה בנכסי מלוג בחיי בעלה,\u0004 שהם נכסים שהיא מביאה לבעלה מבית אביה, ונכסים אלה נשארים קניינה של האשה, אבל הבעל אוכל (\"מולג\") את הפירות שהם מביאים. וכיון שגוף הנכסים שייכים לאשה יכולה היא למכרם לאחרים, שאם ימות בעלה יעברו הנכסים לרשות הקונה. \u0003ו\u0004אם \u0003מתה\u0004 היא, כיון שבעלה יורש אותה מדין תורה \u0003הבעל מוציא מיד הלקוחות\u0004 (ומחזיר להם את הכסף ששילמו), שאנו רואים אותו כאילו הוא היה הקונה הראשון. ואם כן דינו בנכסי אשתו כקונה (\"לוקח\") ולא כשומר.","בענין קרוב לנושא שדנו בו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: בעל בנכסי אשתו\u0004 שהביאה לו נכסי מלוג ובין הנכסים הללו היו מעורבים חפצים או כספים של הקדש, וכיון שלא היו ידועים השתמשו בהם לצורכי חולין. והשאלה היא \u0003מי מעל?\u0004 מי נחשב כמוציא את הנכסים הללו לעצמו?","\u0003אמר רבא: מאן לימעול\u0004 \u0005[מי ימעל]\u0006 כאן? אם תאמר \u0003לימעול\u0004 \u0005[שימעול]\u0006 שייחשב ה\u0003בעל\u0004 כמועל, אולם הוא נכסים \u0003דהיתרא ניחא ליה דליקני\u0004 \u0005[של היתר,\u0006 \u0005נוח,\u0006 רצוי, \u0005לו לקנות]\u0006 שהוא מרוצה בקנייתם על ידי הנישואין, אבל נכסים שיש בשימושם משום \u0003איסורא לא ניחא ליה דליקני\u0004 \u0005[איסור אינו נוח לו לקנות]\u0006 ולא רצה בקנין זה, ולא נקנו לו כספי ההקדש.","ואם תאמר כי \u0003תימעול איהי\u0004 \u0005[היא,\u0006 האשה\u0005]\u0006 שכיון שנישאה העביר את הנכסים לרשות בעלה, הרי היא \u0003דהיתרא נמי\u0004 \u0005[של היתר גם כן]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לה דליקני\u0004 \u0005[שיקנה]\u0006 הבעל, שהרי הקניית נכסים אלה לבעל תקנת חכמים היא ולא נעשתה מרצונה שלה.","ואם תאמר \u0003כי\u0004 \u0003נימעלו\u0004 \u0005[שימעלו]\u0006 \u0003בית דין,\u0004 שהם שתיקנו תקנה זו והם כמקנים לבעל את הנכסים, ואולם \u0003כי עבדו רבנן תקנתא\u0004 \u0005[כאשר עשו חכמים תקנה]\u0006 \u0003ואמרו: בעל לוקח הוי\u0004 \u0005[הוא]\u0006 הרי תיקנו זאת \u0003להיתרא\u0004 \u0005[להיתר],\u0006 \u0003לאיסורא\u0004 \u0005[לאיסור]\u0006 \u0003לא עביד רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה]\u0006 להקנות לו דבר אסור. ואם כן, בעצם העברת הנכסים לרשות הבעל אין איש שימעל.","\u0003אלא אמר רבא:\u0004 ה\u0003בעל\u0004 הוא ש\u0003מעל לכשיוציא\u0004 בפועל את הכסף וישתמש בו לחולין, \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 ב\u0003מוציא מעות הקדש\u0004 לחולין בשגגה לצרכו, שכאשר מוציא — מעל.","ועוד בדיני שאילה בכללם, \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: \u0003כחש בשר\u0004 של בהמה ששאל \u0003מחמת מלאכה\u0004 שעשה בה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין, האם צריך השואל לפצות את בעל הבהמה?","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד מהחכמים]\u0006 \u0003ורב חלקיה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא שמיה\u0004 \u0005[שמו]:\u0006 האם \u0003מכלל\u0004 זה תלמד \u0003דכי\u0004 \u0005[שכאשר]\u0006 \u0003מתה\u0004 הבהמה \u0003מחמת מלאכה מחייב\u0004 \u0005[הריהו חייב]\u0006 לשלם עבורה? \u0003נימא\u0004 \u0005[שיאמר]\u0006 השואל: \u0003לאו לאוקמא בכילתא שאילתה\u0004 \u0005[לא\u0006 כדי \u0005להעמידה בכילה,\u0006 שתנוח בה, \u0005שאלתי אותה],\u0006 ואם אירע בה דבר מחמת המלאכה — הלא לצורך זה נלקחה!","\u0003אלא אמר רבא: לא מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שאם \u0003כחש בשר מחמת מלאכה\u0004 שהוא \u0003פטור, אלא אפילו מתה מחמת מלאכה נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור. דאמר ליה\u0004 \u0005[שאומר לו]\u0006 השואל: \u0003לאו לאוקמא בכילתא שאילתה\u0004 \u0005[לא כדי להעמידה בכילה שאלתיה]\u0006 אלא כדי להשתמש בה.","מסופר: \u0003ההוא גברא דשאיל נרגא מחבריה, איתבר\u0004 \u0005[אדם אחד שאל גרזן מחברו ונשבר]\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לדין, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003זיל אייתי סהדי דלאו שנית ביה, ואיפטר\u0004 \u0005[לך הבא עדים שלא שינית בו,\u0006 בשמושו מן הרגיל, \u0005והפטר]\u0006 מלשלם. שהרי כאמור אם מחמת מלאכה נפגם ונשבר — פטור.","ושואלים: \u0003ואי ליכא סהדי מאי\u0004 \u0005[ואם אין עדים מה]\u0006 הדין? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה שאירע במעשה כזה, \u0003ההוא גברא דשאיל נרגא מחבריה ואיתבר\u0004 \u0005[אדם אחד שאל גרזן מחברו ונשבר],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב\u0004 לדין, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003זיל שלים ליה נרגא מעליא\u0004 \u0005[לך שלם לו גרזן מעולה]\u0006 שלם ויפה.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא ורב אסי לרב:\u0004"],["\u0003דינא הכי\u0004 \u0005[כך הדין]?\u0006 \u0003ושתיק\u0004 \u0005[ושתק],\u0006 לא ענה.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 בענין זה \u0003כ\u0004שיטת \u0003רב כהנא ורב אסי, דמהדר ליה תבריה וממליא ליה דמי\u0004 \u0005[שמחזיר לו את\u0006 הכלי \u0005השבור וממלא לו את דמי\u0006 ההפסד בכסף\u0005].\u0006","ומסופר עוד: \u0003ההוא גברא דשאיל דוולא מחבריה, איתבר\u0004 \u0005[אדם אחד שאל דלי מחבירו,\u0006 ו\u0005נשבר].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב פפא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא לשואל: \u0003אייתי סהדי\u0004 \u0005[הבא עדים]\u0006 ש\u0003לא שנית ביה\u0004 \u0005[שינית בו]\u0006 בשימושו, \u0003ואיפטר\u0004 \u0005[והפטר],\u0006 שדבר זה דינו כמתה מחמת מלאכה.","\u0003ההוא גברא דשאיל שונרא מחבריה, חבור עליה עכברי וקטלוהו\u0004 \u0005[אדם אחד שאל חתול מחבירו\u0006 לצוד עבורו עכברים, \u0005חברו עליו העכברים והרגוהו].\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אשי וקמיבעיא ליה\u0004 \u0005[ונסתפק לו]:\u0006 \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מה\u0006 דינו\u0005]?\u0006 האם \u0003כי\u0004 \u0005[כמו]\u0006 \u0003מתה מחמת מלאכה דמי\u0004 \u0005[נחשב],\u0006 \u0003או לא? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי; הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003אבימי מ\u0004העיר \u0003הגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: גברא דנשי קטלוהו\u0004 \u0005[גבר,\u0006 אדם, \u0005שנשים הרגוהו]\u0006 — \u0003לא דינא\u0004 \u0005[דין]\u0006 יש כאן \u0003ולא דיינא\u0004 \u0005[דיין],\u0006 שדבר זה הוא משונה, ואינו כדרכו כלל.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהמעשה לא כך היה אלא באופן אחר: שאותו חתול \u0003אכיל עכברי טובא וחביל ומית\u0004 \u0005[אכל\u0006 החתול \u0005עכברים הרבה\u0006 עד \u0005שלקה ומת].\u0006 \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אשי וקא\u0004 \u0005[והיה]\u0006 \u0003מעיין בה: כהאי גוונא מאי\u0004 \u0005[\u0006ב\u0005כגון זה מהו\u0006 הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר\u0004 \u0003אבימי מהגרוניא: גברא דנשי קטלוהו\u0004 \u0005[גבר,\u0006 אדם, \u0005שנשים הרגוהו]\u0006 מרוב בעילות שבעל — \u0003לא דינא\u0004 \u0005[דין]\u0006 יש כאן \u0003ולא דיינא\u0004 \u0005[דיין].\u0006","\u0003אמר רבא: הא מאן דבעי למישאל מידי מחבריה וליפטר\u0004 \u0005[מי שרוצה לשאול דבר מחבירו ולהפטר\u0006 מתשלום נזקים\u0005],\u0006 \u0003נימא ליה\u0004 \u0005[שיאמר לו]\u0006 למשאיל: \u0003אשקיין מיא\u0004 \u0005[השקה אותי מים]\u0006 \u0003דהוי\u0004 \u0005[שתהא זו]\u0006 \u0003שאילה בבעלים,\u0004 שהרי אם המשאיל עוסק עם השואל במלאכתו בזמן השאילה פטור השואל מנזקי אונס.","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003פקח הוא\u0004 המשאיל, \u0003נימא ליה\u0004 \u0005[שיאמר לו]:\u0006 \u0003שאיל ברישא והדר אשקייך\u0004 \u0005[שאל\u0006 ממני \u0005תחילה, ולאחר מכן אשקה אותך],\u0006 שאז השאילה אינה קשורה במלאכה, וחייב בכל הנזקים.","\u0003אמר רבא: מקרי דרדקי, שתלא, טבחא, ואומנא, ספר מתא\u0004 \u0005[מלמד תינוקות, שתלן\u0006 מומחה, \u0005טבח, מקיז דם,\u0006 ו\u0005סופר העיר]\u0006 (ערוך) \u0003כולהון בעידן עבידתייהו\u0004 \u0005[כולם בזמן עבודתם]\u0006 \u0003כשאילה בבעלים דמו\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","אגב כך מספרים: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: שאיל לן מר\u0004 \u0005[אדוני שאול לנו]\u0006 למלאכה, שהרי אתה מלמדנו תורה, ואם כן כל חפץ שנשאל ממך יהא דינו כשאלה בבעלים. \u0003אקפיד\u0004 \u0005[הקפיד]\u0006 רבא על כך, \u0003אמר להו\u0004 \u0005[להם]\u0006 לתלמידיו: וכי \u0003לאפקועי ממונאי קא בעיתו\u0004 \u0005[להפקיע את ממוני אתם רוצים]?!\u0006 \u0003אדרבה, אתון שאילתון\u0004 \u0005[להיפך, אתם שאולים]\u0006 \u0003לי.\u0004 שאתם כתלמידים מסייעים בידי לחזור ולשנן את תורתי, והראיה לדבר שאני הוא בעל הבית, ואתם כפועלי, ש\u0003אילו אנא מצי אישתמוטי לכו ממסכתא למסכתא\u0004 \u0005[אני יכול להשתמט לכם ממסכת למסכת],\u0006 שאינני חייב ללמדכם מה שאתם רוצים, \u0003אתון לא מציתו לאישתמוטי\u0004 \u0005[אתם אינכם יכולים להשתמט ממני]\u0006 ומה שמחליט אני ללמד — חייבים אתם ללמוד.","ומעירים: \u0003ולא היא\u0004 \u0005[ואינו כן],\u0006 כלומר, לאמיתו של דבר אין זו חלוקה מוחלטת, \u0003איהו שאיל להו ביומא דכלה\u0004 \u0005[הוא שאול להם בימי הכלה],\u0006 ימי הכינוס שבהם לומדים מסכת קבועה מראש, וראש הישיבה אומר את שיעוריו במסכת זו דווקא, ואינו יכול לדון בנושא אחר. \u0003אינהו שאילו ליה\u0004 \u0005[\u0006ו\u0005הם שאולים לו]\u0006 \u0003בשאר יומי\u0004 \u0005[הימים],\u0006 שאז יכול הוא לבחור במה שירצה.","מסופר: \u0003מרימר בר חנינא אוגר כודנייתא בי\u0004 \u0005[השכיר פרדה בבית]\u0006 \u0003חוזאי, נפק לדלויי טעונה בהדייהו\u0004 \u0005[יצא להרים את המשא עמם],\u0006 \u0003פשעו\u0004 \u0005[התרשלו]\u0006 השואלים \u0003בה,\u0004 בבהמה, \u0003ומית\u0004 \u0005[ומתה].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לדין, \u0003חייבינהו\u0004 \u0005[\u0006ו\u0005חייב אותם\u0006 לשלם\u0005].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא:\u0004 והלא \u0003פשיעה בבעלים היא,\u0004 שהרי בעל הפרדות היה עמם באותו מקום! \u0003איכסיף\u0004 \u0005[התבייש]\u0006 רבא על שפסק שלא כדין. \u0003לסוף איגלאי מילתא דלמיסר טעונה הוא דנפק\u0004 \u0005[לבסוף התברר הדבר שלבדוק את מטענה הוא שיצא],\u0006 כלומר, שלא בא לעזור להם, ולא היה עמם במלאכתם אלא בא לבדוק שלא יפשעו בטעינתה.","ומעירים: לגופו של דבר, \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שגם ב\u0003פשיעה בבעלים פטור,\u0004 ו\u0003משום הכי איכסיף\u0004 \u0005[כך התבייש],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שבפשיעה בבעלים \u0003חייב\u0004 השואל, \u0003אמאי איכסיף\u0004 \u0005[מדוע\u0006 אם כן \u0005התבייש]?\u0006","אלא לא כך היה המעשה, \u0003לא מיפשע פשעו\u0004 \u0005[שהתרשלו]\u0006 \u0003בה, אלא איגנובי איגנוב\u0004 \u0005[שנגנבה],\u0006 \u0003ומתה כדרכה בי\u0004 \u0005[בבית]\u0006 ה\u0003גנב הוי\u0004 \u0005[היתה].\u0006 \u0003ואתו לקמיה\u0004 \u0005[ובאו\u0006 לדין \u0005לפני]\u0006 \u0003רבא וחייבינהו\u0004 \u0005[וחייבם].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא:\u0004 הלא \u0003גניבה בבעלים היא:\u0004 ועל כן \u0003אכסיף\u0004 \u0005[התבייש].\u0006 \u0003לסוף איגלאי מילתא דלמיסר טעונה הוא דנפק\u0004 \u0005[לבסוף התברר הדבר שלבדוק את מטענה הוא שיצא]\u0006 ולא לעזור, ואם כן לא היו כאן בעלים בשעת מלאכה. ונמצא שיפה פסק מתחילה.","\u0003השואל את הפרה,\u0004 אם \u0003שאלה\u0004 מבעליה ל\u0003חצי יום ושכרה\u0004 ל\u0003חצי יום\u0004 האחר, וכן אם \u0003שאלה היום ושכרה למחר,\u0004 או \u0003שכר\u0004 פרה \u0003אחת\u0004 מאותו אדם \u0003ושאל\u0004 ממנו \u0003אחת, ומתה\u0004 הפרה ולא ברור איזה מהן מתה ומתי מתה. \u0003המשאיל אומר: שאולה מתה,\u0004 או במקרה האחר — \u0003ביום שהיתה שאולה מתה,\u0004"],["\u0003בשעה שהיתה שאולה מתה,\u0004 והוא טוען איפוא שיש להחזיר לו דמי הפרה. \u0003והלה\u0004 השואל־השוכר \u0003אומר: איני יודע\u0004 מתי אירע הדבר, במקרה כזה \u0003חייב\u0004 לשלם.","לעומת זאת, אם \u0003השוכר אומר: שכורה מתה,\u0004 או \u0003ביום שהיתה שכורה מתה,\u0004 או \u0003בשעה שהיתה שכורה מתה, והלה,\u0004 בעל הבהמה, \u0003אומר: איני יודע\u0004 — \u0003פטור.\u0004","\u0003זה אומר\u0004 בוודאות: ה\u0003שאולה\u0004 היא שמתה, \u0003וזה אומר:\u0004 ה\u0003שכורה\u0004 היא שמתה — \u0003ישבע השוכר ששכורה מתה.\u0004","\u0003זה אומר: איני יודע, וזה אומר: איני יודע\u0004 — \u0003יחלוקו.\u0004","ומדייקים: \u0003שמעת מיניה\u0004 \u0005[למד אתה מכאן]\u0006 ממשנה זו שאם בא אדם ותבע מחבירו: \u0003מנה לי ביד\u0004 \u0003ך\u0004 שאתה חייב לי, \u0003והלה,\u0004 הנתבע, \u0003אומר: איני יודע\u0004 — \u0003חייב\u0004 לשלם לו.","ושואלים: \u0003לימא תהוי תיובתא\u0004 \u0005[האם נאמר שתהא זו קושיה חמורה]\u0006 לדברי \u0003רב נחמן;\u0004 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: בא לחבירו ואמר לו \u0003\"מנה לי בידך\" והלה,\u0004 הנתבע, \u0003אומר: איני יודע.\u0004 \u0003רב הונא ורב יהודה אמרי\u0004 \u0005[אומרים]:\u0006 במקרה זה הנתבע \u0003חייב\u0004 לשלם. \u0003רב נחמן ור' יוחנן אמרי\u0004 \u0005[אומרים]\u0006 שהוא \u0003פטור!\u0004","ודוחים: כאן יש להסביר \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 \u0003רב נחמן\u0004 במקרה אחר: \u0003כגון שיש עסק שבועה ביניהן.\u0004 כלומר, בין הטוען והנטען יש גם התדיינות אחרת, שבשלה חייב הנתבע להשבע. ולכן, מאחר שהנתבע יש עליו חיוב שבועה, וכאן אינו יכול להשבע — שהרי איננו יודע — לכן חייב לשלם. שמי שנתחייב שבועה ואינו רוצה או אינו יכול להשבע — משלם, אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — \u0003כגון שיש עסק שבועה ביניהם.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[אין הוא בדיוק]\u0006 ענין \u0003זה של\u0004 \u0003עסק שבועה?\u0004 ומשיבים: \u0003כ\u0004דברי \u0003רבא,\u0004"]]};
